// Zusammenfassung Betriebstechnik – eigene Formulierungen und eigene Schaubilder
(window.TEXTBAND=window.TEXTBAND||{}).BT={
 title:'Betriebstechnik',
 src:'Zusammenfassung nach dem Lehrgangs-Textband',
 intro:'Betriebstechnik behandelt Kraft- und Arbeitsmaschinen, Fördertechnik, Instandhaltung, Schwachstellenanalyse, Energieversorgung, Aufstellung und Inbetriebnahme, Pneumatik, Hydraulik, elektrische Steuerungen und Lagerwirtschaft aus Sicht des Meisters. In der Prüfung zählen saubere Rechnungen (Leistung, Wirkungsgrad, Kräfte, Verfügbarkeit, OEE, Bestellmenge) und begründete Entscheidungen mit Blick auf Sicherheit, Recht, Kosten und Dokumentation.',
 ch:[
  {t:'Maschinen als technische Systeme',h:'Kraft-, Arbeitsmaschinen, Hebe- und Fördermittel, ihre Nutzung und ihr Funktionserhalt',pg:1,abb:[['Abb. 1.1 Funktion eines technischen Systems',1],['Abb. 1.2 Einteilung der Maschinen',2],['Abb. 1.3 Umwandlung der Energieform',2]],b:[
    {p:'Maschinen nehmen dem Menschen schwere oder eintönige Arbeit ab und machen Prozesse schneller und genauer. Um eine Maschine zu verstehen, betrachtet man sie als System mit Eingang, Umsetzung und Ausgang (EVA-Prinzip).'},
    {ul:['Eingang: Energie, Stoff oder Information wird zugeführt','Umsetzung: das System wandelt um (z. B. Strom in Drehbewegung, Rohteil in Fertigteil)','Ausgang: umgewandelte Energie, bearbeiteter Stoff, verarbeitete Information – plus unerwünschte Anteile wie Wärme, Lärm, Späne']},
    {tab:[['Maschinengruppe','Hauptfunktion','Beispiele'],['Kraftmaschine','setzt Energie um (in mechanische Arbeit)','Elektromotor, Verbrennungsmotor, Turbine, Hydro- und Druckluftmotor'],['Arbeitsmaschine','setzt Stoff um (fördern, formen, trennen, behandeln)','Pumpe, Verdichter, Werkzeugmaschine, Härteanlage, Förderer'],['Datenverarbeitende Anlage','setzt Information um','Steuerung, Rechner, Prüfsystem']]},
    {ul:['Kraftmaschinen nach Energiequelle: Wasserkraft-, Wärmekraft- und elektrische Maschinen; dazu hydraulische und pneumatische Motoren','Kraftmaschinen treiben Arbeitsmaschinen oder Fahrzeuge an','Arbeitsmaschinen nach Aufgabe: Fördermittel (Feststoffe, Flüssigkeiten, Gase), Werkzeugmaschinen (Werkstücke herstellen), Wärmebehandlungsanlagen (Stoffeigenschaften durch Wärme verändern)']},
    {bsp:{t:'Beispiel: Kompressorstation als System',b:['Eingang: elektrische Energie (ca. 45 kW) und Umgebungsluft','Umsetzung: Elektromotor (Kraftmaschine) treibt Schraubenverdichter (Arbeitsmaschine) an','Ausgang: Druckluft 7 bar als Energieträger für die Fertigung; Nebenausgang: viel Abwärme und Kondensat','Meister-Folgerung: Abwärme nutzen (Hallenheizung, Waschwasser) und Kondensat fachgerecht entsorgen – beides gehört zum Betrieb der Anlage dazu.']}},
    {merke:'Kraftmaschine = Energie wandeln, Arbeitsmaschine = Stoff bearbeiten oder fördern. Ein Antrieb besteht fast immer aus beiden.'}
  ]},
  {t:'Arbeit, Leistung, Energie und Wirkungsgrad',h:'Energieumwandlung in Kraftmaschinen',pg:3,abb:[['Abb. 1.4 Energieumwandlung mittels einer Pumpe',4],['Abb. 1.5 Energieumwandlung bei einem Wasserkraftwerk',4]],b:[
    {p:'Für Auslegung und Kostenrechnung braucht der Meister die physikalischen Grundgrößen sicher – inklusive Umstellen der Formeln. Energie ist gespeicherte Arbeitsfähigkeit; sie lässt sich übertragen, speichern und umwandeln, aber nicht vernichten.'},
    {fx:['W = F · s','Arbeit in Nm = J; Kraft F in N, Weg s in m']},
    {fx:['P = W / t = F · v','Leistung in W = J/s; dieselbe Arbeit in kürzerer Zeit bedeutet mehr Leistung']},
    {fx:['E_pot = m · g · h','Lageenergie in J; g = 9,81 m/s²']},
    {fx:['E_kin = ½ · m · v²','Bewegungsenergie in J']},
    {fx:['ρ = m / V;  v = s / t','Dichte in kg/m³ (Wasser ≈ 1000 kg/m³, Stahl ≈ 7850 kg/m³); Geschwindigkeit in m/s']},
    {fx:['η = P_ab / P_zu;  η_ges = η₁ · η₂ · η₃ …','Wirkungsgrad, immer kleiner als 1; bei Reihenschaltung multiplizieren']},
    {fx:['E_ges = E₁ + E₂ + … = konstant (ΔE = 0)','Energieerhaltungssatz für ein abgeschlossenes System']},
    {ul:['Energieformen: potenziell, kinetisch, elektrisch, chemisch, thermisch','1 J = 1 Nm = 1 Ws; 1 kWh = 3,6 MJ','Temperatur in °C oder K: 0 K = −273,15 °C; Temperaturdifferenzen sind in K und °C gleich groß','Typische Wirkungsgrade: Ottomotor ca. 30–35 %, Dieselmotor bis ca. 45 %, Elektromotor 85–97 %, Großtransformator bis 99 %']},
    {svg:{w:520,h:235,body:'<text x="40" y="78" text-anchor="middle" class="sk-t">P_zu</text><line x1="15" y1="90" x2="93" y2="90" class="sk-f" marker-end="url(#ar)"/><rect x="95" y="60" width="100" height="60" class="sk-body"/><text x="145" y="86" text-anchor="middle" class="sk-t">Motor</text><text x="145" y="106" text-anchor="middle" class="sk-t">η = 0,92</text><line x1="195" y1="90" x2="223" y2="90" class="sk-f" marker-end="url(#ar)"/><rect x="225" y="60" width="100" height="60" class="sk-body"/><text x="275" y="86" text-anchor="middle" class="sk-t">Getriebe</text><text x="275" y="106" text-anchor="middle" class="sk-t">η = 0,95</text><line x1="325" y1="90" x2="353" y2="90" class="sk-f" marker-end="url(#ar)"/><rect x="355" y="60" width="100" height="60" class="sk-body"/><text x="405" y="86" text-anchor="middle" class="sk-t">Pumpe</text><text x="405" y="106" text-anchor="middle" class="sk-t">η = 0,80</text><line x1="455" y1="90" x2="510" y2="90" class="sk-f" marker-end="url(#ar)"/><text x="485" y="78" text-anchor="middle" class="sk-t">P_ab</text><line x1="145" y1="120" x2="145" y2="158" class="sk-c" marker-end="url(#ar)"/><line x1="275" y1="120" x2="275" y2="158" class="sk-c" marker-end="url(#ar)"/><line x1="405" y1="120" x2="405" y2="158" class="sk-c" marker-end="url(#ar)"/><text x="145" y="178" text-anchor="middle" class="sk-t">Wärme</text><text x="275" y="178" text-anchor="middle" class="sk-t">Wärme</text><text x="405" y="178" text-anchor="middle" class="sk-t">Wärme</text><text x="260" y="218" text-anchor="middle" class="sk-t acc">η_ges = 0,92 · 0,95 · 0,80 ≈ 0,70</text>',cap:'Wirkungsgradkette eines Pumpenantriebs: Verluste jeder Stufe multiplizieren sich'}},
    {bsp:{t:'Beispiel: Antriebsmotor für ein Förderband auswählen',b:['Gegeben: An der Antriebstrommel werden 4,2 kW benötigt. Getriebe η_G = 0,94, Motor η_M = 0,90.','Gesamtwirkungsgrad: η_ges = 0,94 · 0,90 = 0,846','Aufgenommene elektrische Leistung: P_zu = P_ab / η_ges = 4,2 kW / 0,846 = 4,96 kW','Die Motor-Nennleistung bezieht sich auf die Wellenleistung: P_Motor = 4,2 kW / 0,94 = 4,47 kW → nächste Normgröße 5,5 kW.','Interpretation: Ein 4-kW-Motor wäre dauerhaft überlastet; 5,5 kW mit Reserve für Anlauf und Verschleiß.']}},
    {bsp:{t:'Beispiel: Hubtisch – Energie und Leistung',b:['Gegeben: Last 800 kg wird in 6 s um 1,5 m angehoben.','Hubarbeit: W = m · g · h = 800 kg · 9,81 m/s² · 1,5 m = 11 772 J','Hubleistung: P = W / t = 11 772 J / 6 s = 1 962 W ≈ 1,96 kW','Bei η_ges = 0,75 (Hydraulik) muss der Antrieb ca. 2,6 kW aufnehmen.']}},
    {merke:'„Energieverlust“ heißt: Energie liegt in einer nicht nutzbaren Form vor, meist als Abwärme. Jede Umwandlungsstufe senkt den Gesamtwirkungsgrad.'},
    {falle:'Rückwärts rechnen: benötigte Antriebsleistung = Nutzleistung ÷ η. Wer mit η multipliziert, dimensioniert zu klein.'}
  ]},
  {t:'Strömungsgrundlagen und Dampfturbinen',h:'Funktionserhalt von Kraftmaschinen – Wirkungsweise und Nutzung in der Industrie · Dampfturbinen',pg:5,abb:[['Abb. 1.6 Aufbau einer Dampfturbine',6],['Abb. 1.7 Einfache Dampfturbinenanlage',7]],b:[
    {p:'Strömungslehre beschreibt Flüssigkeiten (praktisch inkompressibel) und Gase (kompressibel). Sie ist Grundlage für Turbinen, Pumpen, Rohrleitungen und Druckluftnetze.'},
    {fx:['Q = V / t','Volumenstrom in m³/s (oft l/min oder m³/h)']},
    {fx:['Q = A₁ · v₁ = A₂ · v₂','Kontinuitätsgleichung: Was in eine Leitung hineinfließt, kommt auch heraus. Halber Querschnitt → doppelte Geschwindigkeit, mehr Druckverlust.']},
    {fx:['p = F / A;  1 bar = 10 N/cm² = 10⁵ Pa','Druck als Kraft je Fläche']},
    {bsp:{t:'Beispiel: Kühlwasserleitung mit Reduzierung',b:['Gegeben: Rohr mit d₁ = 50 mm, v₁ = 1,5 m/s; danach Reduzierung auf d₂ = 32 mm.','Volumenstrom: Q = π/4 · (0,05 m)² · 1,5 m/s = 0,00295 m³/s ≈ 10,6 m³/h','Geschwindigkeit nach der Reduzierung: v₂ = v₁ · (d₁/d₂)² = 1,5 m/s · (50/32)² = 3,66 m/s','Interpretation: Mehr als doppelte Geschwindigkeit – höherer Druckverlust, Geräusch und Erosionsgefahr. Reduzierungen nur kurz und nicht vor empfindlichen Verbrauchern.']}},
    {p:'Dampfkraftmaschinen nutzen Brennstoffenergie indirekt: Erst wird im Kessel Dampf erzeugt, dann leistet der Dampf Arbeit. Moderne Bauart ist die Dampfturbine (η um 50 % im Kraftwerk).'},
    {ol:['Wasser erwärmen','Wasser verdampfen','Dampf überhitzen','Dampf entspannen (Arbeit an der Turbine)','Dampf kondensieren und als Speisewasser zurückführen']},
    {svg:{w:520,h:250,cap:'Dampfkraftprozess als Kreislauf: Wärme rein, Arbeit an der Welle raus, Restwärme über den Kondensator ab',body:'<text x="105" y="18" text-anchor="middle" class="sk-t">Brennstoffwärme</text><line x1="105" y1="24" x2="105" y2="38" class="sk-f" marker-end="url(#ar)"/><rect x="30" y="40" width="150" height="50" class="sk-body"/><text x="105" y="70" text-anchor="middle" class="sk-t">Dampferzeuger</text><rect x="300" y="40" width="120" height="50" class="sk-body"/><text x="360" y="70" text-anchor="middle" class="sk-t">Turbine</text><rect x="440" y="45" width="75" height="40" class="sk-body"/><text x="477.5" y="70" text-anchor="middle" class="sk-t">Generator</text><line x1="420" y1="65" x2="440" y2="65" class="sk-l thick"/><line x1="180" y1="65" x2="298" y2="65" class="sk-f" marker-end="url(#ar)"/><text x="240" y="57" text-anchor="middle" class="sk-t">Frischdampf</text><line x1="360" y1="90" x2="360" y2="178" class="sk-f" marker-end="url(#ar)"/><text x="368" y="140" class="sk-t">Abdampf</text><rect x="300" y="180" width="120" height="50" class="sk-body"/><text x="360" y="210" text-anchor="middle" class="sk-t">Kondensator</text><line x1="420" y1="205" x2="505" y2="205" class="sk-c" marker-end="url(#ar)"/><text x="462" y="197" text-anchor="middle" class="sk-t">Kühlwasser</text><line x1="300" y1="205" x2="182" y2="205" class="sk-f" marker-end="url(#ar)"/><text x="240" y="197" text-anchor="middle" class="sk-t">Kondensat</text><rect x="30" y="180" width="150" height="50" class="sk-body"/><text x="105" y="210" text-anchor="middle" class="sk-t">Speisepumpe</text><line x1="105" y1="180" x2="105" y2="92" class="sk-f" marker-end="url(#ar)"/><text x="113" y="140" class="sk-t">Speisewasser</text>'}},
    {ul:['Wirkprinzip: Dampf strömt durch feststehende Leitschaufeln (Düsen), wird dabei schnell (Druck- in Bewegungsenergie) und lenkt an den Laufschaufeln um – das Laufrad dreht','Je stärker der Strahl umgelenkt wird und je schneller er ist, desto größer die Umfangskraft','Begriffe nach DIN: Dampfturbine (die rotierende Kraftmaschine), Dampfturbosatz (Turbine + angetriebene Maschinen), Dampfturbinenanlage (alles inkl. Kondensator und Rohrleitungen)','Einsatz: Generatorantrieb in Kraftwerken, Industriekraftwerke mit Prozessdampf (Kraft-Wärme-Kopplung)']},
    {merke:'Kontinuität: Bei gleichbleibendem Volumenstrom verhalten sich die Geschwindigkeiten umgekehrt wie die Querschnittsflächen.'}
  ]},
  {t:'Gasturbinen',h:'Gasturbinen – Strahltriebwerke',pg:7,abb:[['Abb. 1.8 Offener und geschlossener Kreislaufprozess',8]],b:[
    {p:'Gasturbinen sind Verbrennungskraftmaschinen mit stetiger Durchströmung. Sie liefern viel Leistung bei kleinem Gewicht und laufen oft im Verbund mit Dampfturbinen (GuD).'},
    {ol:['Verdichter saugt Frischluft an und verdichtet sie','Brennkammer: Brennstoff wird eingespritzt und verbrannt','Heiße Gase entspannen in der Turbine; ein Teil der Leistung treibt den Verdichter','Nutzleistung geht an Generator, Verdichter, Pumpe oder als Schub ans Flugzeug','Abgaswärme kann die Frischluft vorwärmen oder einen Dampfkessel beheizen']},
    {tab:[['Merkmal','Variante A','Variante B'],['Wellen','einwellig: alle Stufen auf einer Welle, eine Drehzahl','zweiwellig: Gasgenerator und Nutzturbine mit eigener Drehzahl'],['Kreislauf','offen: Luft aus der Umgebung, Abgas an die Umgebung','geschlossen: Arbeitsgas umlaufend, von außen erhitzt, nimmt nicht an der Verbrennung teil']]},
    {ul:['Leistungsbereich von wenigen kW bis mehrere hundert MW, η ca. 35–40 % (allein)','Anfahren mit Elektromotor, bis der Verdichter selbst läuft','Strahltriebwerk: Verdichter, Einspritzdüsen und Brennkammer, Turbine, Schubdüse/Diffusor','Industrie: Notstrom, Kraft-Wärme-Kopplung, Antrieb großer Verdichter und Pumpen']},
    {bsp:{t:'Beispiel: Kraft-Wärme-Kopplung im Werk',b:['Ein Gießereibetrieb erzeugt mit einer kleinen Gasturbine Strom und nutzt die heißen Abgase in einem Abhitzekessel für Prozessdampf.','Strom allein hätte ca. 35 % Wirkungsgrad; durch Nutzung der Abwärme steigt die Brennstoffausnutzung auf 75–85 %.','Meister-Aufgabe: Wartungsfenster der Turbine mit der Produktion abstimmen, weil im Stillstand Dampf aus einem Reservekessel kommen muss.']}},
    {merke:'Gasturbine = Verdichter + Brennkammer + Turbine. Ein großer Teil der Turbinenleistung wird für den eigenen Verdichter gebraucht.'}
  ]},
  {t:'Wasserturbinen',h:'Wasserturbinen',pg:8,abb:[['Abb. 1.9 Pelton-Turbine',9],['Abb. 1.10 Francis-Turbine',9],['Abb. 1.11 Kaplan-Turbine',9]],b:[
    {p:'Wasserturbinen wandeln Lage- und Strömungsenergie des Wassers in Drehbewegung, ein Generator macht daraus Strom. Welche Bauart passt, hängt von Fallhöhe und Wassermenge ab.'},
    {tab:[['Bauart','Prinzip','Fallhöhe','Wassermenge','Kennzeichen'],['Pelton','Gleichdruck (Freistrahl)','sehr hoch (ca. 100–2000 m)','klein','Düsen mit Nadel, Becherschaufeln, η bis ca. 90 %'],['Francis','Überdruck','mittel (bis ca. 700 m)','mittel bis groß','Spirale, verstellbare Leitschaufeln, häufigste Bauart'],['Kaplan','Überdruck','klein (ca. 10–60 m)','groß, schwankend','Propeller mit verstellbaren Laufschaufeln, Flusskraftwerk, η bis ca. 96 %']]},
    {ul:['Gleichdruck (Aktion): Druck vor und hinter dem Laufrad gleich; Energie steckt im Strahl','Überdruck (Reaktion): Druck fällt vom Eintritt bis zum Austritt; Laufrad ganz mit Wasser gefüllt','Regelung der Leistung über Düsennadel (Pelton) bzw. Leitschaufelstellung (Francis, Kaplan)','Durchströmturbine: einfache Bauart für kleine Anlagen mit geringen Fallhöhen','Pumpspeicherwerk: bei Stromüberschuss Wasser hochpumpen, bei Bedarf turbinieren; Gesamtwirkungsgrad ca. 75–85 %']},
    {fx:['P = η · ρ · g · h · Q','Turbinenleistung in W; ρ in kg/m³, h Fallhöhe in m, Q in m³/s']},
    {bsp:{t:'Beispiel: Leistung eines Kleinwasserkraftwerks am Werkskanal',b:['Gegeben: Fallhöhe h = 12 m, Q = 2,5 m³/s, η = 0,88','P = 0,88 · 1000 kg/m³ · 9,81 m/s² · 12 m · 2,5 m³/s = 258 984 W ≈ 259 kW','Bauartwahl: kleine Fallhöhe, großer und schwankender Durchfluss → Kaplan-Turbine','Bei 6 000 Volllaststunden: ca. 1,55 GWh Strom pro Jahr.']}},
    {merke:'Hohe Fallhöhe, wenig Wasser → Pelton; mittlere → Francis; niedrige Fallhöhe, viel Wasser → Kaplan.'}
  ]},
  {t:'Verbrennungsmotoren',h:'Verbrennungskraftmaschinen als Kolbenwärmekraftmaschine',pg:10,abb:[['Abb. 1.12 Verwendung von Verbrennungsmotoren',10],['Abb. 1.13 Einspritzverfahren Otto/Diesel',11],['Abb. 1.14 Viertakt-Ottomotor',11],['Abb. 1.15 Viertakt-Dieselmotor',12]],b:[
    {p:'Im Verbrennungsmotor (Kolbenwärmekraftmaschine nach DIN 1940) wird die Wärme aus der Verbrennung eines Kraftstoff-Luft-Gemischs direkt im Zylinder in Kolbenbewegung umgesetzt. Im Betrieb begegnen sie dem Meister bei Staplern, Notstromaggregaten und Pumpenantrieben.'},
    {svg:{w:520,h:240,cap:'Viertaktverfahren: vier Takte in zwei Kurbelwellenumdrehungen, nur der Arbeitstakt gibt Arbeit ab',body:'<rect x="40" y="30" width="190" height="56" class="sk-body"/><text x="135" y="54" text-anchor="middle" class="sk-t">1  Ansaugen</text><text x="135" y="72" text-anchor="middle" class="sk-t">Einlass offen</text><rect x="290" y="30" width="190" height="56" class="sk-body"/><text x="385" y="54" text-anchor="middle" class="sk-t">2  Verdichten</text><text x="385" y="72" text-anchor="middle" class="sk-t">beide Ventile zu</text><rect x="290" y="170" width="190" height="56" class="sk-body"/><text x="385" y="194" text-anchor="middle" class="sk-t acc">3  Arbeiten</text><text x="385" y="212" text-anchor="middle" class="sk-t">Zündung, Expansion</text><rect x="40" y="170" width="190" height="56" class="sk-body"/><text x="135" y="194" text-anchor="middle" class="sk-t">4  Ausstoßen</text><text x="135" y="212" text-anchor="middle" class="sk-t">Auslass offen</text><line x1="230" y1="58" x2="288" y2="58" class="sk-f" marker-end="url(#ar)"/><line x1="385" y1="86" x2="385" y2="168" class="sk-f" marker-end="url(#ar)"/><line x1="290" y1="198" x2="232" y2="198" class="sk-f" marker-end="url(#ar)"/><line x1="135" y1="170" x2="135" y2="88" class="sk-f" marker-end="url(#ar)"/><text x="260" y="122" text-anchor="middle" class="sk-t">720° Kurbelwinkel</text><text x="260" y="140" text-anchor="middle" class="sk-t">= 2 Umdrehungen</text>'}},
    {tab:[['Merkmal','Ottomotor','Dieselmotor'],['Verdichtet wird','Kraftstoff-Luft-Gemisch','nur Luft'],['Verdichtungsverhältnis','ca. 8–12 : 1','ca. 15–20 : 1'],['Zündung','Fremdzündung (Zündkerze)','Selbstzündung durch heiße Luft, Einspritzung kurz vor OT'],['Gemischbildung','Saugrohr- oder Direkteinspritzung; Gasmotor mit gasförmigem Kraftstoff','Direkteinspritzung in den Brennraum'],['Kraftstoff-Kennzahl','Oktanzahl = Klopffestigkeit (soll hoch sein)','Cetanzahl = Zündwilligkeit (soll hoch sein)'],['Wirkungsgrad','ca. 30–35 %','bis ca. 45 %']]},
    {ul:['Anforderungen an Kraftstoffe: schnell zündfähiges Gemisch bilden, rückstandsarm verbrennen, hoher Heizwert, sicher transportierbar','Einsatz: Kfz, Schienen-, Wasser- und Luftfahrzeuge, Stromerzeugung, Flurförderzeuge, stationäre Pumpen, Notstromaggregate','Kosten: CO₂-Bepreisung macht ineffiziente Motoren teurer – Effizienz ist auch ein Kostenthema']},
    {bsp:{t:'Beispiel: Kraftstoffbedarf eines Notstromaggregats',b:['Gegeben: Aggregat liefert 100 kW elektrisch; Generator η_G = 0,93, Dieselmotor η_M = 0,40; Heizwert Diesel ≈ 9,9 kWh/l','Benötigte Brennstoffleistung: 100 kW / (0,93 · 0,40) = 268,8 kW','Verbrauch je Stunde: 268,8 kWh / 9,9 kWh/l = 27,2 l/h','Für 8 Stunden Überbrückung muss der Tagestank mindestens ca. 220 l enthalten; Füllstand bei jeder Inspektion prüfen und Probelauf (z. B. monatlich unter Last) dokumentieren.']}},
    {merke:'Viertakt: Ansaugen – Verdichten – Arbeiten – Ausstoßen in zwei Kurbelwellenumdrehungen; nur der dritte Takt liefert Arbeit.'},
    {falle:'Oktanzahl gehört zum Otto-, Cetanzahl zum Dieselmotor – und beide sollen möglichst hoch sein, obwohl sie Gegensätzliches beschreiben (Klopffestigkeit vs. Zündwilligkeit).'}
  ]},
  {t:'Elektrische Maschinen',h:'Elektrische Maschinen – Umwandlung elektrischer Energie in mechanische Energie',pg:13,abb:[['Abb. 1.16 Unterscheidung der Stromarten',13],['Abb. 1.17 Zeitlicher Verlauf der Stromstärke',14]],b:[
    {p:'Elektrische Maschinen wandeln elektrische in mechanische Energie (Motor) oder umgekehrt (Generator). Sie haben die kleinsten Umwandlungsverluste aller Kraftmaschinen und sind der Standardantrieb im Betrieb.'},
    {svg:{w:520,h:255,cap:'Zeitverlauf der Stromarten',body:'<line x1="25" y1="105" x2="165" y2="105" class="sk-l" marker-end="url(#ar)"/><line x1="25" y1="170" x2="25" y2="30" class="sk-l" marker-end="url(#ar)"/><text x="31" y="40" class="sk-t">i</text><text x="161" y="123" text-anchor="end" class="sk-t">t</text><text x="95" y="195" text-anchor="middle" class="sk-t acc">Gleichstrom</text><line x1="195" y1="105" x2="335" y2="105" class="sk-l" marker-end="url(#ar)"/><line x1="195" y1="170" x2="195" y2="30" class="sk-l" marker-end="url(#ar)"/><text x="201" y="40" class="sk-t">i</text><text x="331" y="123" text-anchor="end" class="sk-t">t</text><text x="265" y="195" text-anchor="middle" class="sk-t acc">Wechselstrom</text><line x1="365" y1="105" x2="505" y2="105" class="sk-l" marker-end="url(#ar)"/><line x1="365" y1="170" x2="365" y2="30" class="sk-l" marker-end="url(#ar)"/><text x="371" y="40" class="sk-t">i</text><text x="501" y="123" text-anchor="end" class="sk-t">t</text><text x="435" y="195" text-anchor="middle" class="sk-t acc">Drehstrom</text><line x1="25" y1="65" x2="160" y2="65" class="sk-l thick"/><polyline points="200,105 203.5,93.5 207,82.5 210.5,73 214,66 217.5,61.5 221,60 224.5,61.5 228,66 231.5,73 234.5,82.5 238,93.5 241.5,105 245,116.5 248.5,127.5 252,137 255.5,144 259,148.5 262.5,150 266,148.5 269.5,144 273,137 276.5,127.5 280,116.5 283.5,105 287,93.5 290.5,82.5 294,73 297,66 300.5,61.5 304,60 307.5,61.5 311,66 314.5,73 318,82.5 321.5,93.5 325,105" class="sk-l thick"/><polyline points="370,105 373.5,93.5 377,82.5 380.5,73 384,66 387.5,61.5 391,60 394.5,61.5 398,66 401.5,73 404.5,82.5 408,93.5 411.5,105 415,116.5 418.5,127.5 422,137 425.5,144 429,148.5 432.5,150 436,148.5 439.5,144 443,137 446.5,127.5 450,116.5 453.5,105 457,93.5 460.5,82.5 464,73 467,66 470.5,61.5 474,60 477.5,61.5 481,66 484.5,73 488,82.5 491.5,93.5 495,105" class="sk-l thick"/><polyline points="370,144 373.5,148.5 377,150 380.5,148.5 384,144 387.5,137 391,127.5 394.5,116.5 398,105 401.5,93.5 404.5,82.5 408,73 411.5,66 415,61.5 418.5,60 422,61.5 425.5,66 429,73 432.5,82.5 436,93.5 439.5,105 443,116.5 446.5,127.5 450,137 453.5,144 457,148.5 460.5,150 464,148.5 467,144 470.5,137 474,127.5 477.5,116.5 481,105 484.5,93.5 488,82.5 491.5,73 495,66" class="sk-f"/><polyline points="370,66 373.5,73 377,82.5 380.5,93.5 384,105 387.5,116.5 391,127.5 394.5,137 398,144 401.5,148.5 404.5,150 408,148.5 411.5,144 415,137 418.5,127.5 422,116.5 425.5,105 429,93.5 432.5,82.5 436,73 439.5,66 443,61.5 446.5,60 450,61.5 453.5,66 457,73 460.5,82.5 464,93.5 467,105 470.5,116.5 474,127.5 477.5,137 481,144 484.5,148.5 488,150 491.5,148.5 495,144" class="sk-c"/><text x="260" y="222" text-anchor="middle" class="sk-t">Drehstrom: drei um 120° versetzte Wechselspannungen L1, L2, L3</text><text x="260" y="242" text-anchor="middle" class="sk-t">230 V Außenleiter gegen N, 400 V zwischen zwei Außenleitern</text>'}},
    {ul:['Gleichstrom: fließt nur in eine Richtung (Batterie, Steuerspannung 24 V DC)','Wechselstrom: Richtung und Größe ändern sich periodisch; Netzfrequenz 50 Hz (USA 60 Hz)','Drehstrom: drei verkettete Wechselspannungen, je 120° versetzt; 230 V zwischen Außenleiter und N, 400 V zwischen zwei Außenleitern','Übertragungsnetze im Höchstspannungsbereich werden zunehmend als HGÜ (Gleichstrom) gebaut: nur zwei Leiter, geringere Verluste über große Strecken']},
    {fx:['f = 1 / T','Frequenz in Hz aus der Periodendauer T in s']},
    {fx:['Wechselstrom: P = U · I · cos φ','Wirkleistung; cos φ = Leistungsfaktor (Wirk- zu Scheinleistung, steht auf dem Typenschild)']},
    {fx:['Drehstrom: P = √3 · U · I · cos φ','U = Spannung zwischen den Außenleitern (400 V)']},
    {fx:['W = P · t','elektrische Arbeit in kWh – Basis jeder Energiekostenrechnung']},
    {tab:[['Motor','Eigenschaften','Typischer Einsatz'],['Drehstrom-Asynchronmotor (Kurzschlussläufer)','einfach, robust, wartungsarm, Drehstromnetz überall vorhanden','Pumpen, Lüfter, Förderer, Werkzeugmaschinen'],['Gleichstrommotor','großes Anzugsmoment, Drehzahl stufenlos steuerbar','ältere Hauptantriebe, Fahrantriebe'],['Wechselstrommotor (Kondensatormotor)','klein, Einphasennetz','Handmaschinen, Kleingeräte'],['Linearmotor','gerade Bewegung ohne Spindel oder Getriebe, sehr dynamisch, wenig Verschleißteile','Werkzeugmaschinen, Positioniersysteme'],['Transformator','wandelt Spannung im Verhältnis der Windungszahlen, keine bewegten Teile','Netzanschluss, Steuertrafo']]},
    {ul:['Vorteile des Elektromotors: sofort betriebsbereit, leicht umsteuerbar, gut regelbar (Frequenzumrichter), guter Wirkungsgrad in allen Lastbereichen, leicht mit Bremse und Getriebe kombinierbar, unempfindlich gegen Aussetzbetrieb','Elektromotoren verursachen rund zwei Drittel des industriellen Stromverbrauchs – Effizienz lohnt sich','EU-Ökodesign-Verordnung (EU) 2019/1781: neue Drehstrommotoren 0,75–1000 kW mindestens IE3, 75–200 kW seit Juli 2023 mindestens IE4']},
    {bsp:{t:'Beispiel: Stromaufnahme und Energiekosten eines Pumpenmotors',b:['Gegeben: Wellenleistung 11 kW, η = 0,91, cos φ = 0,85, Netz 400 V; Laufzeit 4 000 h/a, Strompreis 0,20 €/kWh','Aufgenommene Leistung: P_zu = 11 kW / 0,91 = 12,09 kW','Strom: I = P_zu / (√3 · U · cos φ) = 12 088 W / (1,732 · 400 V · 0,85) = 20,5 A','Energie: W = 12,09 kW · 4 000 h = 48 352 kWh → Kosten ≈ 9 670 € pro Jahr','Interpretation: Die Energiekosten eines Jahres übersteigen den Kaufpreis des Motors deutlich – deshalb bei Ersatz auf IE4 und Drehzahlregelung achten.']}},
    {merke:'Elektrische Maschinen erreichen Wirkungsgrade bis 99 % (Großtransformator); bei Motoren entscheidet die Effizienzklasse über die Betriebskosten.'}
  ]},
  {t:'Elektrische Schutzmaßnahmen und Elektrofachkraft',h:'Elektrische Maschinen – Umwandlung elektrischer Energie in mechanische Energie (Elektrische Schutzmaßnahmen)',pg:15,abb:[['Tab. 1.1 Elektrische Schutzarten',15]],b:[
    {p:'Strom ist unsichtbar; ein Körperstrom kann Verbrennungen, Muskelverkrampfung und Herzkammerflimmern auslösen. Die meisten Elektrounfälle entstehen durch Unachtsamkeit. Schutz entsteht durch das Betriebsmittel selbst, durch Maßnahmen beim Errichten oder durch beides.'},
    {tab:[['Schutzebene','Ziel','Beispiel'],['Basisschutz','direktes Berühren aktiver Teile verhindern','Isolierung, Abdeckung, Gehäuse'],['Fehlerschutz','im Fehlerfall Berührungsspannung niedrig halten oder schnell abschalten','Schutzleiter mit Überstromschutz'],['Zusatzschutz','Restrisiko abfangen, wenn Basis- und Fehlerschutz versagen','Fehlerstrom-Schutzeinrichtung (RCD) 30 mA']]},
    {svg:{w:520,h:290,body:'<rect x="60" y="10" width="400" height="36" class="sk-body"/><text x="260" y="33" text-anchor="middle" class="sk-t">1  Freischalten (allpolig trennen)</text><line x1="260" y1="46" x2="260" y2="63" class="sk-f" marker-end="url(#ar)"/><rect x="60" y="65" width="400" height="36" class="sk-body"/><text x="260" y="88" text-anchor="middle" class="sk-t">2  Gegen Wiedereinschalten sichern</text><line x1="260" y1="101" x2="260" y2="118" class="sk-f" marker-end="url(#ar)"/><rect x="60" y="120" width="400" height="36" class="sk-body"/><text x="260" y="143" text-anchor="middle" class="sk-t">3  Spannungsfreiheit feststellen</text><line x1="260" y1="156" x2="260" y2="173" class="sk-f" marker-end="url(#ar)"/><rect x="60" y="175" width="400" height="36" class="sk-body"/><text x="260" y="198" text-anchor="middle" class="sk-t">4  Erden und kurzschließen</text><line x1="260" y1="211" x2="260" y2="228" class="sk-f" marker-end="url(#ar)"/><rect x="60" y="230" width="400" height="36" class="sk-body"/><text x="260" y="253" text-anchor="middle" class="sk-t">5  Benachbarte aktive Teile abdecken</text>',cap:'Die fünf Sicherheitsregeln – vor Arbeitsbeginn in dieser Reihenfolge, Aufhebung umgekehrt'}},
    {tab:[['Person','Darf','Grundlage'],['Elektrofachkraft (EFK)','elektrische Anlagen errichten, ändern, instand halten; beaufsichtigen','Ausbildung, Erfahrung, Normenkenntnis'],['Elektrofachkraft für festgelegte Tätigkeiten (EFKffT)','eng umrissene, wiederkehrende Arbeiten selbstständig, z. B. Motortausch gleicher Bauart','Lehrgang (mind. ca. 80 UE) und schriftliche Bestellung durch den Arbeitgeber'],['Elektrotechnisch unterwiesene Person (EuP)','einfache Tätigkeiten nur unter Leitung und Aufsicht einer EFK, z. B. Schaltraum betreten, Spannungsfreiheit feststellen','Unterweisung (ca. 1 Tag)'],['Laie','keine Arbeiten an elektrischen Anlagen','–']]},
    {ul:['Rechtsgrundlage: DGUV Vorschrift 3 und VDE-Bestimmungen als anerkannte Regeln der Technik','Arbeiten unter Spannung nur in begründeten Ausnahmen und nur durch speziell ausgebildete Fachkräfte','Ortsveränderliche Geräte und ortsfeste Anlagen wiederkehrend prüfen lassen (Fristen in der Gefährdungsbeurteilung festlegen)']},
    {bsp:{t:'Beispiel: Motortausch an einer Bandanlage',b:['Ein Industriemechaniker soll einen defekten Getriebemotor tauschen.','Mechanischer Tausch: darf er erledigen. Abklemmen und Anschließen: nur EFK oder eine dafür bestellte EFKffT.','Ablauf: EFK schaltet frei und sichert mit persönlichem Schloss (Regeln 1–3), Mechaniker baut um, EFK schließt an, prüft Drehrichtung und Schutzleiter, dokumentiert und gibt frei.','Meister-Pflicht: Einsatzplanung so, dass die EFK verfügbar ist – Zeitdruck ist kein Grund für Ausnahmen.']}},
    {merke:'Fünf Sicherheitsregeln: freischalten, gegen Wiedereinschalten sichern, Spannungsfreiheit feststellen, erden und kurzschließen, benachbarte aktive Teile abdecken.'},
    {falle:'Wer einen technisch versierten, aber nicht qualifizierten Mitarbeiter an die Elektrik lässt, haftet als Vorgesetzter (Auswahl- und Aufsichtsverschulden).'}
  ]},
  {t:'Verdichter',h:'Funktionserhalt von Arbeitsmaschinen, ihre Wirkungsweise und Nutzung in der Industrie · Verdichter',pg:16,abb:[['Abb. 1.18 Indikatordiagramm eines Kolbenverdichters',17],['Abb. 1.19 Roots-Gebläse und Schraubenverdichter',17]],b:[
    {p:'Verdichter (Kompressoren) fördern Gase von niedrigem auf höheren Druck, indem sie ein angesaugtes Volumen verkleinern. Kenngrößen sind Enddruck und Liefermenge (l/min oder m³/h, bezogen auf Ansaugzustand).'},
    {ul:['Einteilung nach Druck: Vakuumpumpe, Nieder-, Mittel-, Hoch-, Höchstdruckverdichter','Ventilatoren fördern Luft nahezu ohne Druckanstieg; Vakuumpumpen erzeugen Unterdruck','Antrieb: stationär meist Elektromotor, fahrbar oft Verbrennungsmotor','Beim Verdichten steigen Druck und Temperatur – Kühlung ist notwendig','Das Indikatordiagramm (p über V) zeigt den Arbeitstakt eines Kolbenverdichters: ansaugen, verdichten, ausschieben, Rückexpansion aus dem Schadraum']},
    {tab:[['Bauart','Prinzip','Stärken','Einsatz'],['Hubkolbenverdichter','Kolben verkleinert Zylinderraum, Saug- und Druckventil','hohe Drücke, mehrstufig','Werkstatt, Hochdruck, Kurzzeitbetrieb'],['Rotationsverdichter (Flügelzelle)','exzentrischer Rotor mit Schiebern','kompakt','kleine Leistungen'],['Schraubenverdichter','zwei ineinandergreifende Schraubenrotoren','pulsationsarm, leise, kompakt','Druckluftstationen im Dauerbetrieb'],['Roots-Gebläse','zwei gegenläufige Drehkolben mit Gleichlaufgetriebe','ölfrei, große Mengen','kleine Druckerhöhung, pneumatische Förderung'],['Turboverdichter (radial/axial)','Strömungsmaschine, kontinuierlich','sehr große Volumenströme (bis ca. 60 MW)','Hütten, Chemie, Großdruckluft']]},
    {bsp:{t:'Beispiel: Liefermenge für einen Montagebereich abschätzen',b:['Gegeben: 8 Druckluftschrauber à 300 l/min, Gleichzeitigkeitsfaktor 0,5; Zuschlag 20 % für Leckage und Reserve','Bedarf: 8 · 300 l/min · 0,5 = 1 200 l/min','Mit Zuschlag: 1 200 l/min · 1,2 = 1 440 l/min ≈ 1,44 m³/min (86 m³/h)','Auswahl: Schraubenverdichter für Dauerbetrieb mit ca. 1,5 m³/min bei 7 bar, möglichst drehzahlgeregelt, da der Bedarf schwankt.']}},
    {merke:'Verdichter sind Arbeitsmaschinen: Sie fördern Gase mit zum Teil hohem Druck. Verdränger arbeiten mit Raumverkleinerung, Turboverdichter mit Strömungsumlenkung.'}
  ]},
  {t:'Pumpen',h:'Pumpen',pg:18,abb:[['Abb. 1.20 Schema einer Pumpenanlage',18],['Abb. 1.21 Kennlinien und Betriebspunkt',19],['Abb. 1.22 Schnitt durch eine Kreiselpumpe',20]],b:[
    {p:'Pumpen fördern Flüssigkeiten durch Rohrleitungen und überwinden dabei Höhenunterschiede und Widerstände. Die richtige Auslegung entscheidet über Energieverbrauch und Lebensdauer.'},
    {fx:['H = H_geo + H_v + H_w','Gesamtförderhöhe = geodätische Höhe + Geschwindigkeitshöhe + Widerstandshöhe (Rohrreibung, Armaturen, Einbauten)']},
    {fx:['P = ρ · g · Q · H','Förderleistung in W; Antriebsleistung = P / η_Pumpe']},
    {svg:{w:520,h:260,body:'<line x1="60" y1="225" x2="490" y2="225" class="sk-l" marker-end="url(#ar)"/><line x1="60" y1="225" x2="60" y2="20" class="sk-l" marker-end="url(#ar)"/><text x="70" y="22" class="sk-t">Förderhöhe H</text><text x="485" y="248" text-anchor="end" class="sk-t">Förderstrom Q</text><path d="M60,60 Q300,70 460,200" class="sk-l thick"/><path d="M60,160 Q260,150 440,40" class="sk-f"/><line x1="302" y1="108" x2="302" y2="225" class="sk-c"/><line x1="60" y1="108" x2="302" y2="108" class="sk-c"/><circle cx="302" cy="108" r="6" class="fillacc"/><text x="245" y="200" text-anchor="middle" class="sk-t acc">Betriebspunkt</text><text x="405" y="50" text-anchor="end" class="sk-t">Anlagenkennlinie</text><text x="420" y="195" text-anchor="end" class="sk-t">Pumpenkennlinie</text><text x="54" y="164" text-anchor="end" class="sk-t">H_geo</text>',cap:'Der Betriebspunkt liegt im Schnitt von Pumpen- und Anlagenkennlinie'}},
    {ul:['Anlagenkennlinie: nötige Förderhöhe in Abhängigkeit vom Förderstrom (steigt mit Q, weil Reibung wächst)','Pumpenkennlinie: welche Förderhöhe die Pumpe bei welchem Förderstrom schafft','Betriebspunkt: Schnittpunkt beider Kennlinien – liegt er weit vom Bestpunkt, sinkt der Wirkungsgrad']},
    {tab:[['Pumpenart','Funktion','Eigenschaften'],['Hubkolbenpumpe','Kolben mit Saug- und Druckventil; doppelt wirkend fördert in beide Hubrichtungen','hohe Drücke, pulsierend'],['Membranpumpe','Membran statt Kolben, Antriebsteile ohne Kontakt zum Medium','für Schlamm, Sand, aggressive oder giftige Medien'],['Axialkolbenpumpe','Kolben in rotierender Trommel, Hub über Schrägscheibe oder Schrägachse','verstellbar, bis ca. 400 bar (Hydraulik)'],['Radialkolbenpumpe','Kolben sternförmig, Hub über Exzenter','bis ca. 700 bar'],['Zahnradpumpe','Zahnlücken transportieren Flüssigkeit','konstantes Volumen, bis ca. 300 bar, robust, günstig'],['Schraubenspindelpumpe','ineinandergreifende Spindeln bilden wandernde Kammern','leise, hohe Drehzahl; Schmier- und Kühlmittel'],['Wasserringpumpe','Flüssigkeitsring bildet veränderliche Kammern','Vakuum, Gase'],['Kreiselpumpe','Laufrad schleudert Flüssigkeit nach außen','stetig, kompakt, häufigste Bauart; nicht selbstansaugend'],['Strahlpumpe','Treibstrahl erzeugt Unterdruck','ohne bewegte Teile, wartungsarm']]},
    {bsp:{t:'Beispiel: Kühlwasserpumpe auslegen',b:['Gegeben: Q = 36 m³/h = 0,01 m³/s; H_geo = 15 m; H_w = 4 m; H_v = 0,3 m; η_P = 0,70','Förderhöhe: H = 15 m + 0,3 m + 4 m = 19,3 m','Förderleistung: P = 1000 kg/m³ · 9,81 m/s² · 0,01 m³/s · 19,3 m = 1 893 W','Antriebsleistung: 1 893 W / 0,70 = 2,70 kW → Motor 3 kW','Interpretation: Pumpe nach Anlagenkennlinie wählen. Eine zu große Pumpe würde gedrosselt – dauerhaft verschenkte Energie. Besser: Drehzahlregelung.']}},
    {merke:'Kreiselpumpen saugen nicht selbst an: vor dem Start füllen und entlüften, sonst laufen Gleitringdichtung und Lager trocken.'},
    {falle:'Ein Drosselventil hinter einer zu großen Pumpe „passt“ zwar den Volumenstrom an, verbrennt aber die Differenzleistung als Wärme.'}
  ]},
  {t:'Werkzeugmaschinen und Maschinensicherheit',h:'Werkzeugmaschinen',pg:21,b:[
    {p:'Werkzeugmaschinen sind Arbeitsmaschinen zum Umformen, Trennen (Zerteilen, Spanen, Abtragen) und Fügen. Hohe Kräfte und Geschwindigkeiten machen sie gefährlich; für den sicheren und wirtschaftlichen Betrieb ist eine vollständige Dokumentation unverzichtbar.'},
    {ul:['Dokumentation: Betriebsanleitung, Datenblätter, Schalt- und Hydraulikpläne, Ersatzteillisten, Wartungsplan, Konformitätserklärung','Gefährdungen: mechanisch (bewegte Teile), elektrisch, thermisch (heiße/kalte Teile), Lärm, Vibration, Strahlung, Gefahrstoffe (Kühlschmierstoff, Stäube)','Rechtsrahmen: Maschinenrichtlinie 2006/42/EG bzw. ab 20.01.2027 Maschinenverordnung (EU) 2023/1230, harmonisierte Normen (z. B. EN ISO 12100)','Sicherheitskonzept über alle Lebensphasen: Planung/Konstruktion, Transport, Aufbau, Inbetriebnahme, Regelbetrieb, Wartung/Reparatur, Stillsetzung, Abbau, Entsorgung']},
    {svg:{w:520,h:190,cap:'Rangfolge der Schutzmaßnahmen: erst die höhere Stufe ausschöpfen, dann die nächste',body:'<rect x="15" y="25" width="140" height="90" class="sk-body"/><text x="85" y="57" text-anchor="middle" class="sk-t">1  Konstruktiv</text><text x="85" y="75" text-anchor="middle" class="sk-t">Gefahr vermeiden</text><text x="85" y="93" text-anchor="middle" class="sk-t">z. B. Kanten runden</text><rect x="190" y="25" width="140" height="90" class="sk-body"/><text x="260" y="57" text-anchor="middle" class="sk-t">2  Technisch</text><text x="260" y="75" text-anchor="middle" class="sk-t">Gefahr abschirmen</text><text x="260" y="93" text-anchor="middle" class="sk-t">z. B. Schutzhaube</text><rect x="365" y="25" width="140" height="90" class="sk-body"/><text x="435" y="57" text-anchor="middle" class="sk-t">3  Hinweisend</text><text x="435" y="75" text-anchor="middle" class="sk-t">warnen, anweisen</text><text x="435" y="93" text-anchor="middle" class="sk-t">z. B. Warnschild</text><line x1="155" y1="70" x2="188" y2="70" class="sk-l" marker-end="url(#ar)"/><line x1="330" y1="70" x2="363" y2="70" class="sk-l" marker-end="url(#ar)"/><line x1="15" y1="145" x2="505" y2="145" class="sk-f" marker-end="url(#ar)"/><text x="260" y="170" text-anchor="middle" class="sk-t acc">Wirksamkeit nimmt ab – Stufe 3 nur für Restgefahren</text>'}},
    {ol:['Inhärent sichere Konstruktion: Gefahren gar nicht erst entstehen lassen','Technische Schutzmaßnahmen: trennende Schutzeinrichtungen, Lichtgitter, Zweihandschaltung','Benutzerinformation: Warnzeichen an der Maschine, Hinweise in der Betriebsanleitung – nur für verbleibende Restrisiken']},
    {bsp:{t:'Beispiel: Gebrauchte Drehmaschine übernehmen',b:['Ein Werk kauft eine gebrauchte konventionelle Drehmaschine ohne Futterschutz.','Gefährdungsbeurteilung zeigt: Erfassen durch das rotierende Futter.','Maßnahme Stufe 2: Futterschutzhaube mit Positionsschalter nachrüsten (Spindel läuft nur bei geschlossener Haube).','Ergänzend Stufe 3: Unterweisung, Betriebsanweisung, Verbot von Handschuhen beim Arbeiten am drehenden Futter.','Prüfen, ob die Nachrüstung eine wesentliche Veränderung ist – dann entstehen Herstellerpflichten (Risikobeurteilung, CE).']}},
    {merke:'Erst wenn konstruktive Lösungen und Abschirmung nicht reichen, darf mit Warnhinweisen gearbeitet werden. Große Gefahren gehören sichtbar an die Maschine, nicht nur in die Anleitung.'}
  ]},
  {t:'Fördertechnik: Stetig- und Unstetigförderer',h:'Funktionserhalt von Fördermitteln und Fördereinrichtungen · Fördertechnik allgemein · Stetigförderer · Unstetigförderer',pg:22,abb:[['Abb. 1.23 Einteilung Transporttechnik',22],['Tab. 1.2 Einteilung der Stetigförderer',23]],b:[
    {p:'Fördertechnik bewegt Güter oder Personen innerhalb eines Betriebs über begrenzte Entfernungen von der Quelle zur Senke. Große Strecken (Lkw, Bahn, Schiff) gehören zur Verkehrstechnik. Teilgebiete sind Hebetechnik, Materialfluss-, Lager- und Umschlagtechnik.'},
    {svg:{w:520,h:250,cap:'Einteilung der innerbetrieblichen Fördermittel mit typischen Beispielen',body:'<rect x="190" y="10" width="140" height="34" class="sk-body"/><text x="260" y="32" text-anchor="middle" class="sk-t acc">Fördermittel</text><rect x="40" y="75" width="180" height="34" class="sk-body"/><text x="130" y="97" text-anchor="middle" class="sk-t">Stetigförderer</text><rect x="300" y="75" width="180" height="34" class="sk-body"/><text x="390" y="97" text-anchor="middle" class="sk-t">Unstetigförderer</text><line x1="260" y1="44" x2="130" y2="75" class="sk-l"/><line x1="260" y1="44" x2="390" y2="75" class="sk-l"/><rect x="10" y="140" width="105" height="34" class="sk-body"/><text x="62.5" y="162" text-anchor="middle" class="sk-t">flurfrei</text><rect x="125" y="140" width="115" height="34" class="sk-body"/><text x="182.5" y="162" text-anchor="middle" class="sk-t">flurgebunden</text><rect x="275" y="140" width="105" height="34" class="sk-body"/><text x="327.5" y="162" text-anchor="middle" class="sk-t">flurfrei</text><rect x="390" y="140" width="115" height="34" class="sk-body"/><text x="447.5" y="162" text-anchor="middle" class="sk-t">flurgebunden</text><line x1="130" y1="109" x2="62" y2="140" class="sk-l"/><line x1="130" y1="109" x2="182" y2="140" class="sk-l"/><line x1="390" y1="109" x2="327" y2="140" class="sk-l"/><line x1="390" y1="109" x2="447" y2="140" class="sk-l"/><text x="62" y="198" text-anchor="middle" class="sk-t">Hängebahn</text><text x="62" y="216" text-anchor="middle" class="sk-t">Kreisförderer</text><text x="182" y="198" text-anchor="middle" class="sk-t">Bandförderer</text><text x="182" y="216" text-anchor="middle" class="sk-t">Rollenbahn</text><text x="182" y="234" text-anchor="middle" class="sk-t">Schleppkette</text><text x="327" y="198" text-anchor="middle" class="sk-t">Brückenkran</text><text x="327" y="216" text-anchor="middle" class="sk-t">Portalkran</text><text x="447" y="198" text-anchor="middle" class="sk-t">Stapler, FTS</text><text x="447" y="216" text-anchor="middle" class="sk-t">Regalbediengerät</text><text x="447" y="234" text-anchor="middle" class="sk-t">Aufzug</text>'}},
    {tab:[['Merkmal','Stetigförderer','Unstetigförderer'],['Massenstrom','kontinuierlich, ggf. getaktet','unterbrochen, Last- und Leerfahrten'],['Beispiele','Band-, Gurt-, Rollen-, Ketten-, Schnecken-, Kreisförderer, Becherwerk, Elektrohängebahn','Kran, Stapler, FTS, Regalbediengerät, Schleppzug, Aufzug'],['Vorteile','großer Durchsatz gleichartiger Güter, günstiges Verhältnis Eigengewicht zu Nutzlast, oft automatisiert','flexible Wege, fährt nur bei Bedarf, vielseitig'],['Nachteile','ortsfest, kaum erweiterbar, Layoutänderung teuer, Be-/Entladen oft mit Zusatzgeräten','geringerer Durchsatz, Fahrer bzw. Steuerung nötig']]},
    {ul:['Normung Stetigförderer: DIN 15201','Flurfrei (an Decke/Stahlbau): Fläche darunter bleibt nutzbar, Decke muss tragen – Kreisförderer, Schleppkreisförderer, Elektrohängebahn, Krane','Flurgebunden: braucht Hallenfläche, keine tragfähige Decke – Schleppkettenförderer, Stapler, FTS, Gabelhubwagen','Aufgeständert: Rollenbahn, Bandförderer, Aufzüge, Satellitenfahrzeuge','Stetigförderer-Gliederung: ohne Zugmittel (Rollenbahn), mit Zugmittel (Bandförderer), mit Fördermedium (pneumatisch), Schwerkraft (Gefällerollenbahn, Kugelrolltisch); nach Gut: Schütt- oder Stückgut','Schleppkettenförderer: Wagen klinkt in eine Bodenkette ein, Stauen und Verzweigen möglich; muss mit dem Gebäude geplant werden']},
    {bsp:{t:'Beispiel: Fördermittel für eine neue Montagelinie wählen',b:['Situation: 600 gleichartige Gehäuse pro Schicht wandern über 6 Montagestationen; Layout soll 5 Jahre stabil bleiben.','Entscheidung: angetriebene Staurollenbahn (Stetigförderer) – hoher Durchsatz, Puffer zwischen Stationen, wenig Personal.','Für die Versorgung mit Kleinteilen aus dem Lager: Routenzug (Unstetigförderer), weil wechselnde Ziele angefahren werden.','Argument im Fachgespräch: Mischsysteme nutzen die Stärken beider Prinzipien.']}},
    {merke:'Stetigförderer lohnen sich bei großen Mengen gleichartiger Güter auf festen Wegen; Unstetigförderer bei wechselnden Wegen und Lasten.'}
  ]},
  {t:'Hebezeuge, Krananlagen und Lastaufnahme',h:'Hebezeuge und Krananlagen',pg:24,abb:[['Abb. 1.24 Gelenkketten und Gliederketten',24],['Abb. 1.25 Gleitlager und Wälzlager',25],['Abb. 1.26 Lastaufnahmeeinrichtungen',26]],b:[
    {p:'Ein Kran besteht aus einem Träger, auf dem eine Katze mit Hubwerk fährt. Der Träger kann an einer Säule drehen (Säulendrehkran), auf Stützen fahren (Portalkran) oder auf einer Kranbahn durch die Halle laufen (Brückenkran).'},
    {ul:['Bauelemente: Ketten/Seile, Räder und Rollen, Hubwerk, Bremsen und Sperren, Fahr- und Drehwerke, Schienen','Ketten: Gelenkketten (Antriebe, Förderer) und Gliederketten/Rundstahlketten (Lastketten, Anschlagketten); Gliederketten sind beweglich und handlich, aber schwer, wenig elastisch und stoßempfindlich','Seile: Drahtseile, Hanf- und Chemiefaserseile; motorische Hebezeuge nur mit Rundlitzenseilen','Rollen und Trommeln: Ketten- und Seilrollen, Seiltrommeln (geschweißt oder Grauguss, meist mit Rillen); Flaschenzüge als Rollen-, Schrauben- oder Planetenflaschenzug','Kranschienen: Flachstahl für kleinere Lasten, Profile nach DIN 536 für größere; Laufräder nach DIN EN 13001-3-3 und DIN 15084, meist mit zwei Spurkränzen','Bremsen: Halte-, Fahr-, Senk- und Sicherheitsbremsen; Rücklaufsperren formschlüssig (Zahnsperre) oder reibschlüssig (Klemmkörper-/Rollenfreilauf)']},
    {tab:[['Begriff','Aufgabe','Belastung'],['Achse','trägt und lagert drehende Teile','Biegung (ggf. Axialkraft), kein Drehmoment'],['Welle','überträgt Drehmoment über Zahnräder, Riemenscheiben, Kupplungen','Torsion und meist zusätzlich Biegung']]},
    {tab:[['Lager','Vorteile','Nachteile','Einsatz'],['Wälzlager','kleines Anlaufmoment, wenig Schmierstoff, wartungsarm, Lebensdauer berechenbar','stoß- und schmutzempfindlich, Drehzahl und Lebensdauer begrenzt','Getriebe, Motoren, Werkzeugmaschinen, Hebezeuge'],['Gleitlager','dämpfend, stoß- und schmutzunempfindlich, leise, hohe Drehzahlen, bei Flüssigkeitsreibung verschleißfrei','hohes Anlaufmoment, viel Schmierstoff, Überwachung nötig','Turbinen, Generatoren, Kreiselpumpen; einfache Lager in Winden']]},
    {tab:[['Lastaufnahmeeinrichtung','Definition','Beispiele'],['Tragmittel','dauerhaft mit dem Hebezeug verbunden','Hakenflasche, Kranhaken, Seil'],['Lastaufnahmemittel','gehört nicht zum Hebezeug, nimmt die Last auf','Traverse, Greifer, Vakuumheber, Zange'],['Anschlagmittel','verbindet Tragmittel und Last bzw. Lastaufnahmemittel','Rundschlinge, Hebeband, Kette, Seil, Schäkel']]},
    {svg:{w:520,h:315,cap:'Zweistrang-Anschlag: Je größer der Neigungswinkel β, desto größer die Kraft im einzelnen Strang',body:'<circle cx="200" cy="35" r="8" class="sk-body"/><line x1="196" y1="42" x2="135" y2="180" class="sk-l thick"/><line x1="204" y1="42" x2="265" y2="180" class="sk-l thick"/><line x1="200" y1="44" x2="200" y2="178" class="sk-c"/><text x="212" y="100" class="sk-t acc">β</text><rect x="110" y="180" width="180" height="50" class="sk-body"/><text x="200" y="210" text-anchor="middle" class="sk-t">Last m</text><line x1="200" y1="230" x2="200" y2="272" class="sk-f" marker-end="url(#ar)"/><text x="210" y="262" class="sk-t">G = m · g</text><text x="330" y="45" class="sk-t">Kraft je Strang (2 Stränge):</text><text x="330" y="70" class="sk-t">β = 0°:   0,50 · G</text><text x="330" y="92" class="sk-t">β = 30°: 0,58 · G</text><text x="330" y="114" class="sk-t">β = 45°: 0,71 · G</text><text x="330" y="136" class="sk-t acc">β = 60°: 1,00 · G</text><text x="330" y="166" class="sk-t">β > 60° unzulässig</text><text x="260" y="300" text-anchor="middle" class="sk-t">Strangkraft F = m · g / (n · cos β)</text>'}},
    {bsp:{t:'Beispiel: Stahlplatte mit Zweistrang-Kette anschlagen',b:['Gegeben: Platte 2 000 kg, zweisträngige Kette, Neigungswinkel β = 60°','Gewichtskraft: G = 2 000 kg · 9,81 m/s² = 19 620 N','Kraft je Strang: F = G / (2 · cos 60°) = 19 620 N / (2 · 0,5) = 19 620 N','Jeder Strang trägt also die volle Last (≈ 2 t). Bei β = 30° wären es nur 11 328 N (≈ 1,15 t).','Folgerung: lange Anschlagmittel wählen, damit β klein bleibt; Tragfähigkeit am Kettenanhänger für den Winkelbereich ablesen; über 60° nicht anschlagen.']}},
    {merke:'Krane und Anschlagmittel sind Arbeitsmittel nach BetrSichV: Prüfung vor Inbetriebnahme und wiederkehrend (Krane mind. jährlich) durch eine befähigte Person, Ergebnis dokumentieren; Anschlagmittel vor jedem Einsatz sichtprüfen.'},
    {falle:'Achse und Welle werden im Alltag verwechselt („Halbachse“ am Fahrzeug ist eine Welle). Entscheidend: Wird ein Drehmoment übertragen?'}
  ]},
  {t:'Handhebezeuge, Serienhebezeuge, Rollenbahnen und Hängeförderer',h:'Handhebezeuge und Serienhebezeuge · Rollenbahnen, Montagewagen, Hängeförderer',pg:27,b:[
    {p:'Für Montage, Reparatur und seltenes Heben genügen oft einfache Hebezeuge; im Serienbetrieb kommen elektrische Kettenzüge und Seilzüge zum Einsatz. Rollenbahnen, Montagewagen und Hängeförderer verketten Arbeitsplätze.'},
    {ul:['Handhebezeuge: Flaschenzug, Seilzug, Hebelzug – für gelegentliche Lasten in Montage und Instandhaltung','Serienhebezeuge: Elektrokettenzug und Elektroseilzug (Unterschied nur im Tragmittel); ein- oder zweisträngig, ortsfest oder mit Fahrwerk an einer Einschienenbahn','Handhabungsgerät: Lastaufnahme und Bedienschalter bilden eine Einheit, Steuerleitung wendelt sich um die Kette','Rollenbahnen: Rollengang (schieben), Gefällerollenbahn (Schwerkraft), angetriebene Rollenbahn; für leichte Güter Röllchenbahn und Kugelrolltisch; meist im Baukasten geliefert','Montagewagen: frei verschiebbar oder liniengebunden, einfachste Automatik über eine Bodenkette mit Ein-/Ausklinken','Hängeförderer: flurfrei an der Decke – Kreisförderer, Power-&-Free-Förderer (Stauen und Ausschleusen möglich), Elektrohängebahn, Seilhängebahn']},
    {bsp:{t:'Beispiel: Hebezeug für eine Getriebe-Montagezelle',b:['Bauteile bis 250 kg, ca. 40 Hübe pro Stunde, Bewegung nur entlang einer Werkbankreihe.','Lösung: Elektrokettenzug 500 kg mit Fahrwerk an einer Einschienenbahn; Hängetaster mit zwei Hubgeschwindigkeiten für feinfühliges Absetzen.','Organisation: jährliche Prüfung durch befähigte Person, tägliche Sichtprüfung durch die Bediener (Kette, Haken, Endschalter), Unterweisung im Anschlagen.']}},
    {merke:'Elektrokettenzug und Elektroseilzug unterscheiden sich nur im Tragmittel; Prüf- und Unterweisungspflichten sind gleich.'}
  ]},
  {t:'Bedeutung der Instandhaltung, TPM und Fernwartung',h:'Wirtschaftliche Bedeutung und Ursachen der Instandhaltung · Instandhaltung im Spannungsfeld der Interessen · Technische Entwicklung · Netzwerktechnik/Fernwartung',pg:31,abb:[['Abb. 2.1 Acht Säulen von TPM',32]],b:[
    {p:'Für die Instandhaltung werden jährlich Milliarden aufgewendet; in hoch automatisierten Branchen ist ein großer Teil der Belegschaft damit befasst. Hoch automatisierte Anlagen rechnen sich nur bei hoher technischer Verfügbarkeit – deshalb ist Instandhaltung ein Produktivitätsfaktor, keine reine Kostenstelle.'},
    {fx:['techn. Verfügbarkeit = (Belegungszeit − techn. Ausfallzeit) / Belegungszeit','Belegungszeit = Schichtzeit − Pausen; organisatorische Stillstände (Material, Personal) zählen nicht']},
    {svg:{w:520,h:255,cap:'Ziel ist das Minimum der Summe aus Instandhaltungs- und Ausfallkosten, nicht minimale Instandhaltungskosten',body:'<line x1="60" y1="225" x2="500" y2="225" class="sk-l" marker-end="url(#ar)"/><line x1="60" y1="225" x2="60" y2="20" class="sk-l" marker-end="url(#ar)"/><text x="495" y="245" text-anchor="end" class="sk-t">Instandhaltungsaufwand</text><text x="68" y="25" class="sk-t">Kosten</text><polyline points="93.5,218 109,217 124.5,215.5 140,213 155,210.5 170.5,207.5 186,204 201.5,200 217,195.5 232,190.5 247.5,185 263,179.5 278.5,173 294,166.5 309,159 324.5,151.5 340,143.5 355.5,134.5 371,125.5 386,116 401.5,106 417,96 432.5,85 448,73.5 463,61.5" class="sk-l"/><polyline points="93.5,82.5 109,127.5 124.5,150.5 140,165 155,174.5 170.5,181.5 186,187 201.5,191 217,194.5 232,197 247.5,199.5 263,201.5 278.5,203 294,204.5 309,206 324.5,207 340,208 355.5,209 371,209.5 386,210.5 401.5,211 417,211.5 432.5,212 448,212.5 463,213" class="sk-l thick"/><polyline points="93.5,75.5 109,119.5 124.5,141 140,153 155,160 170.5,164 186,166 201.5,166 217,165 232,163 247.5,159.5 263,156 278.5,151 294,146 309,140 324.5,133.5 340,126 355.5,118.5 371,110.5 386,101.5 401.5,92 417,82.5 432.5,72 448,61 463,50" class="sk-f"/><line x1="201.4" y1="166.05671386138613" x2="201.4" y2="225" class="sk-c"/><circle cx="201.4" cy="166.05671386138613" r="5" class="fillacc"/><text x="201.4" y="245" text-anchor="middle" class="sk-t acc">Optimum</text><text x="303.6" y="179.4" class="sk-t">Instandhaltungskosten</text><text x="110.4" y="73" class="sk-t">Ausfallfolgekosten</text><text x="312" y="40.70000000000002" class="sk-t acc">Gesamtkosten</text>'}},
    {ul:['Übergeordnetes Ziel: Summe aus schadensbedingten Instandhaltungskosten und Produktionsausfallkosten minimieren, Verfügbarkeit und Abläufe optimieren','Spannungsfeld: höhere Verfügbarkeit und Produktqualität bei gleichzeitig sinkendem Budget; dazu steigendes Bewusstsein für Sicherheits- und Umweltfolgen von Störungen','Entwicklung: von „reparieren, wenn kaputt“ über geplante Instandhaltung mit Planungssystemen bis zu TPM und datengestützter, vorausschauender Instandhaltung']},
    {ul:['TPM (Total Productive Maintenance bzw. Management): Ziel null Ausfälle, null Fehler, null Unfälle über den gesamten Anlagenlebenslauf','Bediener übernehmen Verantwortung für „ihre“ Anlage: Reinigen, Schmieren, Kontrollieren (autonome Instandhaltung); Trennung Produktion/Instandhaltung wird aufgehoben','Acht Säulen: kontinuierliche Verbesserung, autonome Instandhaltung, geplante Instandhaltung, Training und Ausbildung, Anlaufüberwachung neuer Anlagen, Qualitätsmanagement, TPM in der Verwaltung, Arbeits-, Umwelt- und Gesundheitsschutz']},
    {ul:['Fernwartung und Updates über das Netzwerk sparen Anfahrt und Zeit','Risiko: Schadsoftware und Angriffe auf Steuerungen – Schutz durch Firewall, Virenschutz, Netzsegmentierung, Rechtevergabe','VPN: verschlüsselter Tunnel, Dritte können kaum mitlesen','Proxyserver: nimmt Anfragen stellvertretend entgegen, filtert, protokolliert und schützt interne Netze vor direktem Zugriff aus dem Internet','Fernzugriff nur nach Freigabe vor Ort und zeitlich begrenzt; Zugänge dokumentieren']},
    {bsp:{t:'Beispiel: Technische Verfügbarkeit einer Biegezelle',b:['Gegeben: zwei Schichten à 480 min, Pausen insgesamt 60 min → Belegungszeit 900 min; technische Störungen 54 min; zusätzlich 30 min Materialmangel','Technische Verfügbarkeit = (900 − 54) / 900 = 846 / 900 = 0,94 = 94 %','Der Materialmangel (organisatorisch) geht nicht ein – er senkt aber den Nutzungsgrad.','Meister-Folgerung: Ziel z. B. ≥ 96 %; die drei häufigsten Störursachen per Pareto ermitteln und abstellen.']}},
    {merke:'TPM macht die Bediener zu Mitverantwortlichen für den Anlagenzustand. Das funktioniert nur mit Schulung, klaren Standards und Zeit im Schichtplan.'},
    {falle:'Technische Verfügbarkeit und Nutzungsgrad nicht verwechseln: In die technische Verfügbarkeit gehen nur technisch bedingte Ausfälle ein.'}
  ]},
  {t:'Anforderungen, Kostenentwicklung und Umwelt',h:'Qualitative Anforderungen an die Instandhaltungsdurchführung · Progressive Entwicklung der Investitions- und Instandhaltungskosten · Rohstoffverknappung und Umweltgesetzgebung',pg:33,abb:[['Abb. 2.2 Rahmenbedingungen der Instandhaltung',33],['Tab. 2.1 Schlussfolgerungen für einen Instandhaltungsbetrieb',34],['Abb. 2.3 Einflüsse auf Entscheidung und Risiko',35]],b:[
    {p:'Instandhalter brauchen breites Fachwissen, Erfahrung, Improvisationstalent und Beharrlichkeit. Werden ihnen Verantwortung und Projekte übertragen, müssen auch Kompetenzen (Material abrufen, Maßnahmen festlegen, direkter Kontakt zu Fertigung und Planung) mitgegeben werden.'},
    {ul:['Rahmenbedingungen wirtschaftlicher Instandhaltung: instandhaltungsgerecht konstruierte Maschinen, passend ausgelegte Anlagen, Fachwissen und Ausbildung des Personals, moderne Planungs- und Steuerungssysteme','Je verketteter und automatisierter die Fertigung, desto höher die Ausfallfolgekosten: Fällt in einer starr verketteten Linie eine Station aus, stehen alle vor- und nachgelagerten Stationen','Daher: lange Nutzungszeit, hoher Nutzungsgrad und hohe technische Verfügbarkeit bestimmen die Rentabilität']},
    {tab:[['Ziel','Voraussetzungen'],['maximale Verfügbarkeit','kurze Nebenzeiten durch gute Arbeitsvorbereitung, viel vorbeugende Instandhaltung, systematische Schwachstellenbeseitigung'],['minimaler Störumfang','saubere Maschinen (weniger Verschleiß), konsequente Wartung und Inspektion'],['minimale Stillstandzeit','redundante Technik, schneller Ressourceneinsatz bei Störungen, kurze Nebenzeiten'],['minimale Instandhaltungskosten','gut ausgebildetes Personal, passende Strategie, geeignete Ersatzteilhaltung']]},
    {ul:['Risikoabwägung vor jeder Entscheidung: Wie hoch ist das Ausfallrisiko? Welche Gefahr für Mensch und Umwelt? Welche wirtschaftlichen Folgen? Ist Verringerung möglich und was kostet sie?','Erfahrungswerte (Ausfallhistorie, Herstellerangaben) sind die Grundlage dieser Abschätzung','Umwelt: Betriebsstoffe (Öle, Emulsionen, Fette, Laugen, Lacke, Reiniger) sparsam einsetzen, umweltverträglichere Alternativen prüfen, getrennt sammeln und fachgerecht entsorgen (KrWG, AwSV); Umweltmanagement z. B. nach ISO 14001']},
    {bsp:{t:'Beispiel: Ausfallfolgekosten in einer verketteten Linie',b:['Linie mit 5 Stationen, Ausbringung 120 Teile/h, Deckungsbeitrag 8 € je Teil, Personal 6 Personen à 45 €/h','Ausfall einer Station für 2 h: entgangener Deckungsbeitrag 2 h · 120 · 8 € = 1 920 €; Leerkosten Personal 2 h · 6 · 45 € = 540 €','Summe ≈ 2 460 € – ohne Reparaturkosten und mögliche Vertragsstrafe','Folgerung: Ein Puffer von 30 min zwischen den Stationen oder ein vorgehaltenes Ersatzaggregat kann sich schon nach wenigen Ausfällen bezahlt machen.']}},
    {merke:'Die Bedeutung der Instandhaltung wächst mit Automatisierung und Verkettung – Ausfallfolgekosten übersteigen oft die Reparaturkosten um ein Vielfaches.'}
  ]},
  {t:'Grundmaßnahmen, Wartung und Inspektion planen',h:'Planen und Einleiten von Instandhaltungsmaßnahmen · Wartung, Inspektion, Instandsetzung und Verbesserung · Maßnahmenplanung der Wartung · Maßnahmenplanung der Inspektion',pg:35,abb:[['Tab. 2.2 Grundmaßnahmen der Instandhaltung',36]],b:[
    {p:'Instandhaltung nach DIN 31051 umfasst alle technischen und administrativen Maßnahmen sowie Managementmaßnahmen während der Lebensdauer einer Einheit, die den funktionsfähigen Zustand erhalten oder wiederherstellen.'},
    {tab:[['Grundmaßnahme','Zweck','Beispiele'],['Wartung','Abbau des Abnutzungsvorrats verzögern','reinigen, schmieren, nachstellen, Filter wechseln'],['Inspektion','Istzustand feststellen und beurteilen, Ursachen der Abnutzung bestimmen, Folgerungen ableiten','messen, prüfen, Sichtkontrolle, Thermografie'],['Instandsetzung','funktionsfähigen Sollzustand wiederherstellen (ohne Verbesserung)','Lager tauschen, ausbessern, Dichtungen erneuern'],['Verbesserung','Funktionssicherheit steigern, ohne die geforderte Funktion zu ändern','verschleißfestere Werkstoffe, bessere Abdichtung, Zentralschmierung nachrüsten']]},
    {svg:{w:520,h:250,body:'<line x1="50" y1="215" x2="500" y2="215" class="sk-l" marker-end="url(#ar)"/><line x1="50" y1="215" x2="50" y2="20" class="sk-l" marker-end="url(#ar)"/><text x="58" y="22" class="sk-t">Abnutzungsvorrat</text><text x="495" y="238" text-anchor="end" class="sk-t">Zeit</text><line x1="50" y1="175" x2="490" y2="175" class="sk-c"/><text x="60" y="168" class="sk-t">Abnutzungsgrenze</text><path d="M50,50 Q160,60 240,170" class="sk-l thick"/><line x1="240" y1="170" x2="240" y2="56" class="sk-f" marker-end="url(#ar)"/><path d="M240,50 Q350,60 430,170" class="sk-l thick"/><text x="250" y="110" class="sk-t acc">Instandsetzung</text><text x="60" y="44" class="sk-t">Ausgangszustand</text><circle cx="430" cy="170" r="5" class="fillacc"/><text x="430" y="200" text-anchor="middle" class="sk-t">Ausfall droht</text>',cap:'Abnutzungsvorrat nach DIN 31051 – Instandsetzung stellt ihn vor Erreichen der Grenze wieder her'}},
    {ul:['Teilaufgaben: Pflege nach Betriebsanleitung, routinemäßige Zustandskontrolle, Fehlerdiagnose bei Störungen, Wiederherstellung der vollen Leistungsfähigkeit, Austausch veralteter Anlagenteile','Wartung und Inspektion zu einer Maßnahme der geplanten Instandhaltung (GI) bündeln: ein Arbeitsgang, weniger Rüst- und Wegezeit, keine Doppelarbeit','GI-Plan: Objekt, Tätigkeit, Turnus, Planzeit, Priorität, Werkzeug, Material, Sicherheitshinweise','Auslösung zeitgesteuert (z. B. alle 3 Monate) oder zählerbasiert (Betriebsstunden, Stückzahl, Schaltspiele); in der Regel per Instandhaltungssoftware','Inspektionsintervalle stehen meist in der Herstellerdokumentation; Sonderinspektionen nach Schäden, wenn Folgeschäden noch nicht lokalisiert sind','Bei auffällig hohem oder häufigem Verschleiß die Ursache suchen statt nur Teile zu tauschen']},
    {bsp:{t:'Beispiel: GI-Plan für einen Schraubenkompressor (eigener Musterplan)',b:['Täglich (Bediener): Betriebsdruck und Temperatur ablesen, Kondensatableiter auf Funktion prüfen','Wöchentlich: Ölstand, Leckagen und Geräusche prüfen','Alle 2 000 Bh: Ansaugfilter und Ölfilter wechseln, Kühler reinigen','Alle 4 000 Bh: Ölwechsel, Ölabscheider tauschen, Sicherheitsventil auf Funktion prüfen','Jährlich: Prüfung des Druckbehälters nach Prüffristenplan (befähigte Person/ZÜS)','Jede Position mit Planzeit, Material und Hinweis „vor Arbeiten drucklos machen und gegen Wiederanlauf sichern“.']}},
    {merke:'Wartung bremst den Verschleiß, Inspektion stellt ihn fest, Instandsetzung beseitigt ihn, Verbesserung beseitigt seine Ursache.'}
  ]},
  {t:'Instandsetzungsstrategien und Verbesserung',h:'Maßnahmenplanung der Instandsetzung · Maßnahmenplanung der Verbesserung',pg:37,b:[
    {p:'Ablauforganisatorisch unterscheidet man vorbeugende Instandhaltung (zeit- oder zustandsorientiert) und störungsbedingte Instandsetzung. Welche Strategie passt, hängt von Ausfallfolgen, Messbarkeit und Erfahrungswerten ab.'},
    {tab:[['Strategie','Auslöser','Vorteil','Nachteil'],['störungsbedingt (Crash)','Ausfall','Teile werden voll genutzt, wenig Planung','ungeplante Stillstände, Folgeschäden, Hektik'],['periodisch vorbeugend','Zeit- oder Zählerintervall','gut planbar, hohe Verfügbarkeit','Teile werden oft zu früh getauscht'],['zustandsorientiert','Messwert erreicht Grenze (MDE/BDE, Condition Monitoring)','Abnutzungsvorrat weitgehend genutzt, planbar','Messtechnik und Auswertung nötig'],['vorausschauend (predictive)','Prognose aus Daten, ggf. mit KI','Eingriff kurz vor dem Ausfall, beste Terminierung','hohe Investition in Sensorik, IT, Know-how']]},
    {svg:{w:520,h:330,cap:'Vereinfachte Entscheidungslogik für die Instandhaltungsstrategie eines Bauteils',body:'<rect x="20" y="15" width="250" height="46" class="sk-body"/><text x="145" y="34" text-anchor="middle" class="sk-t">Ausfall teuer oder</text><text x="145" y="52" text-anchor="middle" class="sk-t">sicherheitskritisch?</text><line x1="270" y1="38" x2="328" y2="38" class="sk-l" marker-end="url(#ar)"/><text x="299" y="30" text-anchor="middle" class="sk-t">nein</text><rect x="330" y="15" width="175" height="46" class="sk-body"/><text x="417.5" y="43" text-anchor="middle" class="sk-t acc">ausfallbedingt</text><line x1="145" y1="61" x2="145" y2="98" class="sk-l" marker-end="url(#ar)"/><text x="152" y="84" class="sk-t">ja</text><rect x="20" y="100" width="250" height="46" class="sk-body"/><text x="145" y="119" text-anchor="middle" class="sk-t">Zustand messbar</text><text x="145" y="137" text-anchor="middle" class="sk-t">(Verschleiß erkennbar)?</text><line x1="270" y1="123" x2="328" y2="123" class="sk-l" marker-end="url(#ar)"/><text x="299" y="115" text-anchor="middle" class="sk-t">ja</text><rect x="330" y="100" width="175" height="46" class="sk-body"/><text x="417.5" y="119" text-anchor="middle" class="sk-t acc">zustandsorientiert</text><text x="417.5" y="137" text-anchor="middle" class="sk-t">oder vorausschauend</text><line x1="145" y1="146" x2="145" y2="183" class="sk-l" marker-end="url(#ar)"/><text x="152" y="169" class="sk-t">nein</text><rect x="20" y="185" width="250" height="46" class="sk-body"/><text x="145" y="204" text-anchor="middle" class="sk-t">Lebensdauer bzw.</text><text x="145" y="222" text-anchor="middle" class="sk-t">Intervall bekannt?</text><line x1="270" y1="208" x2="328" y2="208" class="sk-l" marker-end="url(#ar)"/><text x="299" y="200" text-anchor="middle" class="sk-t">ja</text><rect x="330" y="185" width="175" height="46" class="sk-body"/><text x="417.5" y="204" text-anchor="middle" class="sk-t acc">periodisch</text><text x="417.5" y="222" text-anchor="middle" class="sk-t">vorbeugend</text><line x1="145" y1="231" x2="145" y2="268" class="sk-l" marker-end="url(#ar)"/><text x="152" y="254" class="sk-t">nein</text><rect x="20" y="270" width="250" height="46" class="sk-body"/><text x="145" y="289" text-anchor="middle" class="sk-t acc">Redundanz schaffen oder</text><text x="145" y="307" text-anchor="middle" class="sk-t">konstruktiv verbessern</text>'}},
    {ul:['Vorbeugend: regelmäßige Kontrollen und rechtzeitiger Tausch von Verschleißteilen; erfordert Arbeitspläne, Schadensauswertung und Schwachstellenanalyse','Störungsbedingt: Planung beschränkt sich auf Material und Personaleinsatz; schnelle Lokalisierung braucht Anlagen- und Werkstückkenntnis','Sichtbare Ursachen (gebrochen, verbogen, locker, festgefressen) werden direkt behoben; unsichtbare erfordern systematisches Hinterfragen und Prüfen','Ursachenforschung wird oft aus Zeitdruck vergessen – ist aber Kernaufgabe','Industrie 4.0/IoT: Zustand in Echtzeit überwachen; Asset Performance Management bündelt Daten aller Anlagen und sagt den besten Wartungszeitpunkt voraus']},
    {ol:['Auftrag dokumentieren und analysieren','Durchführung vorbereiten (Material, Personal, Termin mit Produktion)','Vorwegmaßnahmen: Schutz- und Sicherheitseinrichtungen, Freischalten','Freigabe zur Durchführung nach Prüfung','Durchführung','Funktionsprüfung','Abnahme','Fertigmeldung und Dokumentation']},
    {bsp:{t:'Beispiel: Strategie für drei Bauteile einer Pressenlinie',b:['Lüfter im Schaltschrank (billig, redundant, Ausfall unkritisch): störungsbedingt tauschen, Ersatz am Lager.','Hydraulikpumpe (Ausfall stoppt die Linie, Zustand über Leckölstrom und Schwingung messbar): zustandsorientiert mit Grenzwerten.','Kupplungsbelag der Presse (sicherheitsrelevant, Verschleiß nach Hubzahl bekannt): periodisch nach Zählerstand.','Ergebnis dokumentieren und jährlich anhand der Störstatistik überprüfen.']}},
    {merke:'Keine Strategie ist für alles richtig. Entscheidend sind Ausfallfolgen, Messbarkeit des Zustands und bekannte Lebensdauer.'}
  ]},
  {t:'Qualitäts- und termingesicherte Instandhaltung',h:'Qualitäts- und termingesicherte Instandhaltung · Überwachung der Instandhaltungsqualität · Fehlerfolgen einer qualitätsmindernden Instandhaltung · Zeitliche Einordnung qualitätssichernder Aufgaben und Maßnahmen',pg:38,b:[
    {p:'Instandhaltung entfaltet ihre Wirkung nur, wenn sie nicht als reine Kostenstelle gesehen wird. Ihre Qualität zeigt sich in Verfügbarkeit, Produktqualität und Sicherheit.'},
    {ul:['Zustandsorientierte Instandhaltung braucht Maschinendatenerfassung (MDE): Laufzeiten, Schalthäufigkeiten, Stillstände und Störungen zeitgenau erfassen und automatisch zuordnen (Produktion, Stillstand, Störung)','Statistische Auswertung zeigt Grundursachen schlechter Instandhaltungsqualität und leitet Handlungsbedarf ab','Fehlerfolgen schlechter Arbeit: überschrittene Toleranzen an qualitätsrelevanten Anlagen, Produktschäden, Linienstillstand, Reparatur unter Zeit- und Platzdruck','Kontinuierliche, kurz- und langperiodische Maßnahmen im QM-System festlegen; Regelkreise einbauen, die Abweichungen von Vorgaben rechtzeitig melden','Gründe für QM in der Instandhaltung: Kundenerwartungen und Zertifizierungen, Komplexität, Kostensenkung, Ruf, Abwehr von Ansprüchen nach Produkthaftungsgesetz']},
    {p:'Der Regelkreis (siehe Kapitel Steuern und Regeln) lässt sich auf die Instandhaltungsqualität übertragen: Sollwert sind die Vorgaben (Plan, Toleranzen), Messglied sind Kennzahlen und Kontrollen, Regler ist die Führungskraft, Stellglied sind Schulung, Arbeitsanweisungen und Ressourcen.'},
    {bsp:{t:'Beispiel: Qualitätssicherung für Schmierarbeiten',b:['Problem: Nach Inspektionen mit „nachschmieren“ fallen Spindellager trotzdem aus.','Maßnahmen: Schmierplan mit Schmierstoff, Menge und Schmierstelle (Foto) im Arbeitsauftrag; Rückmeldung mit Unterschrift; Fettpresse mit Hubzähler.','Kontrolle: Meister prüft monatlich stichprobenartig 5 Aufträge vor Ort; Kennzahl „Lagerausfälle je 1 000 Bh“.','Ergebnis nach 6 Monaten bewerten und den Standard anpassen (PDCA).']}},
    {merke:'Vorgaben umsetzen und durchsetzen ist Führungsaufgabe – die Qualität der Arbeit liegt bei jedem Einzelnen. Saubere Dokumentation hilft, im Haftungsfall zu belegen, dass ein Fehler bei Auslieferung nicht vorlag.'}
  ]},
  {t:'Schwachstellen und Schadensursachen',h:'Schwachstellen und schadensverdächtige Stellen von Maschinen und Anlagen · Maschinenspezifische Schäden · Schäden an verfahrenstechnischen Anlagen · Einfluss der Schadensursachen',pg:41,abb:[['Abb. 3.1 Häufigste mechanische Schadenseinflüsse',41]],b:[
    {p:'Ein Schaden ist technisch nie ganz auszuschließen. Die Grundlage hoher Zuverlässigkeit wird in der Konstruktion gelegt; im Betrieb sichern Inspektion und Wartung die Lebensdauer. Grundsätze der Schadensanalyse beschreibt die VDI-Richtlinie 3822.'},
    {ul:['Mechanische Schadenseinflüsse: Verschleiß (auch Abrasion), Ermüdung, Korrosion, Alterung, Reibung, Gewaltbruch und Gewaltriss','Weitere Einflüsse: Betriebstemperatur, Spiel und Toleranzen, Überlast, mangelhafte Schmierung','Instandhaltungsgerechte Gestaltung: gute Zugänglichkeit, Normteile, geschützte Leitungen und Schläuche, Modulbauweise, automatische Zentralschmierung, einfacher Austausch, automatische Späneabfuhr','Verfahrenstechnische Anlagen: hochkomplex, Bedienung über Prozessleitsystem; Störfälle haben oft Umweltfolgen. Die meisten Störfälle passieren während Wartung oder Instandsetzung','Vor Ort verfügbar halten: Betriebsanweisungen, Betriebshandbuch, Sicherheitshinweise, Prozessparameterlisten, Wartungs- und Instandsetzungsdokumentation, Sicherheitsdatenblätter']},
    {ul:['Prüffragen zu Schadensursachen: Ist der Antrieb für die Betriebsart ausgelegt? Gibt es Überlastschutz? Ist die Schmierung bewegter Teile gesichert? Sind Bauteile für den Einsatzfall richtig gewählt? Braucht ein linienkritisches Aggregat Stand-by? Lassen sich Schäden schnell beheben?','Theoretische, vorbeugende Schwachstellenermittlung: Schwachpunkte vorausschauend erkennen und konstruktiv abstellen – bei sicherheitsrelevanten Teilen im Rahmen der Gefährdungsbeurteilung']},
    {svg:{w:520,h:290,body:'<line x1="30" y1="150" x2="408" y2="150" class="sk-l thick" marker-end="url(#ar)"/><rect x="410" y="120" width="100" height="60" class="sk-body"/><text x="460" y="146" text-anchor="middle" class="sk-t acc">Problem</text><text x="460" y="166" text-anchor="middle" class="sk-t">(Wirkung)</text><line x1="70" y1="45" x2="110" y2="150" class="sk-l"/><line x1="160" y1="45" x2="200" y2="150" class="sk-l"/><line x1="250" y1="45" x2="290" y2="150" class="sk-l"/><line x1="340" y1="45" x2="380" y2="150" class="sk-l"/><text x="70" y="35" text-anchor="middle" class="sk-t">Mensch</text><text x="160" y="35" text-anchor="middle" class="sk-t">Maschine</text><text x="250" y="35" text-anchor="middle" class="sk-t">Material</text><text x="340" y="35" text-anchor="middle" class="sk-t">Methode</text><line x1="90" y1="255" x2="130" y2="150" class="sk-l"/><line x1="200" y1="255" x2="240" y2="150" class="sk-l"/><line x1="310" y1="255" x2="350" y2="150" class="sk-l"/><text x="90" y="275" text-anchor="middle" class="sk-t">Messung</text><text x="200" y="275" text-anchor="middle" class="sk-t">Mitwelt</text><text x="310" y="275" text-anchor="middle" class="sk-t">Management</text>',cap:'Ursache-Wirkungs-Diagramm (Ishikawa) mit den 7 M als Hauptursachen'}},
    {bsp:{t:'Beispiel: Wiederkehrende Brüche an einer Transportkette',b:['Befund: Kettenbruch an einem Ofentransport alle 6–8 Wochen.','Ishikawa: Maschine (Kettenrad verschlissen?), Material (falsche Kettengüte für 250 °C?), Methode (Schmierung mit ungeeignetem Fett?), Mensch (Kettenspannung nach Gefühl?), Messung (keine Längungsmessung), Mitwelt (Zunder, Hitze).','Untersuchung zeigt: Standardfett verkokt, Kette läuft trocken → Verschleiß und Längung → Überlast am Kettenrad.','Abhilfe: Hochtemperaturschmierstoff, Kettenlängung als Inspektionsmerkmal, Kettenrad gemeinsam mit Kette tauschen.']}},
    {merke:'Gute Dokumentation aller Instandhaltungsarbeiten ist die Datenbasis, um Schwachstellen zu finden und dauerhaft zu beseitigen.'}
  ]},
  {t:'Schadenshäufigkeit senken: Kennzahlen und Schadensanalyse',h:'Verringerung der Schadenshäufigkeit mit organisatorischen, technischen und wirtschaftlich vertretbaren Mitteln',pg:42,b:[
    {p:'Kern des Instandhaltungskonzepts sind Störungsart, Ursache und Folgen. Passt keine Strategie (Ausfall sehr teuer, Zustand nicht messbar, keine Erfahrungswerte), bleiben Parallelanlage oder konstruktive Änderung.'},
    {fx:['MTBF = Betriebszeit / Anzahl Ausfälle','Mean Time Between Failures: mittlere störungsfreie Laufzeit']},
    {fx:['MTTR = Σ Reparaturzeiten / Anzahl Ausfälle','Mean Time To Repair: mittlere Reparaturdauer']},
    {fx:['V = MTBF / (MTBF + MTTR)','Verfügbarkeit aus den beiden Kennzahlen']},
    {fx:['OEE = Verfügbarkeit · Leistungsgrad · Qualitätsrate','Overall Equipment Effectiveness (Gesamtanlageneffektivität)']},
    {bsp:{t:'Beispiel: Kennzahlen eines Bearbeitungszentrums (ein Monat)',b:['Gegeben: geplante Laufzeit 400 h, 8 Störungen, Reparaturzeit gesamt 16 h; Solltakt 60 Teile/h; gefertigt 20 736 Teile, davon 20 321 Gutteile','Betriebszeit = 400 h − 16 h = 384 h','MTBF = 384 h / 8 = 48 h;  MTTR = 16 h / 8 = 2 h','Verfügbarkeit = 384 / 400 = 0,96 (auch 48 / (48 + 2) = 0,96)','Leistungsgrad = 20 736 / (384 h · 60 /h) = 20 736 / 23 040 = 0,90','Qualitätsrate = 20 321 / 20 736 = 0,98','OEE = 0,96 · 0,90 · 0,98 = 0,847 ≈ 84,7 %','Interpretation: Größter Hebel ist der Leistungsgrad (Kurzstillstände, reduzierte Geschwindigkeit) – dort zuerst ansetzen.']}},
    {ol:['Schaden beschreiben: Fotos, Skizzen, konstruktive und fertigungstechnische Details','Bestandsaufnahme: Anlage, Betreiber, Hersteller, Baujahr, Inbetriebnahme, Laufzeit, Vorgeschichte des Teils','Einzeluntersuchungen: Messungen, Werkstoff- und Bruchflächenuntersuchung, Schadenshypothesen prüfen','Ergebnisse auswerten: Hauptursache von Begleiteinflüssen trennen, ggf. nachuntersuchen','Abhilfemaßnahmen festlegen und Schadensbericht schreiben (kurz, aber vollständig)','Maßnahmen einleiten und Wirksamkeit kontrollieren']},
    {svg:{w:520,h:250,cap:'Pareto-Diagramm von 100 Störungen eines Montageautomaten: zwei Ursachen erklären zwei Drittel',body:'<line x1="60" y1="230" x2="500" y2="230" class="sk-l" marker-end="url(#ar)"/><line x1="60" y1="230" x2="60" y2="30" class="sk-l" marker-end="url(#ar)"/><text x="68" y="35" class="sk-t">Störungen</text><line x1="480" y1="230" x2="480" y2="40" class="sk-l"/><text x="486" y="34" class="sk-t">%</text><text x="54" y="235" text-anchor="end" class="sk-t">0</text><text x="54" y="145" text-anchor="end" class="sk-t">25</text><text x="54" y="55" text-anchor="end" class="sk-t">50</text><text x="486" y="145" class="sk-t">50</text><text x="486" y="55" class="sk-t">100</text><rect x="68" y="78.80000000000001" width="58" height="151.2" class="sk-body"/><text x="97" y="248" text-anchor="middle" class="sk-t">Greifer</text><text x="97" y="72.80000000000001" text-anchor="middle" class="sk-t">42</text><rect x="132" y="140" width="58" height="90" class="sk-body"/><text x="161" y="248" text-anchor="middle" class="sk-t">Sensor</text><text x="161" y="134" text-anchor="middle" class="sk-t">25</text><rect x="196" y="186.8" width="58" height="43.199999999999996" class="sk-body"/><text x="225" y="248" text-anchor="middle" class="sk-t">Hydraulik</text><text x="225" y="180.8" text-anchor="middle" class="sk-t">12</text><rect x="260" y="201.2" width="58" height="28.8" class="sk-body"/><text x="289" y="248" text-anchor="middle" class="sk-t">Antrieb</text><text x="289" y="195.2" text-anchor="middle" class="sk-t">8</text><rect x="324" y="212" width="58" height="18" class="sk-body"/><text x="353" y="248" text-anchor="middle" class="sk-t">SPS</text><text x="353" y="206" text-anchor="middle" class="sk-t">5</text><rect x="388" y="201.2" width="58" height="28.8" class="sk-body"/><text x="417" y="248" text-anchor="middle" class="sk-t">Sonstige</text><text x="417" y="195.2" text-anchor="middle" class="sk-t">8</text><polyline points="97,154.5 161,109.5 225,88 289,73.5 353,64.5 417,50" class="sk-f"/><circle cx="97" cy="154.4" r="3.5" class="fillacc"/><circle cx="161" cy="109.39999999999999" r="3.5" class="fillacc"/><circle cx="225" cy="87.79999999999998" r="3.5" class="fillacc"/><circle cx="289" cy="73.4" r="3.5" class="fillacc"/><circle cx="353" cy="64.4" r="3.5" class="fillacc"/><circle cx="417" cy="50" r="3.5" class="fillacc"/><line x1="60" y1="86" x2="480" y2="86" class="sk-c"/><text x="330" y="106" text-anchor="middle" class="sk-t acc">80 %-Linie</text>'}},
    {ul:['Werkzeuge: Pareto-Analyse (Wichtiges zuerst), Ishikawa-Diagramm mit 7 M (Mensch, Maschine, Material, Methode, Messung, Management, Mitwelt), FMEA (Fehlermöglichkeiten vorab bewerten), Fehlerbaumanalyse','Wöchentliche Störungsbesprechung Produktion/Instandhaltung mit Pareto-Auswertung ist ein bewährtes Ritual']},
    {merke:'Systematische Schwachstellenbekämpfung = Schwachstellen ermitteln, Ursachen erforschen, Schwachstellen beseitigen und Erfolg kontrollieren.'},
    {falle:'MTBF wird mit der Betriebszeit gerechnet, nicht mit der Kalenderzeit oder der geplanten Zeit inklusive Reparaturen.'}
  ]},
  {t:'Eingriffszeitpunkte für Instandhaltungen',h:'Eingriffszeitpunkte für Instandhaltungen',pg:44,abb:[['Abb. 3.2 Verlauf des Abnutzungsgrades nach DIN 31051',44]],b:[
    {p:'Jeder geplante Eingriffszeitpunkt ist ein Kompromiss: Wartungsintervalle werden aus Kostengründen gestreckt, doch mit sinkendem Abnutzungsvorrat steigt die Ausfallwahrscheinlichkeit.'},
    {svg:{w:520,h:250,cap:'Ausfallrate über der Lebensdauer („Badewannenkurve“)',body:'<line x1="50" y1="220" x2="505" y2="220" class="sk-l" marker-end="url(#ar)"/><line x1="50" y1="220" x2="50" y2="20" class="sk-l" marker-end="url(#ar)"/><text x="58" y="25" class="sk-t">Ausfallrate</text><text x="500" y="212" text-anchor="end" class="sk-t">Zeit</text><polyline points="60,106 71,133.5 81.5,153 92.5,167 103,176.5 114,183.5 124.5,188 135.5,191.5 146,194 157,195.5 167.5,197 178.5,197.5 189,198 200,198.5 210.5,199 221.5,199 232,199.5 243,199.5 253.5,199.5 264.5,199.5 275,199.5 286,199.5 296.5,199.5 307.5,199.5 318,199.5 329,199.5 339.5,199.5 350.5,199.5 361,199 372,197 382.5,193 393.5,187 404,180 415,170.5 425.5,160 436.5,147 447,133 458,117 468.5,99 479.5,80 490,58.5" class="sk-l thick"/><line x1="130" y1="40" x2="130" y2="220" class="sk-c"/><line x1="352" y1="40" x2="352" y2="220" class="sk-c"/><text x="90" y="240" text-anchor="middle" class="sk-t">Frühausfälle</text><text x="240" y="240" text-anchor="middle" class="sk-t">Zufallsausfälle</text><text x="425" y="240" text-anchor="middle" class="sk-t">Verschleiß</text><text x="140" y="90" class="sk-t">Montage-,</text><text x="140" y="108" class="sk-t">Werkstofffehler</text><text x="362" y="90" class="sk-t acc">vorbeugend</text><text x="362" y="108" class="sk-t acc">tauschen</text>'}},
    {tab:[['Zeitpunkt','Kennzeichen','Bewertung'],['nach Ausfall','Stillstand ist schon eingetreten','ungünstigste Variante, Gefahr von Folgeschäden'],['vorzeitig','Verschleißgeräusche, sichtbare Ermüdung oder bekannte Lebensdauer (z. B. Schaltspiele)','Teil wird vor dem Ausfall getauscht'],['nach Wahrscheinlichkeit','Lebensdauerangaben, Erfahrungswerte, KI-gestützte Prognose','Tausch vor Erreichen der Garantiegrenze, besonders ohne Redundanz']]},
    {ul:['Die sicherste Vermeidung ungeplanter Eingriffe ist regelmäßige Wartung und Inspektion','Lebensdauerprognosen gelten nur für die angenommene Belastung','Instandhaltungssoftware mit KI kann Ausfallwahrscheinlichkeiten und optimale Eingriffszeitpunkte berechnen']},
    {bsp:{t:'Beispiel: Tauschzeitpunkt eines Leistungsschützes planen',b:['Gegeben: elektrische Lebensdauer 2 000 000 Schaltspiele; 4 Schaltungen pro Minute; 2 Schichten à 7,5 h; 220 Arbeitstage','Schaltspiele pro Jahr: 4 · 60 · 15 · 220 = 792 000','Lebensdauer erreicht nach 2 000 000 / 792 000 = 2,5 Jahren','Entscheidung: Tausch nach ca. 2 Jahren im geplanten Betriebsurlaub, weil die Anlage keine Redundanz hat und ein Ausfall die Linie stoppt.']}},
    {merke:'Crash-, periodisch vorbeugende und zustandsabhängige Instandhaltung unterscheiden und mit Vor- und Nachteilen begründen können – ein Klassiker in der Prüfung.'}
  ]},
  {t:'Energiegewinnung, Energiearten und Energiesparen',h:'Aufrechterhalten der Energieversorgung im Betrieb · Energiegewinnung und -umwandlung · Energieeinsparung und -bereitstellung',pg:48,abb:[['Abb. 4.1 Funktionsprinzip von Wärmekraftwerken',49]],b:[
    {p:'Nach dem Energieerhaltungssatz wird Energie nur umgewandelt; am Ende landet sie als niederwertige Wärme in der Umwelt. Energiekosten und -effizienz entscheiden zunehmend über die Wettbewerbsfähigkeit.'},
    {svg:{w:520,h:175,cap:'Von der Primär- zur Nutzenergie: jede Umwandlung kostet Verluste',body:'<rect x="10" y="40" width="105" height="50" class="sk-body"/><text x="62.5" y="61" text-anchor="middle" class="sk-t">Primär-</text><text x="62.5" y="79" text-anchor="middle" class="sk-t">energie</text><rect x="140" y="40" width="105" height="50" class="sk-body"/><text x="192.5" y="61" text-anchor="middle" class="sk-t">Sekundär-</text><text x="192.5" y="79" text-anchor="middle" class="sk-t">energie</text><rect x="270" y="40" width="105" height="50" class="sk-body"/><text x="322.5" y="61" text-anchor="middle" class="sk-t">End-</text><text x="322.5" y="79" text-anchor="middle" class="sk-t">energie</text><rect x="400" y="40" width="110" height="50" class="sk-body"/><text x="455" y="61" text-anchor="middle" class="sk-t acc">Nutz-</text><text x="455" y="79" text-anchor="middle" class="sk-t">energie</text><line x1="115" y1="65" x2="138" y2="65" class="sk-f" marker-end="url(#ar)"/><line x1="245" y1="65" x2="268" y2="65" class="sk-f" marker-end="url(#ar)"/><line x1="375" y1="65" x2="398" y2="65" class="sk-f" marker-end="url(#ar)"/><text x="62" y="115" text-anchor="middle" class="sk-t">Kohle, Gas,</text><text x="62" y="133" text-anchor="middle" class="sk-t">Wind, Sonne</text><text x="192" y="115" text-anchor="middle" class="sk-t">Strom, Heizöl,</text><text x="192" y="133" text-anchor="middle" class="sk-t">Diesel</text><text x="322" y="115" text-anchor="middle" class="sk-t">Strom am</text><text x="322" y="133" text-anchor="middle" class="sk-t">Zähler</text><text x="455" y="115" text-anchor="middle" class="sk-t">Bewegung,</text><text x="455" y="133" text-anchor="middle" class="sk-t">Wärme, Licht</text><text x="260" y="165" text-anchor="middle" class="sk-t acc">Verluste: Kraftwerk, Netz, Motor, Getriebe …</text>'}},
    {ul:['Primärenergie: noch nicht umgewandelt (Steinkohle, Braunkohle, Erdöl, Erdgas, Kernbrennstoff, Sonne, Wind, Wasser)','Sekundärenergie: umgewandelt in eine verbrauchsgerechte Form (Strom, Benzin, Diesel, Heizöl) – mit Umwandlungsverlusten und Eigenbedarf','Nutzenergie: was der Verbraucher tatsächlich nutzt (Antrieb, Heiz- und Prozesswärme, Licht)','Wärmekraftwerk: Kessel erzeugt Dampf, Dampf treibt Turbine und Generator, Kondensat geht zurück; rund zwei Drittel der Brennstoffwärme gehen als Abwärme verloren']},
    {tab:[['Erneuerbare Quelle','Prinzip','Hinweis'],['Wasserkraft','Speicher-, Pumpspeicher-, Fluss-, Gezeitenkraftwerk','Kaplan bei Flusskraftwerken, Francis/Pelton bei Speichern'],['Wind','Rotor treibt Generator','schwankend, braucht Verbund und Speicher'],['Solarthermie','Kollektor erwärmt Wärmeträger','Trinkwasser, Heizung, Prozesswärme'],['Solarthermisches Kraftwerk','Spiegel bündeln Licht, Wärme treibt Turbine','große Anlagen in sonnenreichen Regionen'],['Fotovoltaik','Solarzelle wandelt Licht direkt in Strom','Dachanlagen im Betrieb, Eigenverbrauch'],['Biomasse','Verbrennung von Holz, Stroh, Biogas','Strom und Fern-/Nahwärme'],['Brennstoffzelle','Wasserstoff + Sauerstoff → Strom, Wärme, Wasser','keine bewegten Teile; Umkehrung der Elektrolyse'],['Geothermie','Erdwärme oberflächennah oder tief','Heizen, Kühlen, Strom']]},
    {ul:['Energiewende: weg von Kern- und fossilen Brennstoffen, hin zu erneuerbaren Energien und Effizienz; Kernkraft seit 2023 beendet, Kohleausstieg bis spätestens 2038; Erneuerbare liefern inzwischen über die Hälfte des Stroms','Optimierung beginnt mit der Messung der Ist-Verbräuche (Energiemanagement, z. B. ISO 50001)','Strom zum Heizen ist die teuerste Variante; größter Stromverbraucher im Betrieb sind Elektromotoren','Effizienzklassen IE1 (Standard) bis IE5 (Ultra Premium); für Neumotoren 0,75–1000 kW gilt mindestens IE3, 75–200 kW mindestens IE4','Sparmaßnahmen: unnötigen Verbrauch vermeiden, Wirkungs- und Nutzungsgrade verbessern, spezifischen Verbrauch senken, Wärme zurückgewinnen, dämmen, regenerative Quellen nutzen']},
    {bsp:{t:'Beispiel: Lohnt sich ein IE4-Motor statt IE2?',b:['Gegeben: Wellenleistung 30 kW, 6 000 h/a, η_IE2 = 92,0 %, η_IE4 = 94,5 % (Beispielwerte), Strompreis 0,20 €/kWh','Aufnahme IE2: 30 / 0,920 = 32,61 kW; IE4: 30 / 0,945 = 31,75 kW','Differenz: 0,86 kW · 6 000 h = 5 176 kWh pro Jahr → ca. 1 035 € pro Jahr','Bei Mehrkosten von z. B. 1 500 € amortisiert sich der IE4-Motor in rund 1,5 Jahren.']}},
    {merke:'Energie sparen ist nicht nur Umweltschutz, sondern ein betriebswirtschaftlicher Faktor. Ohne Messung keine Optimierung.'}
  ]},
  {t:'Stromversorgung und Ersatzstrom',h:'Energieversorgung des Betriebs · Stromversorgung des Betriebs für Maschinen, verfahrenstechnische Anlagen, Ver- und Entsorgungssysteme',pg:51,abb:[['Tab. 4.1 Stromnetz in Deutschland',51]],b:[
    {p:'Elektrische Energie lässt sich kaum speichern; Erzeugung und Verbrauch müssen jederzeit übereinstimmen. Für Betriebe ist die ständige Verfügbarkeit lebenswichtig – Steuerungen, IT und Kühlwasserpumpen dürfen nicht ausfallen.'},
    {tab:[['Netzebene','Spannung','Aufgabe'],['Höchstspannung (Übertragungsnetz)','220 / 380 kV (HGÜ bis 525 kV)','Transport über weite Strecken, europäischer Verbund'],['Hochspannung','ca. 60–110 kV','Verteilung an Umspannwerke und Großindustrie'],['Mittelspannung','ca. 10–30 kV','regionale Trafostationen, Industrie- und Gewerbebetriebe'],['Niederspannung','230 / 400 V','Ortsnetze, Endverbraucher, Maschinenanschluss']]},
    {ul:['Übertragungsmittel (Betriebsmittel): Freileitungen, Erdkabel, Stromschienen, Transformatoren','Freileitungen aus Kostengründen v. a. im Höchst- und Hochspannungsnetz, Erdkabel v. a. in Mittel- und Niederspannung','Größere Betriebe beziehen Mittelspannung und betreiben eine eigene Trafostation']},
    {tab:[['Ersatzversorgung','Merkmal','Einsatz'],['USV (unterbrechungsfreie Stromversorgung)','Batterie mit Wechselrichter, keine Umschaltlücke; teuer','IT, Steuerungen, Brandschutztore, Messtechnik'],['Notstromaggregat (Notstrombetrieb)','Verbrennungsmotor + Generator, Start in Sekunden; nur kurzzeitig','Sicherheitsbeleuchtung, Kühlwasser, Gefahrenabwehr'],['Netzersatzanlage (Netzersatzbetrieb)','Dauerbetrieb über Stunden bis Wochen; niedrige Drehzahl, Aufstellort und Leistung auf Dauerlast ausgelegt','ganze Produktionsbereiche, Inselbetrieb']]},
    {ul:['Gründe für Ersatzstrom: gesetzliche Forderungen, unzuverlässiges Netz, Prozesse müssen abgesichert laufen, kein oder schwieriger Netzanschluss','Kurze Unterbrechungen genügen, um Steuerungen und Rechner abstürzen zu lassen – empfindliche Verbraucher immer über USV']},
    {bsp:{t:'Beispiel: USV für den Leitrechner einer Anlage',b:['Gegeben: Verbraucherleistung 2,4 kW, geforderte Überbrückung 15 min bis zum kontrollierten Herunterfahren; Wirkungsgrad Wechselrichter 0,9','Energie: 2,4 kW · 0,25 h = 0,6 kWh','Batterieseitig: 0,6 kWh / 0,9 = 0,67 kWh nutzbare Kapazität, plus Alterungsreserve','Organisatorisch: Akkutest halbjährlich, Austausch der Batterien nach Herstellerangabe, Umschaltung jährlich unter Last testen und dokumentieren.']}},
    {merke:'USV = ohne Unterbrechung, kurze Dauer. Notstromaggregat = kurze Lücke, begrenzte Dauer. Netzersatzanlage = lange Dauer.'}
  ]},
  {t:'Wasserversorgung und -entsorgung',h:'Wasserversorgung und -entsorgung für den Betrieb',pg:53,abb:[['Abb. 4.2 Grundanforderungen an Trinkwasser',54]],b:[
    {p:'Nur ein sehr kleiner Teil des Wassers der Erde ist Süßwasser in nutzbarer Form. Industrie und Gewerbe verbrauchen in Deutschland den größten Anteil. Wasser wird teurer – sparsamer Umgang zahlt sich aus.'},
    {tab:[['Ebene','Regelungen'],['EU','Wasserrahmenrichtlinie, Trinkwasserrichtlinie'],['Bund','Wasserhaushaltsgesetz (WHG), Abwasserabgabengesetz (AbwAG), Abwasserverordnung (AbwV), Trinkwasserverordnung (TrinkwV), Verordnung über Anlagen zum Umgang mit wassergefährdenden Stoffen (AwSV)'],['Land','Landeswassergesetze'],['Kommune','Entwässerungssatzungen, Indirekteinleitergenehmigung']]},
    {tab:[['Wasserart','Anforderung','Hinweis'],['Trinkwasser','keimarm, frei von Krankheitserregern, farblos, kühl, geruchs- und geschmacksneutral, Grenzwerte der TrinkwV, nicht korrosiv, ausreichend Menge und Druck','meist aus Grundwasser; DIN 2000 und Technische Regeln'],['Brauch-/Nutzwasser','nach Prozessbedarf, gewisse Mindesthygiene; filtern, enthärten, entsalzen','entlastet Trinkwasser, spart Kosten'],['Warmwasser','ca. 30–60 °C (darüber Heißwasser); wirtschaftlich, zweckmäßig, betriebssicher (keine Verbrühung, Verkalkung, Korrosion)','Erwärmer, Regelung mit Thermostat und Sicherheitsventil, Zirkulationspumpe, Verteilleitungen'],['Kühl-, Kessel-, VE-Wasser','je nach Zweck: Härte entfernen, vollentsalzt für Dampferzeuger','Kesselstein mindert Wärmeübergang und Funktion']]},
    {ul:['Wird hartes Wasser über ca. 60 °C erwärmt, fällt Kalk aus und das Wasser wird aggressiver (Korrosion) – für Heiz- und Kühlkreisläufe Härte entfernen','Abwasserarten: Schmutzwasser (Haushalt, Gewerbe, Industrie), Niederschlagswasser, unverschmutztes Kühl- und Tropfwasser, kontaminiertes Abwasser, Sickerwasser','Abwasser nach Stand der Technik behandeln: mechanisch/physikalisch, biologisch, chemisch; branchenspezifische Mindestanforderungen in den Anhängen der AbwV','Rund 80 % des genutzten Wassers kehren als Abwasser in den Kreislauf zurück']},
    {bsp:{t:'Beispiel: Kühlwasserkreislauf statt Durchlaufkühlung',b:['Gegeben: Härteofenkühlung mit Durchlaufwasser 3 m³/h, 4 000 h/a; Kosten Frisch- und Abwasser 4,50 €/m³','Verbrauch: 3 m³/h · 4 000 h = 12 000 m³ → 54 000 € pro Jahr','Mit geschlossenem Kreislauf und Rückkühler bleiben ca. 5 % Ergänzungswasser: 600 m³','Einsparung: 11 400 m³ · 4,50 €/m³ = 51 300 € pro Jahr (abzüglich Strom für Rückkühler und Pumpe)','Zusatznutzen: Abwärme kann Waschanlage oder Hallenheizung vorwärmen.']}},
    {merke:'Trinkwasser ist durch nichts zu ersetzen; seine Beschaffenheit regelt die Trinkwasserverordnung. Für Prozesse genügt meist aufbereitetes Brauchwasser.'}
  ]},
  {t:'Raumluft, Absauge- und Abscheideanlagen',h:'Raumluftversorgung · Absauge- und Abscheideanlagen',pg:56,abb:[['Tab. 4.2 Lufttechnische Anlagen',56],['Abb. 4.3 Schema einer Absauganlage',57]],b:[
    {p:'Lüftungs- und Klimatechnik hält in Räumen einen festgelegten Zustand aus Temperatur, Luftbewegung, Feuchte und Reinheit. In der Industrie dienen Anlagen dem Arbeitsschutz (ArbStättV, ASR A3.6 Lüftung) und dem Prozess (Lackiererei, Elektronik).'},
    {tab:[['Anlage','Wirkungsweise'],['freie Lüftung','Luftwechsel durch Temperaturunterschied oder Wind, keine Aufbereitung'],['einfache Lüftungsanlage','Ventilatoren erzwingen den Luftwechsel'],['Lüftung mit Luftbehandlung','zusätzlich heizen, kühlen, befeuchten oder entfeuchten'],['Klimaanlage','hält Temperatur und Feuchte selbsttätig auf Sollwerten'],['industrielle Absaugung','erfasst Gase, Rauch, Staub, Dämpfe, Späne an der Quelle'],['Sonderanlagen','Reinräume, Klimaprüfräume, Luftschleusen']]},
    {ul:['Grundaufgaben: Luftverunreinigungen abführen, aufbereitete Zuluft zuführen, Wärme abführen, unerwünschten Luftaustausch verhindern','Energie: Wärmerückgewinnung – die warme Fortluft erwärmt über einen Wärmetauscher die kalte Außenluft','Absauganlage: Erfassungseinrichtung an der Quelle, Saugleitung, Ventilator, Druckleitung, Abscheider/Filter zur Sammlung oder Rückgewinnung','Schadstoffe möglichst dort erfassen, wo sie entstehen – bevor sie in den Atembereich gelangen (Rangfolge nach GefStoffV)']},
    {bsp:{t:'Beispiel: Schweißrauchabsaugung an Roboterzellen',b:['Problem: Hallenluft trüb, Grenzwerte für Schweißrauch gefährdet.','Lösung: Absaughaube über jeder Zelle, zentrale Filteranlage mit Abreinigung; gefilterte Luft im Winter zurück in die Halle (Umluft nur mit geprüfter Filterklasse), im Sommer als Fortluft.','Instandhaltung: Differenzdruck am Filter täglich ablesen, Staubsammelbehälter leeren, jährliche Wirksamkeitsprüfung dokumentieren.']}},
    {merke:'Luftschadstoffe an der Entstehungsstelle erfassen ist wirksamer und billiger als die ganze Halle zu lüften.'}
  ]},
  {t:'Druckluftversorgung',h:'Druckluftversorgung',pg:57,abb:[['Tab. 4.3 Vorteile und Anwendungen von Druckluft',57]],b:[
    {p:'Druckluft ist flexibel, sauber und überlastsicher – aber die teuerste Energieform im Betrieb. Nur ein kleiner Teil der eingesetzten elektrischen Energie kommt als Arbeit am Werkzeug an. Deshalb gezielt einsetzen und das Netz optimieren.'},
    {tab:[['Vorteile','Anwendungen'],['leicht zu transportieren und gut speicherbar','Spannen und Klemmen'],['sauber, trocken, explosionsgeschützt einsetzbar','Transportieren von Schütt- und Stückgut'],['überlastsicher, betriebs- und unfallsicher','Spritzen, Strahlen, Blasen'],['stufenlos regelbar, einfach herzustellen','Antriebe: Werkzeuge, Motoren, Hämmer; Prüfen, Steuern, Regeln']]},
    {ul:['Druckbereiche: Niederdruck bis 10 bar, Mitteldruck bis 40 bar, Hochdruck darüber','Erzeugung: vorzugsweise Schrauben- oder Turboverdichter im Dauerbetrieb, Kolbenverdichter im Kurzzeitbetrieb','Kette: verdichten, kühlen (Luft- oder Wasserkühlung, Wärmerückgewinnung), nachkühlen und Kondensat abscheiden, speichern, trocknen, filtern (Restöl), verteilen, Kondensat aufbereiten','Trocknung: Kältetrockner (Drucktaupunkt ca. +3 °C), Adsorptionstrockner (bis −40 °C und tiefer); Absorption chemisch','Speicher (Windkessel): gleicht bei Kolbenverdichtern Pulsation aus und fängt Verbrauchsspitzen ab']},
    {svg:{w:520,h:260,body:'<rect x="20" y="30" width="140" height="50" class="sk-body"/><text x="90" y="60" text-anchor="middle" class="sk-t">Ansaugfilter</text><line x1="160" y1="55" x2="188" y2="55" class="sk-f" marker-end="url(#ar)"/><rect x="190" y="30" width="140" height="50" class="sk-body"/><text x="260" y="60" text-anchor="middle" class="sk-t">Verdichter</text><line x1="330" y1="55" x2="358" y2="55" class="sk-f" marker-end="url(#ar)"/><rect x="360" y="30" width="140" height="50" class="sk-body"/><text x="430" y="60" text-anchor="middle" class="sk-t">Nachkühler</text><line x1="460" y1="80" x2="460" y2="148" class="sk-f" marker-end="url(#ar)"/><rect x="390" y="150" width="115" height="50" class="sk-body"/><text x="447" y="180" text-anchor="middle" class="sk-t">Druckbehälter</text><line x1="390" y1="175" x2="372" y2="175" class="sk-f" marker-end="url(#ar)"/><rect x="265" y="150" width="105" height="50" class="sk-body"/><text x="317" y="180" text-anchor="middle" class="sk-t">Trockner</text><line x1="265" y1="175" x2="247" y2="175" class="sk-f" marker-end="url(#ar)"/><rect x="140" y="150" width="105" height="50" class="sk-body"/><text x="192" y="180" text-anchor="middle" class="sk-t">Feinfilter</text><line x1="140" y1="175" x2="122" y2="175" class="sk-f" marker-end="url(#ar)"/><rect x="15" y="150" width="105" height="50" class="sk-body"/><text x="67" y="180" text-anchor="middle" class="sk-t">Ringnetz</text><line x1="400" y1="80" x2="400" y2="118" class="sk-c"/><text x="395" y="112" text-anchor="end" class="sk-t">Kondensat</text><line x1="447" y1="200" x2="447" y2="230" class="sk-c"/><line x1="317" y1="200" x2="317" y2="230" class="sk-c"/><text x="380" y="248" text-anchor="middle" class="sk-t">Kondensat → Aufbereitung</text>',cap:'Druckluftkette: erzeugen, kühlen, speichern, trocknen, filtern, verteilen'}},
    {tab:[['Versorgung','Vorteile'],['zentral','geringere Installations- und Energiekosten, weniger Platz, einfache Überwachung, günstigere Wartung, einheitliche Qualität, Wärmerückgewinnung möglich'],['dezentral','Kompressor passt genau zum Bedarf, kurze Netze mit wenig Leckage, Störung trifft nur einen Bereich; sinnvoll für Sonderdrücke']]},
    {svg:{w:520,h:290,cap:'Druckluftnetz als Ringleitung: Abgänge nach oben, Gefälle zum Kondensatablass am Tiefpunkt',body:'<text x="150" y="28" class="sk-t">Abgänge oben (Schwanenhals)</text><rect x="10" y="110" width="95" height="50" class="sk-body"/><text x="57.5" y="131" text-anchor="middle" class="sk-t">Kompressor-</text><text x="57.5" y="149" text-anchor="middle" class="sk-t">station</text><line x1="105" y1="135" x2="150" y2="135" class="sk-l thick"/><rect x="150" y="80" width="340" height="150" class="sk-l thick"/><path d="M200,80 V52 Q200,44 208,44 H222 Q230,44 230,52 V105" class="sk-l"/><rect x="218" y="105" width="24" height="22" class="sk-body"/><text x="230" y="121" text-anchor="middle" class="sk-t">V1</text><path d="M300,80 V52 Q300,44 308,44 H322 Q330,44 330,52 V105" class="sk-l"/><rect x="318" y="105" width="24" height="22" class="sk-body"/><text x="330" y="121" text-anchor="middle" class="sk-t">V2</text><path d="M400,80 V52 Q400,44 408,44 H422 Q430,44 430,52 V105" class="sk-l"/><rect x="418" y="105" width="24" height="22" class="sk-body"/><text x="430" y="121" text-anchor="middle" class="sk-t">V3</text><text x="320" y="175" text-anchor="middle" class="sk-t">Ringleitung</text><line x1="490" y1="230" x2="490" y2="250" class="sk-l"/><rect x="470" y="250" width="40" height="18" class="sk-body"/><text x="460" y="284" text-anchor="middle" class="sk-t">Kondensatablass</text><line x1="170" y1="252" x2="445" y2="252" class="sk-f" marker-end="url(#ar)"/><text x="300" y="244" text-anchor="middle" class="sk-t">Gefälle ca. 1–2 %</text>'}},
    {ul:['Ringleitung bevorzugt (Versorgung von zwei Seiten, geringer Druckabfall), Stichleitungen zu den Entnahmestellen','Abgänge nach oben, damit Kondensat nicht zu den Verbrauchern läuft; Leitungen mit Gefälle, Entwässerung an Tiefpunkten','Druckabfall im Netz klein halten (Richtwert ≤ 0,1 bar), Druck an der Entnahmestelle konstant, Luftqualität nach Bedarf (z. B. ISO 8573-1)','Leckagen regelmäßig orten (Ultraschall) und beseitigen']},
    {bsp:{t:'Beispiel: Kosten von Leckagen',b:['Messung am Wochenende: Kompressor muss bei stehender Produktion 1,2 m³/min nachliefern – das ist reine Leckage.','Jahresmenge bei 6 000 h Netzbetrieb: 1,2 m³/min · 60 · 6 000 = 432 000 m³','Spezifischer Energiebedarf ca. 0,12 kWh/m³ → 51 840 kWh; bei 0,20 €/kWh ≈ 10 370 € pro Jahr','Leckageortung und Abdichten kosten einen Bruchteil davon – Maßnahme mit sehr kurzer Amortisation.']}},
    {bsp:{t:'Beispiel: Rohrdurchmesser für eine Druckluftleitung',b:['Gegeben: Liefermenge 6 m³/min (Ansaugzustand), Betriebsdruck 7 bar Überdruck ≈ 8 bar absolut, zulässige Strömungsgeschwindigkeit 6 m/s','Volumenstrom im Rohr: 6 m³/min / 8 = 0,75 m³/min = 0,0125 m³/s','Querschnitt: A = Q / v = 0,0125 / 6 = 0,00208 m²','Innendurchmesser: d = √(4 · A / π) = 0,0515 m ≈ 52 mm → nächstgrößeres Normrohr wählen','Hinweis: Für das Netz lieber eine Nennweite größer wählen – Druckverlust kostet dauerhaft Energie.']}},
    {merke:'Druckluft so wenig wie möglich, so viel wie nötig. Leckagen von 20–30 % des Verbrauchs sind in vielen Netzen üblich und ein großes Sparpotenzial.'}
  ]},
  {t:'Gasversorgung',h:'Gasversorgung',pg:59,b:[
    {p:'Erdgas kommt meist über das Leitungsnetz des Versorgers; technische Gase (Argon, CO₂, Sauerstoff, Acetylen, Stickstoff) über Flaschen- oder Bündelbatterien oder Tanks. Die Wahl hängt vom Verbrauch, vom Wechselaufwand und vom Platz ab.'},
    {ul:['Flaschen-/Bündelbatterie mit Umschalteinrichtung: Weiterbetrieb während des Wechsels','Zentrale Versorgung: Gas aus Speicher, Batterie oder Tank über ein Rohrnetz an die Entnahmestellen','Erdgasanlagen auf dem Werksgelände sind Energieanlagen nach Energiewirtschaftsgesetz (EnWG); anerkannte Regel der Technik ist das DVGW-Regelwerk','Bestandteile: Anschlussleitung, Gasdruckregel- und Messanlage in der Übergabestation, erdverlegte und oberirdische Werksleitungen bis zu Brennern und Heizungsanlagen','Wiederkehrende Prüfung in festgelegten Abständen durch Fachfirmen oder befähigte Mitarbeitende; Ergebnisse schriftlich festhalten','Leitungsschäden entstehen durch Alterung, Verkehrslast und Bauarbeiten – deshalb regelmäßige Rohrnetzüberprüfung']},
    {bsp:{t:'Beispiel: Schutzgasversorgung für eine Schweißerei',b:['Bisher: 10 Einzelflaschen an den Schweißplätzen, häufiger Wechsel, Stolper- und Umfallgefahr.','Neu: zentrale Bündelbatterie im Freien mit automatischer Umschaltung, Rohrleitung zu Entnahmestellen mit Druckminderer.','Vorteile: kein Transport von Flaschen in die Halle, keine Restgasverluste, weniger Stillstand.','Pflichten: Dichtheitsprüfung, Kennzeichnung der Leitungen, Gefährdungsbeurteilung (Erstickungsgefahr bei Argon/CO₂ in Gruben), Unterweisung.']}},
    {merke:'Gasanlagen regelmäßig prüfen und dokumentieren – Schäden entstehen oft unbemerkt von außen.'}
  ]},
  {t:'Aufstellen von Anlagen: Ort, Medien, Fundament, Montage',h:'Aufstellen und Inbetriebnehmen von Anlagen und Einrichtungen, insbesondere unter Beachtung sicherheitstechnischer und anlagenspezifischer Vorschriften · Funktionsnotwendige Bedingungen beim Aufstellen und Inbetriebnehmen von Anlagen und Einrichtungen · Aufstellen von Anlagen und Einrichtungen in ihrer Auswirkung auf die zu erbringende Funktion · Geeignete Fundamente · Fachgerechte Montage',pg:64,b:[
    {p:'Bevor eine Anlage produzieren kann, muss sie fachgerecht aufgestellt und in Betrieb genommen werden. Die Inbetriebnahmekosten können bis rund 20 % der Investition erreichen – sorgfältige Vorbereitung spart Zeit und Geld.'},
    {ol:['Aufstellen und Ausrichten','Medienanschlüsse herstellen (Strom, Druckluft, Dampf, Wasser …)','Steuerung bzw. Regelung einstellen','Funktionskontrolle durch Probeläufe','Abnahmeprotokoll erstellen']},
    {ul:['Herstellervorschriften für Transport, Montage und Aufstellung lückenlos einhalten und dokumentieren – wichtig für Funktion und Garantie','Aufstellort abhängig von der Fertigungsorganisation (Fließ-, Insel-, Werkstattfertigung)','Funktionsfläche: Platz für Bedienung, Wartung und Verkehrswege nach ArbStättV und ASR (z. B. ASR A1.2 Raumabmessungen und Bewegungsflächen, ASR A1.8 Verkehrswege)','Belüftung/Klima: Elektronik verträgt nur begrenzte Umgebungstemperaturen; Arbeits-, Umwelt- und Gesundheitsschutz (ArbSchG, BImSchG) beachten','Lärm und Vibration: Grenzwerte der LärmVibrationsArbSchV für Beschäftigte, Immissionsrichtwerte nach BImSchG/TA Lärm je nach Gebietsart (Industrie-, Gewerbe-, Mischgebiet)','Aufstellung im Freien: Witterungsschutz und Schutz vor Unbefugten']},
    {tab:[['Medium','Festlegen'],['elektrische Energie','Spannung (400/500/690 V), Anschlussleistung, Absicherung'],['Druckluft','Druck, Qualität, Volumenstrom (z. B. 300 l/min bei 6 bar)'],['Dampf, Stickstoff','Druck, Qualität, Volumenstrom'],['Wasser','Druck, Temperatur, Volumenstrom'],['Schmierstoffe, Chemikalien','Menge und Sorte bzw. Reinheit'],['Entsorgung: Kondensat, Abwasser, Emulsion, Säuren, Laugen','Menge, Konzentration, Temperatur']]},
    {ul:['Fundament nach Fundamentplan des Herstellers; bei großen Anlagen Bodengutachten und Statik; Ebenheit und Tragfähigkeit bestimmen Präzision und Funktionssicherheit','Montage: Komplettanlagen oft durch Hersteller oder Projektfirma, kleinere Maschinen durch den Betreiber','Ausrichten ist entscheidend: Fehlausrichtung ist Hauptursache für Ausfälle rotierender Maschinen (Lager, Dichtungen, Kupplungen) – Laser-Ausrichtsystem nutzen','Abnahme der Präzision über Messprotokolle oder Probewerkstücke']},
    {bsp:{t:'Beispiel: Aufstellung eines Bearbeitungszentrums vorbereiten',b:['4 Wochen vorher: Fundamentplan prüfen, Bodenplatte auf Tragfähigkeit und Ebenheit messen lassen, Kranbahn/Transportweg klären.','Medien: 400 V/63 A Zuleitung durch Elektrofachkraft, Druckluft 6 bar mit Wartungseinheit, Kühlschmierstoff-Erstbefüllung bestellen, Späne-Entsorgung festlegen.','Umfeld: Abstand zu Nachbarmaschinen für Schaltschranktür und Späneförderer, Fluchtwege freihalten.','Am Aufstelltag: Transportsicherungen entfernen, ausrichten mit Präzisionswasserwaage, Dokumentation und Messprotokoll ablegen.']}},
    {merke:'Herstellerangaben zu Fundament, Medien und Ausrichtung sind Teil der Gewährleistungsbedingungen – Abweichungen gefährden Garantieansprüche.'}
  ]},
  {t:'Vorabnahme: Rechtsrahmen, Konformität und CE',h:'Funktionsnotwendige Bedingungen bei Vorabnahme und Inbetriebnahme von Anlagen',pg:66,abb:[['Abb. 5.1 Darstellung der CE-Kennzeichnung',68]],b:[
    {p:'Mit jeder Maschine liefert der Hersteller technische Unterlagen, darunter die Bestätigung, dass die geltenden Vorschriften eingehalten sind. Der Meister prüft bei der Vorabnahme Dokumentation und Kennzeichnung, bevor in Betrieb genommen wird.'},
    {tab:[['Regelwerk','Adressat','Inhalt'],['Maschinenrichtlinie 2006/42/EG, ab 20.01.2027 Maschinenverordnung (EU) 2023/1230','Hersteller','Risikobeurteilung, Bau nach Sicherheitsanforderungen, Betriebsanleitung, Konformitätserklärung, CE'],['Niederspannungsrichtlinie, EMV-Richtlinie','Hersteller','elektrische Sicherheit, elektromagnetische Verträglichkeit'],['Druckgeräterichtlinie 2014/68/EU','Hersteller','Kategorien nach Druck × Volumen und Fluid'],['PSA-Verordnung (EU) 2016/425','Hersteller','persönliche Schutzausrüstung'],['Produktsicherheitsgesetz (ProdSG)','Hersteller, Händler','nationale Regeln für das Inverkehrbringen'],['Betriebssicherheitsverordnung (BetrSichV)','Arbeitgeber/Betreiber','Gefährdungsbeurteilung, sichere Verwendung, Prüfungen, überwachungsbedürftige Anlagen'],['DGUV Vorschriften und Regeln','Unternehmer','Unfallverhütung im Betrieb']]},
    {ul:['Harmonisierte Normen konkretisieren die Richtlinie; wer sie anwendet, darf von der Konformität ausgehen (Vermutungswirkung)','EG-Konformitätserklärung: Hersteller (oder Bevollmächtigter in der EU) bestätigt die Einhaltung aller relevanten Richtlinien; Inhalt ist je Richtlinie vorgeschrieben, die Form nicht; bei Maschinen liegt sie jeder Lieferung bei','Konformitätserklärung muss Behörden auf Verlangen unverzüglich vorgelegt werden, z. B. nach einem Unfall','CE-Kennzeichnung: Hersteller bzw. Importeur erklärt die Übereinstimmung; Mindesthöhe 5 mm, Proportionen vorgegeben','CE ist kein Prüfzeichen – eine unabhängige Stelle war nur in Ausnahmefällen beteiligt; anders beim GS- oder DGUV-Test-Zeichen','BetrSichV gilt für Bereitstellung und Benutzung von Arbeitsmitteln sowie den Betrieb überwachungsbedürftiger Anlagen (Dampfkessel, Druckbehälter, Aufzüge)','Vor der ersten Verwendung: Gefährdungsbeurteilung, daraus Schutzmaßnahmen, Betriebsanweisungen, Unterweisungen']},
    {ul:['Vorbereitende Tätigkeiten: Verpackung und Transportsicherungen entfernen, Schutzschichten von Führungen abnehmen, Behälter und Leitungen reinigen, Betriebsflüssigkeiten einfüllen, Medien anschließen, Sicherheitseinrichtungen (Not-Halt) prüfen, Kabel und Leitungen kontrollieren, Sichtprüfung auf Schäden','Besondere Anlagen: AwSV (Anlagen mit wassergefährdenden Stoffen, ggf. Sachverständigenprüfung und Anzeige), Druckgeräte (Prüfung vor Inbetriebnahme durch befähigte Person oder ZÜS je nach Kategorie bzw. Druck-Liter-Produkt)','Sicherheitsrelevante Schweißarbeiten (z. B. Hochdruckrohre) nur durch geprüfte Schweißer mit gültiger Prüfung']},
    {bsp:{t:'Beispiel: Druckluftbehälter einer neuen Kompressoranlage',b:['Gegeben: Behälter 500 l, maximal zulässiger Druck 11 bar, Fluid Luft','Druck-Liter-Produkt: 11 bar · 500 l = 5 500 bar·l','Nach BetrSichV Anhang 2 Abschnitt 4 liegt ein solcher Behälter im Bereich, in dem die Prüfung vor Inbetriebnahme und die wiederkehrenden Prüfungen durch eine zugelassene Überwachungsstelle (ZÜS) erfolgen – Einstufung im Einzelfall anhand der Tabelle prüfen.','Ergebnis für den Meister: Inbetriebnahme erst nach Prüfbescheinigung; Fristen in den Prüfplan übernehmen.']}},
    {merke:'Hersteller sorgen für sichere Maschinen (Binnenmarktrecht), Betreiber für sichere Verwendung (Arbeitsschutzrecht). Beides muss bei der Inbetriebnahme zusammenkommen.'},
    {falle:'CE heißt nicht „geprüft und sicher“. Der Betreiber muss trotzdem eine eigene Gefährdungsbeurteilung für die konkrete Einsatzsituation erstellen.'}
  ]},
  {t:'Inbetriebnahme, Abnahme und Gefährdungsbeurteilung',h:'Sensorische Erfassung · Einhaltung der vereinbarten Vertragsbestimmungen und kontinuierlichen Kontroll- und Überwachungszeit · Einhaltung der vorgeschriebenen Energiebelastung · Inbetriebnahme und Abnahmevorschriften · Gefährdungsbeurteilung',pg:69,b:[
    {p:'Beim ersten Hochfahren werden Anzeigen und Messwerte genau beobachtet. Das Abnahmeprotokoll schließt die Inbetriebnahme ab und ist der zentrale Nachweis gegenüber dem Hersteller.'},
    {ol:['Lieferung auf Vollständigkeit und Transportschäden prüfen','Baugruppen und Teilabläufe einzeln testen','Einstellungen korrigieren und nachjustieren, Gesamtablauf prüfen','Probelauf unter Produktionsbedingungen','Übergabe mit Dokumentation und Prüfnachweisen, Abnahmeprotokoll unterschreiben']},
    {ul:['Sensorische Erfassung: Temperatur, Druck und Durchfluss von Kühlwasser und Hydrauliköl beobachten und protokollieren – Abweichungen haben schwere Folgen','Grundeinstellungen (Ventilstellungen, Drehzahlen, Parameter) dokumentieren, damit der Ausgangszustand nach Optimierungen wiederherstellbar ist','Während der Gewährleistungsfrist keine eigenmächtigen Umbauten – sonst erlischt der Anspruch','Energiebelastung prüfen: Zu hohe Aufnahme von Strom oder Druckluft überlastet das Werksnetz und deutet auf Fehlfunktion oder Überlast hin']},
    {ul:['Abnahme-Checkliste: Pflichtenheft eingehalten? Dokumentation vollständig? Sicherheitseinrichtungen geprüft? Konformitätserklärung gültig? CE vorhanden? Gefährdungsbeurteilung erstellt und Maßnahmen umgesetzt? Probelauf erfolgreich? Leistungsdaten nachgewiesen (Taktzeit, Maschinen- und Prozessfähigkeit cm/cmk)?']},
    {ul:['Gefährdungsbeurteilung (§ 5 ArbSchG, § 3 BetrSichV) ist das zentrale Element des Arbeitsschutzes – Gefahren erkennen, bevor etwas passiert','Umfang nach betrieblichen Gegebenheiten; alle vorhersehbaren Tätigkeiten einschließen: Normalbetrieb, Einrichten, Störungsbeseitigung, Reinigung, Instandhaltung, Entsorgung','Für jede Tätigkeit bzw. jeden Arbeitsplatz; gleichartige Arbeitsplätze dürfen gemeinsam beurteilt werden','Beschäftigte frühzeitig beteiligen; Betriebsrat hat Mitbestimmungsrecht (§ 87 Abs. 1 Nr. 7 BetrVG)','Praxishilfe: GDA-Leitlinie „Gefährdungsbeurteilung und Dokumentation“','Ablauf: Arbeitsbereiche festlegen – Gefährdungen ermitteln – beurteilen – Maßnahmen festlegen (STOP-Prinzip: Substitution, technisch, organisatorisch, persönlich) – umsetzen – Wirksamkeit prüfen – dokumentieren – fortschreiben']},
    {bsp:{t:'Beispiel: Abnahme einer Laserschneidanlage',b:['Probelauf über 2 Schichten mit drei Blechstärken; Taktzeit und Schnittqualität mit Pflichtenheft verglichen.','Messwerte im Protokoll: Kühlwassertemperatur 22 °C (Soll 20–24 °C), Druckluft 1,1 m³/min (Herstellerangabe 1,2), Stromaufnahme im Rahmen.','Mängelliste: Absaugung zu laut → nachbessern bis Frist X; Abnahme unter Vorbehalt.','Unterschriften Hersteller und Betreiber; Protokoll mit Konformitätserklärung, Betriebsanleitung und Schulungsnachweisen im Anlagenordner ablegen.']}},
    {merke:'Das Abnahmeprotokoll bestätigt vollständige Lieferung und einwandfreie Funktion zum Übergabezeitpunkt – gewissenhaft ausfüllen und archivieren.'}
  ]},
  {t:'Einweisung des Bedien- und Instandhaltungspersonals',h:'Funktionsnotwendige Bedingungen bei der Einweisung des Bedienpersonals',pg:70,b:[
    {p:'Bediener und Instandhalter bestimmen Leistung und Lebensdauer einer Anlage. Sie müssen rechtzeitig vor der Inbetriebnahme geschult werden – oft beim Hersteller, bei größeren Lücken durch zusätzliche Weiterbildung.'},
    {ul:['Inhalte: Steuerung und Bedienkonzept, Betriebsarten, Störungsbehebung, Sicherheitseinrichtungen, Wartungsaufgaben','Klare Schnittstelle: welche Wartung macht der Bediener, welche die Instandhaltung','Sprachliche Verständigung sichern; Sicherheits- und Bedienanweisungen müssen vollständig verstanden werden – ggf. mehrsprachige Unterlagen oder Sprachkurse','Kennzeichnung an der Anlage (Armaturen, Mess- und Wartungsstellen) identisch mit Schaltplan und Dokumentation','Betriebsanweisung durch den Betreiber erstellen (Herstellervorlage an Betriebsgegebenheiten anpassen)','Unterweisung vor Aufnahme der Tätigkeit und mindestens jährlich (§ 12 ArbSchG, § 12 BetrSichV), schriftlich dokumentieren']},
    {ol:['Vorbereiten: Lernziele, Unterlagen, Termin vor Produktionsstart','Vormachen und erklären: Meister oder Herstellertechniker zeigt den Ablauf','Nachmachen lassen: Mitarbeiter führt unter Aufsicht aus und erklärt','Üben und kontrollieren: selbstständiges Arbeiten, Rückfragen, Freigabe']},
    {bsp:{t:'Beispiel: Einweisung an einer neuen Roboterschweißzelle',b:['Herstellerschulung: 2 Bediener und 1 Instandhalter je Schicht (Programmstart, Teach-Grundlagen, Brennerwartung).','Interne Unterweisung aller Bediener: Schutztürverriegelung, Not-Halt, Betriebsanweisung Schweißrauch, Brandschutz.','Schnittstelle: Bediener reinigt Düse und wechselt Kontaktrohr; Drahtvorschub und Roboterachsen nur Instandhaltung.','Nachweis: Unterweisungsliste mit Unterschrift, Freigabematrix am Schichtbrett.']}},
    {merke:'Gute Einweisung ist die beste Vorbeugung gegen Bedien- und Einstellfehler – und Pflicht des Arbeitgebers.'}
  ]},
  {t:'Steuern und Regeln',h:'Funktionserhalt und Überwachung der Steuer- und Regeleinrichtungen sowie der Diagnosesysteme von Maschinen und Anlagen · Mechanische Steuer- und Regeleinrichtungen · Wirkungsweise und Instandhaltungshäufigkeit',pg:73,abb:[['Abb. 6.1 Regelung eines Maschinentischs',74],['Abb. 6.2 Temperaturregelung in einem Behälter',75],['Abb. 6.3 Unstetiger Regler einer Ofenheizung',75],['Abb. 6.4 Reglerverhalten eines unstetigen Reglers',75]],b:[
    {p:'Steuer- und Regeleinrichtungen automatisieren Maschinen. Mechanische Steuerungen (Nocken, Kurvenscheiben, Hebel, Getriebe) sind einfach, robust und langlebig – Beispiel Nockenwelle im Motor. Grundbegriffe gelten für alle Energieformen.'},
    {tab:[['Merkmal','Steuern','Regeln'],['Wirkungsweg','offen (Steuerkette)','geschlossen (Regelkreis)'],['Istwert','wird nicht erfasst','wird laufend gemessen und mit dem Sollwert verglichen'],['Störgröße','wirkt ungehindert','wird ausgeglichen'],['Alltagsbeispiel','Lüftungsstufe per Schalter','Klimaautomatik hält Innentemperatur']]},
    {svg:{w:520,h:150,cap:'Steuerkette: offener Wirkungsweg, eine Störung wird nicht bemerkt',body:'<text x="3" y="52" class="sk-t">Eingabe</text><line x1="5" y1="85" x2="33" y2="85" class="sk-f" marker-end="url(#ar)"/><rect x="35" y="60" width="120" height="50" class="sk-body"/><text x="95" y="81" text-anchor="middle" class="sk-t">Steuer-</text><text x="95" y="99" text-anchor="middle" class="sk-t">einrichtung</text><line x1="155" y1="85" x2="183" y2="85" class="sk-f" marker-end="url(#ar)"/><rect x="185" y="60" width="110" height="50" class="sk-body"/><text x="240" y="90" text-anchor="middle" class="sk-t">Stellglied</text><line x1="295" y1="85" x2="323" y2="85" class="sk-f" marker-end="url(#ar)"/><rect x="325" y="60" width="120" height="50" class="sk-body"/><text x="385" y="81" text-anchor="middle" class="sk-t">Steuer-</text><text x="385" y="99" text-anchor="middle" class="sk-t">strecke</text><line x1="445" y1="85" x2="512" y2="85" class="sk-f" marker-end="url(#ar)"/><text x="458" y="77" class="sk-t">Ausgabe</text><line x1="385" y1="18" x2="385" y2="58" class="sk-l" marker-end="url(#ar)"/><text x="392" y="22" class="sk-t">Störgröße z</text><text x="260" y="140" text-anchor="middle" class="sk-t acc">keine Rückmeldung des Istwerts</text>'}},
    {svg:{w:520,h:240,body:'<text x="8" y="72" class="sk-t">Sollwert w</text><line x1="8" y1="90" x2="34" y2="90" class="sk-f" marker-end="url(#ar)"/><circle cx="50" cy="90" r="14" class="sk-body"/><line x1="64" y1="90" x2="83" y2="90" class="sk-f" marker-end="url(#ar)"/><text x="73" y="82" text-anchor="middle" class="sk-t">e</text><rect x="85" y="65" width="100" height="50" class="sk-body"/><text x="135" y="95" text-anchor="middle" class="sk-t">Regler</text><line x1="185" y1="90" x2="213" y2="90" class="sk-f" marker-end="url(#ar)"/><rect x="215" y="65" width="100" height="50" class="sk-body"/><text x="265" y="95" text-anchor="middle" class="sk-t">Stellglied</text><line x1="315" y1="90" x2="343" y2="90" class="sk-f" marker-end="url(#ar)"/><text x="329" y="82" text-anchor="middle" class="sk-t">y</text><rect x="345" y="65" width="120" height="50" class="sk-body"/><text x="405" y="95" text-anchor="middle" class="sk-t">Regelstrecke</text><line x1="465" y1="90" x2="510" y2="90" class="sk-f" marker-end="url(#ar)"/><text x="498" y="82" text-anchor="middle" class="sk-t">x</text><line x1="405" y1="28" x2="405" y2="63" class="sk-l" marker-end="url(#ar)"/><text x="412" y="24" class="sk-t">Störgröße z</text><line x1="490" y1="90" x2="490" y2="190" class="sk-l"/><line x1="490" y1="190" x2="332" y2="190" class="sk-l" marker-end="url(#ar)"/><rect x="220" y="165" width="110" height="50" class="sk-body"/><text x="275" y="195" text-anchor="middle" class="sk-t">Messglied</text><line x1="220" y1="190" x2="50" y2="190" class="sk-l"/><line x1="50" y1="190" x2="50" y2="106" class="sk-l" marker-end="url(#ar)"/><text x="64" y="128" class="sk-t acc">−</text><text x="482" y="140" text-anchor="end" class="sk-t">Istwert x</text>',cap:'Regelkreis: Regeldifferenz e = w − x wird laufend ausgeglichen'}},
    {tab:[['Begriff','Zeichen','Bedeutung'],['Regelgröße','x','Größe, die konstant gehalten werden soll (Istwert)'],['Führungsgröße','w','vorgegebener Sollwert'],['Regeldifferenz','e = w − x','Abweichung, aus der der Regler rechnet'],['Stellgröße','y','Ausgang des Reglers, wirkt über das Stellglied auf die Strecke'],['Störgröße','z','äußere Einflüsse, z. B. Wärmeverlust, Last'],['Regelstrecke','–','Teil der Anlage, in dem die Regelgröße beeinflusst wird']]},
    {p:'Unstetige Regler (Zwei- oder Mehrpunktregler, z. B. Bimetall, Thermostat) kennen nur feste Schaltstellungen. Die Regelgröße pendelt zwischen oberer und unterer Schaltgrenze; der Abstand heißt Schaltdifferenz (Hysterese). Stetige Regler verstellen die Stellgröße stufenlos und halten den Sollwert genauer – deshalb überwiegen sie in der Industrie.'},
    {svg:{w:520,h:295,cap:'Zweipunktregler: Die Regelgröße pendelt zwischen oberer und unterer Schaltgrenze (Schaltdifferenz)',body:'<line x1="50" y1="170" x2="505" y2="170" class="sk-l" marker-end="url(#ar)"/><line x1="50" y1="170" x2="50" y2="20" class="sk-l" marker-end="url(#ar)"/><text x="500" y="190" text-anchor="end" class="sk-t">Zeit</text><text x="58" y="25" class="sk-t">Temperatur</text><line x1="50" y1="70" x2="440" y2="70" class="sk-c"/><line x1="50" y1="110" x2="440" y2="110" class="sk-c"/><line x1="50" y1="90" x2="440" y2="90" class="sk-c"/><text x="505" y="75" text-anchor="end" class="sk-t">oben</text><text x="505" y="115" text-anchor="end" class="sk-t">unten</text><text x="505" y="95" text-anchor="end" class="sk-t">Sollwert</text><polyline points="50,165 110,70 150,110 190,70 230,110 270,70 310,110 350,70 390,110" class="sk-l thick"/><line x1="50" y1="280" x2="505" y2="280" class="sk-l" marker-end="url(#ar)"/><text x="10" y="235" class="sk-t">EIN</text><text x="10" y="267" class="sk-t">AUS</text><polyline points="50,230 110,230 110,262 150,262 150,230 190,230 190,262 230,262 230,230 270,230 270,262 310,262 310,230 350,230 350,262 390,262 390,230 390,230" class="sk-f"/><text x="300" y="205" text-anchor="middle" class="sk-t">Heizung (Stellgröße)</text>'}},
    {ul:['Ausfallursachen von Steuer- und Regeleinrichtungen: Verschleiß, Materialermüdung, mechanische Einwirkung','Warnsignale vor einem Ausfall: Leckagen, Risse, lautere Laufgeräusche, ungewohnte Betriebswerte (Druck, Temperatur, Stromaufnahme), starke Erwärmung, Vibrationen','Rechtzeitiges Eingreifen verhindert Folgeschäden – deshalb hohe Aufmerksamkeit bei Wartung und Inspektion']},
    {bsp:{t:'Beispiel: Öltemperaturregelung eines Hydraulikaggregats',b:['Sollwert w = 45 °C; gemessen x = 52 °C → Regeldifferenz e = 45 − 52 = −7 K','Regler erhöht die Stellgröße y (Lüfterdrehzahl des Ölkühlers bzw. Öffnung des Kühlwasserventils).','Störgröße z: steigende Hallentemperatur im Sommer, höhere Last der Presse.','Folge für die Instandhaltung: Kühlerlamellen verschmutzt → Regler läuft dauerhaft am Anschlag → Temperatur steigt trotzdem. Stellgröße als Diagnosesignal nutzen.']}},
    {merke:'Steuern = offene Kette ohne Rückmeldung. Regeln = geschlossener Kreis aus Messen, Vergleichen, Stellen.'}
  ]},
  {t:'Reglertypen und Übertragungsverhalten',h:'Übertragungsverhalten und Übertragungsfehlerdiagnose',pg:76,abb:[['Abb. 6.5 P-Regler zur Füllstandsregelung',76],['Abb. 6.6 Sprungantwort eines P-Reglers',76],['Abb. 6.7 Sprungantwort eines PID-Reglers',77]],b:[
    {p:'Stetige Regler unterscheidet man danach, wie die Stellgröße auf eine sprunghafte Änderung der Regeldifferenz reagiert (Sprungantwort). Grundtypen sind P, I und D; daraus werden PI-, PD- und PID-Regler kombiniert.'},
    {svg:{w:520,h:322,cap:'Idealisierte Sprungantworten der Grundregler',body:'<line x1="30" y1="130" x2="250" y2="130" class="sk-l" marker-end="url(#ar)"/><line x1="30" y1="130" x2="30" y2="32" class="sk-l" marker-end="url(#ar)"/><text x="38" y="42" class="sk-t acc">P-Regler</text><text x="246" y="146" text-anchor="end" class="sk-t">t</text><line x1="70" y1="130" x2="70" y2="45" class="sk-c"/><polyline points="30,130 70,130 70,85 242,85" class="sk-l thick"/><line x1="280" y1="130" x2="500" y2="130" class="sk-l" marker-end="url(#ar)"/><line x1="280" y1="130" x2="280" y2="32" class="sk-l" marker-end="url(#ar)"/><text x="288" y="42" class="sk-t acc">I-Regler</text><text x="496" y="146" text-anchor="end" class="sk-t">t</text><line x1="320" y1="130" x2="320" y2="45" class="sk-c"/><polyline points="280,130 320,130 492,50" class="sk-l thick"/><line x1="30" y1="275" x2="250" y2="275" class="sk-l" marker-end="url(#ar)"/><line x1="30" y1="275" x2="30" y2="177" class="sk-l" marker-end="url(#ar)"/><text x="38" y="187" class="sk-t acc">PI-Regler</text><text x="246" y="291" text-anchor="end" class="sk-t">t</text><line x1="70" y1="275" x2="70" y2="190" class="sk-c"/><polyline points="30,275 70,275 70,240 242,190" class="sk-l thick"/><line x1="280" y1="275" x2="500" y2="275" class="sk-l" marker-end="url(#ar)"/><line x1="280" y1="275" x2="280" y2="177" class="sk-l" marker-end="url(#ar)"/><text x="288" y="187" class="sk-t acc">PID-Regler</text><text x="496" y="291" text-anchor="end" class="sk-t">t</text><line x1="320" y1="275" x2="320" y2="190" class="sk-c"/><polyline points="280,275 320,275 320,190 334,237 492,195" class="sk-l thick"/><text x="260" y="312" text-anchor="middle" class="sk-t">Stellgröße y nach einem Sprung der Regeldifferenz zum Zeitpunkt t₀ (gestrichelt)</text>'}},
    {tab:[['Regler','Verhalten','Vorteil','Nachteil'],['P (proportional)','Stellgröße proportional zur Regeldifferenz','reagiert sofort, einfach (z. B. Schwimmerventil)','bleibende Regelabweichung'],['I (integral)','summiert die Regeldifferenz über die Zeit','beseitigt die Abweichung vollständig','träge, kann überschwingen'],['PI','P-Anteil plus I-Anteil (Nachstellzeit)','schnell und ohne bleibende Abweichung – Industriestandard','Überschwingen bei ungünstiger Einstellung'],['PID','zusätzlich D-Anteil: reagiert auf die Änderungsgeschwindigkeit','sehr schnelle Reaktion auf Sprünge','empfindlich gegen Messrauschen, schwierig einzustellen']]},
    {ul:['Warum bleibt beim P-Regler eine Abweichung? Ohne Abweichung liefert er keine Stellgröße – die Strecke driftet wieder weg','Der I-Anteil wird erst kleiner, wenn die Regeldifferenz ihr Vorzeichen wechselt; daher Überschwingen um den Sollwert','Fehlerdiagnose: Schwingt die Regelgröße dauernd → Verstärkung zu hoch oder Nachstellzeit zu klein; bleibt eine Abweichung → I-Anteil fehlt oder Stellglied am Anschlag; reagiert der Kreis zu träge → Messglied verschmutzt, Totzeit, Stellglied schwergängig']},
    {bsp:{t:'Beispiel: Füllstandsregelung eines Kühlschmierstoffbehälters',b:['Mit P-Regler (Schwimmer betätigt Zulaufventil): Bei großer Entnahme stellt sich ein Füllstand unter dem Soll ein – bleibende Regelabweichung.','Mit PI-Regler (Füllstandssensor, Regelventil, SPS): Der I-Anteil erhöht den Zulauf so lange, bis der Sollstand wieder erreicht ist.','Störung im Betrieb: Füllstand pendelt stark → Nachstellzeit zu kurz eingestellt; Parameter nach Herstellerempfehlung zurücksetzen und protokollieren.']}},
    {falle:'Ein P-Regler allein erreicht den Sollwert nicht exakt. Ist „keine bleibende Regelabweichung“ gefordert, braucht es einen I-Anteil.'}
  ]},
  {t:'Pneumatik: Grundlagen und Druckluftaufbereitung',h:'Pneumatische Steuer- und Regeleinrichtungen · Anwendung der Druckluft und Druckluftaufbereitung',pg:77,abb:[['Abb. 6.8 Entstehung des Drucks',78],['Abb. 6.9 Bauarten von Verdichtern',78],['Abb. 6.10 Druckerzeugung in einer Verdichteranlage',78],['Abb. 6.11 Darstellung und Schaltplan einer Pneumatikanlage',80]],b:[
    {p:'Pneumatik, Hydraulik und Elektrik sind die drei Hauptenergieformen der Automatisierung. Wird ein eingeschlossenes Gasvolumen verkleinert, steigt der Druck; technisch nutzt man den Überdruck gegenüber der Atmosphäre.'},
    {fx:['p_e = F / A;  p_e = p_abs − p_amb','Überdruck in N/cm² (1 bar = 10 N/cm²); p_amb ≈ 1 bar']},
    {ol:['Ansaugen über Ansaugfilter','Verdichten (Kolben-, Schrauben-, Turboverdichter)','Kühlen und Kondensat abscheiden','Speichern im Druckluftbehälter','Trocknen und Filtern','Verteilen (Ringleitung mit Gefälle)','Warten: Wartungseinheit vor der Maschine (Filter, Druckregler, ggf. Öler)']},
    {ul:['Drucktaupunkt: Temperatur, bis zu der die Druckluft abkühlen kann, ohne dass Wasser ausfällt; Wahl nach Anwendung (Kältetrockner ca. +3…+5 °C, Adsorptionstrockner −20 °C und tiefer)','Geölte Luft nur, wenn Antriebe es verlangen; Lebensmittel und Medizin brauchen ölfreie, hochreine Luft','Leitungen: Ringleitung für Versorgungssicherheit, leichtes Gefälle, ausreichender Durchmesser; Leckagen sofort beseitigen']},
    {tab:[['Vorteile der Pneumatik','Nachteile der Pneumatik'],['Ex-Schutz: in explosionsgefährdeten Bereichen einsetzbar','Luft muss aufbereitet werden'],['hohe Leistungsdichte, sehr hohe Geschwindigkeiten','niedriger Wirkungsgrad, hohe Energiekosten (deutlich teurer als Hydraulik und Elektrik)'],['überlastsicher bis zum Stillstand','Luft ist kompressibel – kein genaues Positionieren, ungleichmäßige Geschwindigkeit bei Lastwechsel'],['keine Rückleitung nötig, Abluft ins Freie','Leckage- und Druckverluste in langen Netzen'],['Kraft und Geschwindigkeit stufenlos einstellbar, einfache Linear- und Drehbewegung','Abluftgeräusche (Schalldämpfer nötig)'],['robust, lange Lebensdauer','Kräfte begrenzt (Netzdruck ca. 6 bar)']]},
    {bsp:{t:'Beispiel: Luftverbrauch eines Pneumatikzylinders',b:['Gegeben: doppelt wirkender Zylinder D = 50 mm, Hub 200 mm, 6 bar Überdruck, 20 Doppelhübe pro Minute (Kolbenstange vernachlässigt)','Volumen je Doppelhub: 2 · π/4 · (0,05 m)² · 0,2 m = 0,000785 m³','Auf Ansaugzustand umgerechnet: · (6 + 1) bar / 1 bar = 0,0055 m³','Verbrauch: 0,0055 m³ · 20 /min = 0,110 m³/min ≈ 110 l/min','Bei 0,12 kWh/m³ und 4 000 h/a: 0,11 · 60 · 4 000 · 0,12 = 3 168 kWh – für einen einzigen Zylinder.']}},
    {merke:'Druckluft immer nach Anwendung aufbereiten: so trocken und sauber wie nötig, ölhaltig nur wenn gefordert.'}
  ]},
  {t:'Pneumatische Antriebe',h:'Funktion von Antriebs- und Steuergliedern (Antriebe)',pg:80,abb:[['Abb. 6.12 Einfach wirkender Zylinder',80],['Abb. 6.13 Doppelt wirkender Zylinder',81],['Abb. 6.14 Kolbenkräfte bei Zylindern',81],['Abb. 6.15 Druckluft-Lamellenmotor',81]],b:[
    {p:'Antriebsglieder setzen die Energie der Druckluft in Bewegung um: Zylinder für gerade, Motoren und Schwenkantriebe für drehende Bewegungen.'},
    {tab:[['Zylinder','Funktion','Einsatz'],['einfach wirkend','Druckluft nur beim Ausfahren, Rückhub durch Feder','Spannen, Auswerfen, kleine Hübe'],['doppelt wirkend','Druckluft in beide Richtungen; Einfahrkraft kleiner wegen Kolbenstangenfläche','Standard in der Automatisierung'],['mit Endlagendämpfung','Dämpfungszapfen sperrt Abluft, Restluft entweicht über einstellbare Drossel','schwere Lasten, hohe Geschwindigkeit']]},
    {svg:{w:520,h:255,cap:'Wirksame Kolbenflächen: beim Einfahren fehlt die Fläche der Kolbenstange',body:'<rect x="60" y="60" width="300" height="100" class="sk-l"/><rect x="170" y="62" width="20" height="96" class="sk-body"/><rect x="190" y="95" width="270" height="30" class="sk-body"/><line x1="460" y1="110" x2="508" y2="110" class="sk-f" marker-end="url(#ar)"/><text x="478" y="92" class="sk-t acc">F, v</text><line x1="80" y1="190" x2="80" y2="162" class="sk-l" marker-end="url(#ar)"/><line x1="340" y1="190" x2="340" y2="162" class="sk-l" marker-end="url(#ar)"/><text x="88" y="186" class="sk-t">Zufluss aus</text><text x="260" y="186" class="sk-t">Zufluss ein</text><line x1="40" y1="60" x2="40" y2="160" class="sk-c"/><text x="30" y="115" text-anchor="end" class="sk-t">D</text><line x1="430" y1="97" x2="430" y2="123" class="sk-c"/><text x="422" y="115" text-anchor="end" class="sk-t">d</text><text x="115" y="100" text-anchor="middle" class="sk-t">A_K</text><text x="275" y="82" text-anchor="middle" class="sk-t">A_R</text><text x="20" y="222" class="sk-t">Ausfahren: A_K = π · D² / 4</text><text x="270" y="222" class="sk-t">Einfahren: A_R = π · (D² − d²) / 4</text><text x="170" y="246" text-anchor="middle" class="sk-t acc">F = p · A · η</text><text x="350" y="246" text-anchor="middle" class="sk-t acc">v = Q / A</text>'}},
    {fx:['F = p_e · A · η','wirksame Kolbenkraft; A in cm², p_e in N/cm², η ≈ 0,9 bei Pneumatikzylindern']},
    {ul:['Auswahlgrößen: Kolbendurchmesser, Hublänge, Kolbenstangendurchmesser, Druck','Schwenkantriebe mit begrenztem Winkel (z. B. 90°, 180°) öffnen und schließen Armaturen','Druckluft-Lamellenmotor: exzentrischer Rotor mit verschiebbaren Lamellen bildet sichelförmige Kammern; Drehmoment über Druck, Drehzahl über Luftmenge einstellbar','Vorteile Lamellenmotor: überlastsicher auch bei Blockieren, großer Drehzahlbereich, wenig Verschleiß, keine Funken oder heißen Oberflächen, volles Moment beim Anlauf, unempfindlich gegen Hitze, Staub, Vibration']},
    {bsp:{t:'Beispiel: Spannkraft eines Pneumatikzylinders',b:['Gegeben: D = 63 mm, d = 20 mm, p_e = 6 bar = 60 N/cm², η = 0,9','Kolbenfläche: A_K = π/4 · (6,3 cm)² = 31,17 cm²','Ausfahrkraft: F = 60 N/cm² · 31,17 cm² · 0,9 = 1 683 N','Ringfläche: A_R = 31,17 − π/4 · (2 cm)² = 31,17 − 3,14 = 28,03 cm²','Einfahrkraft: F = 60 · 28,03 · 0,9 = 1 514 N','Interpretation: Erforderliche Spannkraft 1 500 N? Dann muss in Ausfahrrichtung gespannt werden; Netzdruckschwankungen (z. B. auf 5 bar) senken die Kraft auf ca. 1 400 N – Reserve einplanen oder Druckschalter einsetzen.']}},
    {falle:'Beim Einfahren wirkt nur die Ringfläche. Wer mit der vollen Kolbenfläche rechnet, überschätzt die Rückzugskraft.'}
  ]},
  {t:'Pneumatische Ventile',h:'Funktion von Antriebs- und Steuergliedern (Steuerglieder)',pg:82,abb:[['Abb. 6.16 Darstellung von Wegeventilen',82],['Abb. 6.17 Betätigungsarten',83],['Tab. 6.1 Anschlussbezeichnungen',84],['Abb. 6.18–6.21 Sperrventile',84],['Abb. 6.22–6.24 Strom- und Druckventile',85],['Abb. 6.25 Druckregelventil',86],['Abb. 6.26 Zeitverzögerungsventil',86]],b:[
    {p:'Steuerglieder (Ventile) führen die Druckluft zur richtigen Zeit in richtiger Menge den Antrieben zu. Nach Funktion gibt es Wege-, Sperr-, Strom- und Druckventile.'},
    {ul:['Wegeventile bestimmen Start, Stopp und Richtung; ein verschobener Steuerkolben verbindet die Anschlüsse','Schaltzeichen: Jedes Quadrat ist eine Schaltstellung; Anschlüsse werden am Quadrat der Ruhestellung gezeichnet','Bezeichnung n/m: n Anschlüsse, m Schaltstellungen – z. B. 3/2, 5/2, 4/3','Ruhestellung = Lage ohne äußere Kraft; Ausgangsstellung = Lage im Schaltplan; bei drei Stellungen gibt es eine Mittelstellung (z. B. Sperr-Mittelstellung)','Betätigung: manuell (Knopf, Hebel, Pedal), mechanisch (Stößel, Rolle, Feder), elektrisch (Magnet, ggf. mit Vorsteuerung), pneumatisch (Druck oder Entlastung)']},
    {tab:[['Anschluss','Zahl (ISO 5599)','früher (Buchstabe)'],['Druckanschluss','1','P'],['Arbeitsanschlüsse','2, 4','B, A'],['Entlüftung','3, 5','R, S'],['Steueranschlüsse','12, 14 (Schalten auf 2 bzw. 4)','Z, Y']]},
    {svg:{w:520,h:300,cap:'Schaltplan (ISO 1219): doppelt wirkender Zylinder, 5/2-Wegeventil mit Taster und Feder, zwei Drosselrückschlagventile als Abluftdrosseln',body:'<rect x="170" y="30" width="180" height="40" class="sk-l"/><line x1="230" y1="30" x2="230" y2="70" class="sk-l thick"/><line x1="230" y1="50" x2="410" y2="50" class="sk-l thick"/><text x="415" y="55" class="sk-t">MM1</text><rect x="163" y="95" width="44" height="40" class="sk-c"/><line x1="185" y1="70" x2="185" y2="95" class="sk-l"/><line x1="185" y1="135" x2="185" y2="150" class="sk-l"/><line x1="175" y1="95" x2="195" y2="95" class="sk-l"/><line x1="175" y1="135" x2="195" y2="135" class="sk-l"/><line x1="175" y1="95" x2="175" y2="135" class="sk-l"/><path d="M168,107 Q175,115 168,123" class="sk-l"/><path d="M182,107 Q175,115 182,123" class="sk-l"/><line x1="195" y1="95" x2="195" y2="135" class="sk-l"/><circle cx="195" cy="113" r="4" class="sk-body"/><path d="M188,109 L195,123 L202,109" class="sk-l"/><text x="158" y="119" text-anchor="end" class="sk-t">RZ1</text><rect x="313" y="95" width="44" height="40" class="sk-c"/><line x1="335" y1="70" x2="335" y2="95" class="sk-l"/><line x1="335" y1="135" x2="335" y2="150" class="sk-l"/><line x1="325" y1="95" x2="345" y2="95" class="sk-l"/><line x1="325" y1="135" x2="345" y2="135" class="sk-l"/><line x1="325" y1="95" x2="325" y2="135" class="sk-l"/><path d="M318,107 Q325,115 318,123" class="sk-l"/><path d="M332,107 Q325,115 332,123" class="sk-l"/><line x1="345" y1="95" x2="345" y2="135" class="sk-l"/><circle cx="345" cy="113" r="4" class="sk-body"/><path d="M338,109 L345,123 L352,109" class="sk-l"/><text x="362" y="119" class="sk-t">RZ2</text><path d="M185,150 H275 V170" class="sk-l"/><path d="M335,150 H305 V170" class="sk-l"/><rect x="200" y="170" width="60" height="50" class="sk-body"/><rect x="260" y="170" width="60" height="50" class="sk-body"/><line x1="290" y1="220" x2="305" y2="172" class="sk-l" marker-end="url(#ar)"/><line x1="275" y1="170" x2="270" y2="218" class="sk-l" marker-end="url(#ar)"/><line x1="310" y1="220" x2="310" y2="210" class="sk-l"/><line x1="304" y1="210" x2="316" y2="210" class="sk-l"/><line x1="230" y1="220" x2="215" y2="172" class="sk-l" marker-end="url(#ar)"/><line x1="245" y1="170" x2="250" y2="218" class="sk-l" marker-end="url(#ar)"/><line x1="210" y1="220" x2="210" y2="210" class="sk-l"/><line x1="204" y1="210" x2="216" y2="210" class="sk-l"/><line x1="200" y1="195" x2="182" y2="195" class="sk-l"/><path d="M182,186 A9,9 0 0,0 182,204" class="sk-l"/><polyline points="320,195 326,187 332,203 338,187 344,203 350,195" class="sk-l"/><text x="268" y="163" text-anchor="end" class="sk-t">4</text><text x="312" y="163" class="sk-t">2</text><text x="296" y="240" class="sk-t">1</text><text x="358" y="200" class="sk-t">QM1 (5/2)</text><path d="M270,220 V232 L264,240 H276 Z" class="sk-l"/><path d="M310,220 V226" class="sk-l"/><path d="M290,220 V255 H150" class="sk-l"/><rect x="100" y="240" width="50" height="30" class="sk-body"/><path d="M125,244 L137,255 L125,266 L113,255 Z" class="sk-l"/><line x1="117" y1="255" x2="133" y2="255" class="sk-c"/><line x1="60" y1="255" x2="100" y2="255" class="sk-l"/><circle cx="45" cy="255" r="15" class="sk-body"/><path d="M45,245 L53,259 L37,259 Z" class="fillacc"/><text x="125" y="288" text-anchor="middle" class="sk-t">Wartungseinheit</text><text x="45" y="288" text-anchor="middle" class="sk-t">Quelle</text>'}},
    {tab:[['Ventil','Funktion','Anwendung'],['Rückschlagventil','Durchfluss nur in eine Richtung','Sicherung gegen Rückströmen'],['Wechselventil','ODER: Signal an P1 oder P2 gelangt nach A','Bedienung von zwei Stellen'],['Zweidruckventil','UND: Ausgang nur bei Signal an beiden Eingängen','Zweihandbedienung'],['Schnellentlüftungsventil','Abluft direkt am Zylinder ins Freie','schnellerer Rückhub'],['Drosselventil','verengter Querschnitt, beidseitig wirkend','Geschwindigkeit begrenzen'],['Drosselrückschlagventil','drosselt nur in einer Richtung','Abluftdrosselung: ruckfreie Bewegung ohne Stick-Slip'],['Druckbegrenzungsventil','normal geschlossen, öffnet bei Überdruck','Schutz von Behältern und Leitungen'],['Druckregelventil','normal offen, hält Ausgangsdruck konstant (Membran gegen Feder)','in jeder Wartungseinheit'],['Zeitverzögerungsventil','3/2-Ventil + Drosselrückschlagventil + Luftspeicher','ein- oder ausschaltverzögerte Signale']]},
    {bsp:{t:'Beispiel: Ventilauswahl für eine Presseinrichtung',b:['Aufgabe: Zylinder darf nur ausfahren, wenn der Werker beide Taster gleichzeitig drückt; Ausfahren soll langsam und ruckfrei erfolgen, der Rückhub schnell.','Lösung: Zweidruckventil (UND) aus zwei 3/2-Tasterventilen steuert ein 5/2-Impulsventil; Drosselrückschlagventil in der Abluft der Kolbenstangenseite; Schnellentlüftungsventil am Kolbenraum.','Hinweis: Für echte Pressen ist eine zertifizierte Zweihandsteuerung nach EN ISO 13851 erforderlich – das Zweidruckventil allein erfüllt die Sicherheitsanforderung nicht.']}},
    {merke:'Druckbegrenzungsventil = normal geschlossen (Schutz). Druckregelventil = normal offen (konstanter Arbeitsdruck). Pneumatische Bauteile nur im zulässigen Druckbereich des Herstellers betreiben.'}
  ]},
  {t:'Schaltpläne und GRAFCET',h:'Schaltpläne und Spezifikationssprache GRAFCET',pg:86,abb:[['Abb. 6.27 Aufbau pneumatischer Schaltpläne',87],['Tab. 6.2 Bezeichnung von Bauelementen',87],['Abb. 6.28 GRAFCET für eine Förderanlage',89]],b:[
    {p:'Pneumatische Schaltpläne sind in Schaltkreise gegliedert und folgen dem Energiefluss von unten nach oben: Versorgung – Signalgeber – Ventile – Antriebe. Alle Bauteile sind in Ausgangsstellung (unbetätigt) gezeichnet.'},
    {ul:['Referenzkennzeichnung: zwei konkurrierende Normen (DIN ISO 1219-2 und DIN EN IEC 81346-2); verbreitet sind Kennbuchstaben nach 81346-2','Beispiele: MM Zylinder/Motor, QM Wegeventil, RZ Drosselrückschlagventil, BG Endschalter/Sensor, SJ handbetätigtes Ventil bzw. Signalgeber, KH Signalverknüpfung (UND/ODER/Zeit), AZ Wartungseinheit, GQ Druckquelle, PG Manometer','Konventionelle Pläne zeigen logische Verknüpfungen; Abläufe, bei denen ein Schritt den vorigen voraussetzt, beschreibt man mit Ablaufplänen']},
    {svg:{w:520,h:360,cap:'GRAFCET einer Spann- und Bohrvorrichtung: Schritte, Transitionen und Aktionen wechseln sich ab',body:'<rect x="62" y="20" width="36" height="30" class="sk-body"/><text x="80" y="40" text-anchor="middle" class="sk-t">0</text><rect x="62" y="85" width="36" height="30" class="sk-body"/><text x="80" y="105" text-anchor="middle" class="sk-t">1</text><rect x="62" y="150" width="36" height="30" class="sk-body"/><text x="80" y="170" text-anchor="middle" class="sk-t">2</text><rect x="62" y="215" width="36" height="30" class="sk-body"/><text x="80" y="235" text-anchor="middle" class="sk-t">3</text><rect x="62" y="280" width="36" height="30" class="sk-body"/><text x="80" y="300" text-anchor="middle" class="sk-t">4</text><rect x="65" y="23" width="30" height="24" class="sk-l"/><line x1="80" y1="50" x2="80" y2="85" class="sk-l"/><line x1="80" y1="115" x2="80" y2="150" class="sk-l"/><line x1="80" y1="180" x2="80" y2="215" class="sk-l"/><line x1="80" y1="245" x2="80" y2="280" class="sk-l"/><line x1="80" y1="310" x2="80" y2="345" class="sk-l"/><path d="M80,345 H30 V8 H80" class="sk-l"/><line x1="80" y1="8" x2="80" y2="18" class="sk-l" marker-end="url(#ar)"/><line x1="68" y1="67" x2="92" y2="67" class="sk-l thick"/><text x="102" y="72" class="sk-t">(1)  SF1 · BG1 · BG3</text><line x1="68" y1="132" x2="92" y2="132" class="sk-l thick"/><text x="102" y="137" class="sk-t">(2)  BG2 (gespannt)</text><line x1="68" y1="197" x2="92" y2="197" class="sk-l thick"/><text x="102" y="202" class="sk-t">(3)  BG4 (Bohrtiefe)</text><line x1="68" y1="262" x2="92" y2="262" class="sk-l thick"/><text x="102" y="267" class="sk-t">(4)  BG3</text><line x1="68" y1="327" x2="92" y2="327" class="sk-l thick"/><text x="102" y="332" class="sk-t">(5)  BG1</text><line x1="98" y1="100" x2="260" y2="100" class="sk-l"/><rect x="260" y="87" width="220" height="26" class="sk-body"/><text x="370" y="105" text-anchor="middle" class="sk-t">MM1 ausfahren: spannen</text><line x1="98" y1="165" x2="260" y2="165" class="sk-l"/><rect x="260" y="152" width="220" height="26" class="sk-body"/><text x="370" y="170" text-anchor="middle" class="sk-t">MM2 ausfahren: bohren</text><line x1="98" y1="230" x2="260" y2="230" class="sk-l"/><rect x="260" y="217" width="220" height="26" class="sk-body"/><text x="370" y="235" text-anchor="middle" class="sk-t">MM2 einfahren</text><line x1="98" y1="295" x2="260" y2="295" class="sk-l"/><rect x="260" y="282" width="220" height="26" class="sk-body"/><text x="370" y="300" text-anchor="middle" class="sk-t">MM1 einfahren: lösen</text>'}},
    {ul:['GRAFCET (DIN EN 60848): Strukturteil links (Schritte und Transitionen), Wirkungsteil rechts (Aktionen)','Startschritt mit doppeltem Rahmen; weitere Schritte fortlaufend nummeriert','Transition: waagerechter Strich zwischen zwei Schritten, Nummer links in Klammern, Bedingung rechts; Negation durch Strich über dem Signal','Bei linearen Abläufen ist immer genau ein Schritt aktiv','Kontinuierliche Aktion wirkt nur, solange der Schritt aktiv ist; speichernde Aktion wird gesetzt (:= 1) und erst in einem späteren Schritt zurückgesetzt (:= 0)','Zeitbedingungen möglich, z. B. Aktion erst 10 s nach Aktivierung eines Schritts','Rückführung vom letzten Schritt zum Startschritt als Linie mit Pfeil']},
    {bsp:{t:'Beispiel: Ablauf einer Spann- und Bohrvorrichtung (zur Grafik)',b:['Schritt 0: Grundstellung. Transition 1: Starttaster SF1 und beide Zylinder hinten (BG1, BG3).','Schritt 1: Spannzylinder MM1 fährt aus. Transition 2: BG2 meldet „gespannt“.','Schritt 2: Bohreinheit MM2 fährt aus. Transition 3: BG4 „Bohrtiefe erreicht“.','Schritt 3: MM2 fährt zurück. Transition 4: BG3.','Schritt 4: MM1 löst. Transition 5: BG1 → zurück zu Schritt 0.','Nutzen für die Instandhaltung: Bleibt die Anlage stehen, zeigt der aktive Schritt sofort, welches Signal fehlt.']}},
    {merke:'GRAFCET-Grundregel: Schritte und Transitionen wechseln sich immer ab; weitergeschaltet wird nur, wenn der vorige Schritt aktiv und die Bedingung erfüllt ist.'}
  ]},
  {t:'Elektropneumatik',h:'Funktion von Eingabe-, Verarbeitungs- und Stellelementen in der Elektropneumatik · Schaltpläne elektropneumatischer Steuerungen',pg:89,abb:[['Abb. 6.29 Signalelemente und Sensoren',90],['Abb. 6.30 Näherungsschalter',90],['Abb. 6.31 Berührungslose Näherungsschalter',90],['Abb. 6.32 Relais mit Schließer und Öffner',91],['Abb. 6.33 Elektropneumatische Steuerung',91]],b:[
    {p:'Elektropneumatik verbindet die Kraft der Pneumatik mit der flexiblen, günstigen Signalverarbeitung der Elektrik: Der elektrische Steuerteil erfasst und verknüpft Signale, Magnetventile schalten den pneumatischen Leistungsteil.'},
    {svg:{w:520,h:200,cap:'Elektropneumatik: elektrischer Steuerteil, Magnetventil als Schnittstelle, pneumatischer Leistungsteil',body:'<rect x="10" y="15" width="500" height="70" class="sk-c"/><text x="18" y="33" class="sk-t">Steuerteil (elektrisch, 24 V)</text><rect x="20" y="40" width="130" height="36" class="sk-body"/><text x="85" y="63" text-anchor="middle" class="sk-t">Taster, Sensor</text><line x1="150" y1="58" x2="183" y2="58" class="sk-f" marker-end="url(#ar)"/><rect x="185" y="40" width="140" height="36" class="sk-body"/><text x="255" y="63" text-anchor="middle" class="sk-t">Relais / SPS</text><line x1="325" y1="58" x2="358" y2="58" class="sk-f" marker-end="url(#ar)"/><rect x="360" y="40" width="140" height="36" class="sk-body"/><text x="430" y="63" text-anchor="middle" class="sk-t acc">Magnetspule</text><line x1="430" y1="76" x2="430" y2="108" class="sk-f" marker-end="url(#ar)"/><rect x="10" y="110" width="500" height="70" class="sk-c"/><text x="18" y="172" class="sk-t">Leistungsteil (pneumatisch, 6 bar)</text><rect x="360" y="118" width="140" height="36" class="sk-body"/><text x="430" y="141" text-anchor="middle" class="sk-t">Wegeventil</text><line x1="360" y1="136" x2="327" y2="136" class="sk-f" marker-end="url(#ar)"/><rect x="185" y="118" width="140" height="36" class="sk-body"/><text x="255" y="141" text-anchor="middle" class="sk-t">Zylinder, Motor</text><line x1="185" y1="136" x2="152" y2="136" class="sk-f" marker-end="url(#ar)"/><rect x="20" y="118" width="130" height="36" class="sk-body"/><text x="85" y="141" text-anchor="middle" class="sk-t">Bewegung, Kraft</text>'}},
    {tab:[['Sensor','reagiert auf','Einsatz'],['Grenztaster (mechanisch)','Berührung','Endlagen, robust, verschleißbehaftet'],['Druckschalter','Druckschwelle','Spanndruck überwachen'],['induktiv','Metalle (am besten Stahl)','Metallteile, Nocken, Endlagen'],['kapazitiv','fast alle Stoffe (auch Kunststoff, Holz, Flüssigkeiten)','Füllstand, Kunststoffteile'],['magnetisch (Reed, Hall)','Magnetfeld (Kolbenmagnet)','Zylinderendlagen durch die Wand'],['optisch','Licht (Einweg, Reflexion, Taster)','große Abstände, Teileerkennung'],['Ultraschall','Schallreflexion','Abstand, transparente Teile, Füllstand']]},
    {ul:['Berührungslose Sensoren sind verschleißfrei, klein und preisgünstig; Anschluss meist 3-Leiter (braun +, blau −, schwarz Signal)','Relais: Spule (A1/A2) zieht Anker an und betätigt Kontakte; Öffner 11-12, 21-22 …, Schließer 13-14, 23-24 …','Öffner sind unbetätigt geschlossen, Schließer unbetätigt offen – benannt nach dem, was beim Betätigen passiert','Stromlaufplan: Strompfade zwischen +24 V und 0 V, Bauteile in Ruhestellung; Verriegelungen über Kontakte, z. B. Start nur, wenn Endschalter „Zylinder hinten“ betätigt']},
    {bsp:{t:'Beispiel: Sensoren für eine Sortierstation wählen',b:['Kunststoffgehäuse auf dem Band erkennen → kapazitiver Sensor oder optischer Taster (induktiv reagiert nicht).','Endlagen des Ausschieberzylinders → Magnetfeldsensoren auf der Zylindernut, verschleißfrei.','Aluminiumdeckel zählen → induktiv mit Reduktionsfaktor beachten (Schaltabstand bei Aluminium deutlich kleiner als bei Stahl).','Bei Störungen zuerst LED am Sensor prüfen: leuchtet sie, liegt das Problem nachgelagert (Leitung, Eingang, Programm).']}},
    {falle:'Induktive Sensoren erkennen nur Metall – und Nichteisenmetalle mit verringertem Schaltabstand. Für Kunststoff oder Holz kapazitiv oder optisch wählen.'}
  ]},
  {t:'Instandhaltung pneumatischer Anlagen',h:'Geplante Instandhaltungsarbeiten zum Funktionserhalt · Ausfallursachen und deren Häufigkeit',pg:91,b:[
    {p:'Pneumatikbauteile sind in Funktion, Anschlussmaßen und Druckbereich genormt und relativ günstig. Deshalb beschränkt sich die Instandhaltung meist auf Inspektion; defekte Teile werden getauscht statt repariert.'},
    {ul:['Viele Bauteile sind Einwegteile; große Zylinder und Ventile lassen sich mit Verschleißteilsätzen (Dichtungen, Kolbenringe) überholen','Undichtigkeiten durch verschlissene Dichtungen senken Kraft und Geschwindigkeit – Türen, Klappen, Spanner arbeiten unzuverlässig','Typenschilder reichen für die Ersatzteilbestimmung oft nicht – Datenblatt und Bestellnummer heranziehen','Ausfallanalyse: Ausfall nach langer Laufzeit ist normaler Verschleiß; frühe oder wiederholte Ausfälle deuten auf Schmutz in der Luft, Überdruck, zu hohe Temperatur oder Feuchte, Vibration oder ein ungeeignetes Bauteil hin – Einsatzbedingungen mit Datenblatt vergleichen']},
    {ul:['Inspektionspunkte: Wartungseinheit (Filter, Kondensat, Druckeinstellung), Leckagen hören bzw. mit Ultraschall orten, Schläuche auf Knicke und Scheuerstellen, Schalldämpfer auf Verstopfung, Zylinderdämpfung und Endlagensensoren, Ölversorgung falls geölt']},
    {bsp:{t:'Beispiel: Ventile fallen nach wenigen Wochen aus',b:['Befund: Drei 5/2-Ventile an einer Verpackungsmaschine innerhalb von zwei Monaten defekt, Schieber klemmen.','Prüfung: Filterelement der Wartungseinheit seit Monaten nicht gewechselt, Kondensatbehälter voll; Rost- und Wasserspuren im Ventil.','Ursache: Wasser und Schmutz in der Druckluft. Maßnahmen: automatischen Kondensatablass einbauen, Filterwechsel in den GI-Plan, Kältetrockner der Station prüfen.','Ergebnis dokumentieren – Ventiltausch allein hätte das Problem nur verschoben.']}},
    {merke:'Pneumatikbauteile sind zuverlässig und langlebig. Häufige Ausfälle haben fast immer eine Ursache in Luftqualität, Druck oder Umgebung.'}
  ]},
  {t:'Hydraulik: Anwendung und Anlagenaufbau',h:'Hydraulische Steuer- und Regeleinrichtungen · Hydraulik in ihrer Anwendung · Hydraulische Anlagen als Zusammenfassung der Bauelemente',pg:92,abb:[['Abb. 6.34 Hydraulikanlage',95],['Abb. 6.35 Hydraulikaggregat',95]],b:[
    {p:'Hydrostatik nutzt hohe Drücke zur Übertragung großer Kräfte (Presse); Hydrodynamik nutzt strömende Flüssigkeit bei niedrigem Druck (hydrodynamische Kupplung, Drehmomentwandler). Industriehydraulik ist meist Hydrostatik.'},
    {ul:['Anwendungen: Werkzeugmaschinen, Hebebühnen, Krane, Stapler, Pressen, Baumaschinen, Fahrzeugbremsen und Lenkungen']},
    {tab:[['Vorteile','Nachteile'],['hohe Leistungsdichte, große Kräfte','Leckagen: wassergefährdende Flüssigkeit, Umwelt- und Rutschgefahr'],['Kraft und Geschwindigkeit stufenlos','Geräusche durch Druckpulsationen'],['Überlastschutz durch Druckbegrenzungsventil','schlechter Wirkungsgrad bei Drosselsteuerungen'],['hohe Betriebssicherheit und Lebensdauer','Filterung und Kühlung erforderlich'],['sehr genaue Positionierung (bis ca. ±1 µm)','Viskosität und damit Verluste temperaturabhängig'],['Anfahren unter Volllast, einfache Richtungsumkehr','Regelkreise schwingungsanfällig, komplexe Regler']]},
    {ul:['Aufbau: Energieversorgung (Aggregat: mechanisch → hydraulisch), Energiesteuerung (Ventile), Energiewandlung (Zylinder, Hydromotor: hydraulisch → mechanisch)','Behälter: Vorrat, Beruhigung und Entgasung, Ausgleich des Pendelvolumens; stationär ca. 4- bis 5-fache Pumpenfördermenge pro Minute, mobil bzw. mit Verstellpumpe 1- bis 2-fach; Saug- und Rücklaufleitung enden unter dem Ölspiegel, Rohrenden 45–60° angeschrägt','Pumpe mit Motor: stationär Elektromotor, mobil Verbrennungsmotor; konstantes oder verstellbares Fördervolumen','Rückschlagventil: verhindert Leerlaufen, hält Druck im Speicherbetrieb','Filter: hält die geforderte Reinheitsklasse; Rücklauf- oder Druckfilter, Saugfilter möglichst vermeiden; z. B. 10 µm bei β = 200 (1 von 200 Partikeln dieser Größe passiert, Abscheidegrad 99,5 %); am besten Dauerfiltration im Nebenstrom','Druckbegrenzungsventil: schützt vor Überdruck, muss den vollen Volumenstrom abführen können','Einfüll- und Belüftungsfilter: hält Schmutz beim Luftaustausch zurück','Temperatur: optimal um 50 °C; Mineralöl stationär max. ca. 70 °C, mobil bis ca. 90 °C; ggf. Kühlkreislauf','Hydrospeicher: speichert Volumen unter Druck (Stickstoff hinter Blase, Membran oder Kolben) für Druckhalten, Eilgang, Notfunktionen, Leckageausgleich, Pulsationsdämpfung','Messpunkte mit Messkupplungen; Rohrfeder-Manometer mit Glycerinfüllung, elektronische Drucksensoren für Fernanzeige und Regelung']},
    {svg:{w:520,h:330,cap:'Hydraulischer Grundschaltplan: Motor und Pumpe, Druckbegrenzungsventil, Manometer, 4/3-Wegeventil (Sperrmittelstellung, Magnet und Federzentrierung), Rücklauffilter, Zylinder',body:'<rect x="170" y="25" width="180" height="40" class="sk-l"/><line x1="220" y1="25" x2="220" y2="65" class="sk-l thick"/><line x1="220" y1="45" x2="400" y2="45" class="sk-l thick"/><text x="405" y="50" class="sk-t">MM1</text><path d="M185,65 V110 H250 V150" class="sk-l"/><path d="M335,65 V120 H270 V150" class="sk-l"/><text x="256" y="104" class="sk-t">A</text><text x="276" y="114" class="sk-t">B</text><rect x="185" y="150" width="50" height="45" class="sk-body"/><rect x="235" y="150" width="50" height="45" class="sk-body"/><rect x="285" y="150" width="50" height="45" class="sk-body"/><line x1="200" y1="195" x2="200" y2="152" class="sk-l" marker-end="url(#ar)"/><line x1="220" y1="150" x2="220" y2="193" class="sk-l" marker-end="url(#ar)"/><line x1="300" y1="195" x2="320" y2="152" class="sk-l" marker-end="url(#ar)"/><line x1="300" y1="150" x2="320" y2="193" class="sk-l" marker-end="url(#ar)"/><line x1="250" y1="150" x2="250" y2="160" class="sk-l"/><line x1="245" y1="160" x2="255" y2="160" class="sk-l"/><line x1="250" y1="195" x2="250" y2="185" class="sk-l"/><line x1="245" y1="185" x2="255" y2="185" class="sk-l"/><line x1="270" y1="150" x2="270" y2="160" class="sk-l"/><line x1="265" y1="160" x2="275" y2="160" class="sk-l"/><line x1="270" y1="195" x2="270" y2="185" class="sk-l"/><line x1="265" y1="185" x2="275" y2="185" class="sk-l"/><polyline points="185,172 180,165 175,179 170,165 165,179 160,172" class="sk-l"/><polyline points="335,172 340,165 345,179 350,165 355,179 360,172" class="sk-l"/><rect x="145" y="162" width="15" height="20" class="sk-body"/><line x1="145" y1="182" x2="160" y2="162" class="sk-l"/><rect x="360" y="162" width="15" height="20" class="sk-body"/><line x1="360" y1="182" x2="375" y2="162" class="sk-l"/><text x="140" y="177" text-anchor="end" class="sk-t">MB1</text><text x="380" y="177" class="sk-t">MB2</text><path d="M250,195 V240 H110 V252" class="sk-l"/><path d="M270,195 V255" class="sk-l"/><path d="M270,255 L282,268 L270,281 L258,268 Z" class="sk-l"/><line x1="259" y1="268" x2="281" y2="268" class="sk-c"/><text x="290" y="273" class="sk-t">Filter</text><line x1="270" y1="281" x2="270" y2="300" class="sk-l"/><path d="M255,298 V315 H285 V298" class="sk-l"/><circle cx="110" cy="270" r="18" class="sk-body"/><path d="M110,253 L117,265 L103,265 Z" class="fillacc"/><line x1="110" y1="288" x2="110" y2="300" class="sk-l"/><path d="M95,298 V315 H125 V298" class="sk-l"/><text x="82" y="248" text-anchor="end" class="sk-t">GP1</text><circle cx="45" cy="270" r="16" class="sk-body"/><text x="45" y="275" text-anchor="middle" class="sk-t">M</text><line x1="61" y1="267" x2="92" y2="267" class="sk-l"/><line x1="61" y1="273" x2="92" y2="273" class="sk-l"/><line x1="170" y1="240" x2="170" y2="255" class="sk-l"/><rect x="155" y="255" width="30" height="40" class="sk-body"/><line x1="178" y1="260" x2="178" y2="290" class="sk-l" marker-end="url(#ar)"/><path d="M170,248 H148 V275 H155" class="sk-c"/><polyline points="185,280 189,274 193,286 197,274 201,280" class="sk-l"/><line x1="170" y1="295" x2="170" y2="300" class="sk-l"/><path d="M158,298 V315 H182 V298" class="sk-l"/><text x="206" y="284" class="sk-t">DBV</text><line x1="215" y1="240" x2="215" y2="232" class="sk-l"/><circle cx="215" cy="220" r="12" class="sk-body"/><line x1="207" y1="228" x2="223" y2="212" class="sk-l" marker-end="url(#ar)"/>'}},
    {fx:['P = p · Q / 600','hydraulische Leistung in kW mit p in bar und Q in l/min; Motorleistung = P / η_ges']},
    {bsp:{t:'Beispiel: Aggregat für eine Biegepresse dimensionieren',b:['Gegeben: Betriebsdruck 160 bar, Förderstrom 40 l/min, Gesamtwirkungsgrad Pumpe/Motor 0,85, stationäre Maschine','Hydraulische Leistung: P = 160 · 40 / 600 = 10,67 kW','Motorleistung: 10,67 kW / 0,85 = 12,55 kW → Normmotor 15 kW','Behältervolumen: 4- bis 5-fache Förderung je Minute = 160 bis 200 l','Druckbegrenzungsventil auf ca. 10 % über Betriebsdruck einstellen und plombieren.']}},
    {merke:'Hydraulik = große Kräfte, kleine Baugröße, präzise Bewegung. Sauberkeit und Temperatur der Flüssigkeit entscheiden über die Lebensdauer.'}
  ]},
  {t:'Hydraulische Bauelemente',h:'Funktion der Bauelemente',pg:97,abb:[['Abb. 6.36 Pumpenbauformen',97],['Abb. 6.37 Hydraulikzylinderbauformen',98],['Abb. 6.38 Direkt gesteuertes 4/3-Wegeventil',99],['Abb. 6.39 Vorgesteuertes 4/3-Wegeventil',99],['Abb. 6.40 Entsperrbares Rückschlagventil',100],['Abb. 6.41 Drossel- und Drosselrückschlagventil',100],['Abb. 6.42 Stromregelventil',101],['Abb. 6.43 Ansteuerung eines Stetigventils',101]],b:[
    {p:'Hydraulikpumpen sind Verdrängerpumpen: Ein Raum füllt sich auf der Saugseite und wird zur Druckseite hin verkleinert. Der Druck entsteht erst durch den Widerstand des Verbrauchers.'},
    {ul:['Anforderungen an Pumpen: betriebssicher, langlebig, schmutzunempfindlich, leise, guter Wirkungsgrad, pulsationsarm','Bauarten: Außen- und Innenzahnradpumpe, Flügelzellenpumpe (auch verstellbar), Axial- und Radialkolbenpumpe, Reihenkolbenpumpe, Schraubenpumpe','Kenndaten: maximaler Betriebsdruck, maximaler Förderstrom, Bauart, Wirkungsgrad, Drehzahl, Antriebsleistung, Konstant- oder Verstellpumpe, Ansaugverhalten, Schmutzempfindlichkeit, Geräusch']},
    {tab:[['Zylinderbauform','Merkmal'],['einfach wirkend','Kraft nur in eine Richtung, Rückhub durch Feder oder äußere Last (z. B. Plungerzylinder)'],['doppelt wirkend, einseitige Stange (Differenzialzylinder)','unterschiedliche Kräfte und Geschwindigkeiten aus und ein'],['durchgehende Kolbenstange (Gleichgangzylinder)','gleiche Kraft und Geschwindigkeit in beiden Richtungen'],['Mehrstellungszylinder','zwei Zylinder in einem Gehäuse, mehrere Positionen'],['Tandemzylinder','mehrere Kolben hintereinander: große Kraft bei kleinem Durchmesser'],['Teleskopzylinder','ineinandergeschachtelt, langer Hub; Kraft bestimmt durch die kleinste wirksame Fläche']]},
    {fx:['F = p · A · η;  v = Q / A','Kraft aus Druck, Geschwindigkeit aus Volumenstrom – jeweils über die wirksame Fläche']},
    {bsp:{t:'Beispiel: Kraft und Geschwindigkeit eines Hydraulikzylinders',b:['Gegeben: D = 80 mm, d = 45 mm, p = 120 bar = 1 200 N/cm², Q = 30 l/min, η = 0,95','A_K = π/4 · 8² = 50,27 cm²;  A_R = 50,27 − π/4 · 4,5² = 34,36 cm²','Ausfahrkraft: F = 1 200 · 50,27 · 0,95 = 57 303 N ≈ 57,3 kN','Einfahrkraft: F = 1 200 · 34,36 · 0,95 = 39 172 N ≈ 39,2 kN','v_aus = 30 000 cm³/min / 50,27 cm² = 597 cm/min ≈ 0,10 m/s','v_ein = 30 000 / 34,36 = 873 cm/min ≈ 0,15 m/s','Interpretation: Der Rückhub ist rund 1,5-mal schneller, aber mit kleinerer Kraft – typisch für Differenzialzylinder.']}},
    {ul:['Hydromotoren: Umkehrung des Pumpenprinzips, viele Pumpen auch als Motor nutzbar; Schwenkmotoren mit begrenztem Winkel','Wegeventile: Kolbenschieber (einfach, mit innerer Leckage) oder Sitzventil (leckagefrei, hohe Drücke, kleinere Ströme); große Nennweiten werden hydraulisch vorgesteuert','Anschlüsse in der Hydraulik: P Pumpe, T Tank, A und B Arbeitsleitungen','Sperrventile: Rückschlagventil (auch als Vorspannventil oder Bypass), entsperrbares Rückschlagventil (hält Lasten leckagefrei, z. B. Hebebühne), Wechselventil (ODER)','Stromventile: Drosselventil (Geschwindigkeit lastabhängig, bei scharfkantiger Blende kaum temperaturabhängig), Drosselrückschlagventil (Einbaurichtung beachten), Stromregelventil mit Druckwaage (Volumenstrom bleibt bei wechselnder Last konstant)','Druckventile: Druckbegrenzungsventil (normal geschlossen), Druckreduzierventil (normal offen, begrenzt Ausgangsdruck), Druckschaltventil bzw. Folgeventil (schaltet bei Erreichen eines Drucks weitere Verbraucher zu)','Proportionalventile (Stetigventile): Proportionalmagnet und elektronischer Verstärker wandeln ein analoges Signal in Kolbenstellung; damit Geschwindigkeit, sanftes Anfahren und Bremsen; Kolbenlage per Wegaufnehmer geregelt']},
    {merke:'Druck bestimmt die Kraft, Volumenstrom die Geschwindigkeit. Wer schneller fahren will, braucht mehr Förderstrom – nicht mehr Druck.'},
    {falle:'Drosselrückschlagventil falsch herum eingebaut: Die Drosselung wirkt in der falschen Richtung. Einbaurichtung immer mit dem Schaltplan abgleichen.'}
  ]},
  {t:'Hydraulik: Pläne, Ersatzteile, Flüssigkeit und Sicherheit',h:'Hydraulikschaltplan und Sinnbilder der Hydraulikelemente · Funktionsplan, Funktionsdiagramm, Ablaufplan und Stromlaufplan als Mittel der Überwachung von Hydraulikanlagen · Ersatzteilbevorratung/Ersatzteilvorhaltung · Hydraulikflüssigkeit und ihr Einfluss auf die Funktionstüchtigkeit von Hydraulikanlagen · Funktion der Anlagenteile und Anlagensicherheit',pg:101,b:[
    {p:'Zur Überwachung und Fehlersuche gehört eine vollständige Dokumentation in mehreren Planarten. Dazu kommen die richtige Ersatzteilhaltung, die passende Hydraulikflüssigkeit und regelmäßige Sicherheitsprüfungen.'},
    {tab:[['Unterlage','Zeigt','Nutzen bei der Fehlersuche'],['Systemschaltplan','Bauteile funktionsgerecht, nicht lagerichtig angeordnet','Übersicht, Funktionszusammenhang'],['Lageschaltplan','Bauteile an ihrem tatsächlichen Einbauort','Bauteil in großen Anlagen finden'],['Stromlaufplan','elektrische Verdrahtung, Klemmen, SPS-Ein-/Ausgänge','Signalweg prüfen'],['Belegungsliste','Zuordnung Bauteilkennzeichen ↔ SPS-Adresse','Schaltplan mit Programm verknüpfen'],['Ablaufplan/GRAFCET/Funktionsdiagramm','logischer Ablauf, Schritte, Bedingungen','fehlendes Weiterschaltsignal erkennen'],['SPS-Programm','herstellerspezifische Umsetzung','Online-Status beobachten']]},
    {ul:['Ersatzteile: Ventile, Pumpen, Zylinder, Motoren, Schläuche, Filter bevorraten und rechtzeitig nachbestellen','Bauteilaufdruck reicht oft nicht – Datenblatt (Durchfluss, elektrische Daten, Einbaumaße) einsehen','Stetigventile nur gegen baugleiche Ventile desselben Herstellers tauschen; Ansteuersignale sind nicht genormt, sonst drohen unkontrollierte Bewegungen']},
    {tab:[['Flüssigkeitsgruppe','Kennzeichnung','Einsatz'],['Mineralöle','HLP, HVLP (mit Zusätzen gegen Verschleiß, Viskositätsindex verbessert)','Standard im Maschinenbau'],['schwer entflammbar','HFA, HFB, HFC (wasserhaltig), HFD (wasserfrei synthetisch)','Gießerei, Schmiede, Bergbau, Nähe zu Zündquellen'],['umweltverträglich','HETG, HEES, HEPG, HEPR','Mobil-, Land- und Forsttechnik, Wasserbau']]},
    {ul:['Aufgaben der Flüssigkeit: Energieübertragung, Schmierung, Korrosionsschutz, Wärme- und Schmutzabtransport','Wichtige Eigenschaften: Viskosität und Temperaturverhalten, Verträglichkeit mit Dichtungen und Metallen, Alterungsbeständigkeit, Umweltverträglichkeit, Entflammbarkeit','Ölzustand regelmäßig prüfen lassen (Ölanalyse: Partikel, Wasser, Viskosität, Säurezahl); Sorten nicht ohne Freigabe mischen']},
    {ul:['Hydraulikbauteile vor der ersten Benutzung und danach regelmäßig prüfen; bei Mängeln oder Alterung tauschen (BetrSichV, Gefährdungsbeurteilung)','Schlauchleitungen: Gefahr durch Peitschen beim Herausreißen und durch Flüssigkeitsstrahl (Injektionsverletzung); DGUV Regel 113-020 empfiehlt begrenzte Lager- und Verwendungsdauer (Richtwert 6 Jahre ab Herstellung inkl. max. 2 Jahre Lagerung); Prüffristen durch befähigte Person festlegen','Hydrospeicher als Druckgerät: Prüfung vor Inbetriebnahme und wiederkehrend durch befähigte Person oder ZÜS je nach Druck-Liter-Produkt','Sicherheitsblock am Speicher: verplombtes Druckbegrenzungsventil, Manometer und Messanschluss, Absperr- und Ablasshahn, Warnhinweis „vor Arbeiten flüssigkeitsseitig drucklos machen“']},
    {bsp:{t:'Beispiel: Schlauchprüfplan einer Spritzgießmaschine',b:['Schlauch mit Herstellungsdatum 03/2021, eingebaut 02/2022.','Verwendungsdauer laut Gefährdungsbeurteilung 6 Jahre ab Herstellung → Austausch spätestens 03/2027.','Zwischenprüfung jährlich durch befähigte Person: Scheuerstellen, Blasen, Leckage an der Armatur, Knickschutz; Ergebnis im Prüfbuch.','Bei Ersatz nur Schläuche mit passendem Druck, Medium und Temperatur einsetzen und Schlauchschutz anbringen.']}},
    {merke:'Vor Arbeiten an Hydraulik: abschalten, sichern, Speicher entladen, Lasten mechanisch abstützen, Restdruck am Manometer prüfen.'}
  ]},
  {t:'Elektrische Steuerungen',h:'Elektrische und elektronische Steuer- und Regeleinrichtungen · Komplexe Produktionssysteme, Maschinen und Anlagen · Elektrische Steuerungen nach der Realisierungsform',pg:104,abb:[['Abb. 6.44 Verknüpfungssteuerung ohne Speicherverhalten',105],['Abb. 6.45 Logiksteuerung ohne Speicherverhalten',105],['Abb. 6.46–6.49 ODER-Verknüpfung, vorrangiges Setzen/Rücksetzen',106]],b:[
    {p:'Elektrik ist die dritte Energieform der Automatisierung. Arbeiten an elektrischen Anlagen sind Elektrofachkräften vorbehalten (DGUV Vorschrift 3). Moderne Anlagen (Frequenzumrichter, Roboter, 3D-Druck) erfordern zunehmend herstellerspezifische Spezialkenntnisse für Bedienung und Instandhaltung.'},
    {tab:[['Steuerungsart','Prinzip','Beispiel'],['Verknüpfungssteuerung ohne Speicher (Schaltnetz)','Ausgang nur, solange die Eingangsbedingung erfüllt ist','UND: Reihenschaltung zweier Taster (Zweihand); ODER: Parallelschaltung'],['Verknüpfungssteuerung mit Speicher','kurzer Impuls setzt, anderer Befehl setzt zurück (Selbsthaltung)','Motor EIN/AUS mit Tastern'],['Ablaufsteuerung zeitgeführt','Weiterschalten nach Zeit','Ampel, Waschzyklus'],['Ablaufsteuerung prozessgeführt','Weiterschalten nach Rückmeldung aus dem Prozess','Werkzeugmaschine, Roboter, Reaktor']]},
    {svg:{w:520,h:262,cap:'Stromlaufplan einer Selbsthaltung mit vorrangigem Ausschalten (Öffner SF1 vor der Parallelschaltung)',body:'<line x1="20" y1="25" x2="500" y2="25" class="sk-l thick"/><line x1="20" y1="235" x2="500" y2="235" class="sk-l thick"/><text x="22" y="18" class="sk-t">+24 V</text><text x="22" y="252" class="sk-t">0 V</text><line x1="120" y1="25" x2="120" y2="45" class="sk-l"/><line x1="120" y1="45" x2="120" y2="53" class="sk-l"/><line x1="120" y1="53" x2="132" y2="53" class="sk-l"/><line x1="120" y1="75" x2="120" y2="83" class="sk-l"/><line x1="120" y1="75" x2="134" y2="51" class="sk-l"/><text x="104" y="69" text-anchor="end" class="sk-t">SF1 (AUS)</text><line x1="120" y1="83" x2="120" y2="100" class="sk-l"/><line x1="120" y1="100" x2="200" y2="100" class="sk-l"/><line x1="120" y1="100" x2="120" y2="108" class="sk-l"/><line x1="120" y1="130" x2="120" y2="138" class="sk-l"/><line x1="120" y1="130" x2="108" y2="110" class="sk-l"/><text x="104" y="124" text-anchor="end" class="sk-t">SF2</text><line x1="200" y1="100" x2="200" y2="108" class="sk-l"/><line x1="200" y1="130" x2="200" y2="138" class="sk-l"/><line x1="200" y1="130" x2="188" y2="110" class="sk-l"/><text x="210" y="124" text-anchor="start" class="sk-t">KF1</text><line x1="120" y1="138" x2="120" y2="155" class="sk-l"/><line x1="200" y1="138" x2="200" y2="155" class="sk-l"/><line x1="120" y1="155" x2="200" y2="155" class="sk-l"/><line x1="160" y1="155" x2="160" y2="172" class="sk-l"/><rect x="145" y="172" width="30" height="30" class="sk-body"/><text x="182" y="192" class="sk-t">KF1</text><line x1="160" y1="202" x2="160" y2="235" class="sk-l"/><line x1="330" y1="25" x2="330" y2="60" class="sk-l"/><line x1="330" y1="60" x2="330" y2="68" class="sk-l"/><line x1="330" y1="90" x2="330" y2="98" class="sk-l"/><line x1="330" y1="90" x2="318" y2="70" class="sk-l"/><text x="314" y="84" text-anchor="end" class="sk-t">KF1</text><line x1="330" y1="98" x2="330" y2="172" class="sk-l"/><rect x="315" y="172" width="30" height="30" class="sk-body"/><text x="352" y="192" class="sk-t">QA1 (Motor)</text><line x1="330" y1="202" x2="330" y2="235" class="sk-l"/><text x="380" y="70" class="sk-t">SF1 = AUS-Taster</text><text x="380" y="90" class="sk-t">SF2 = EIN-Taster</text><text x="380" y="110" class="sk-t">KF1 hält sich selbst</text><text x="380" y="140" class="sk-t acc">Öffner in Reihe:</text><text x="380" y="160" class="sk-t acc">AUS hat Vorrang</text>'}},
    {ul:['Vorrangiges Setzen: Öffner (AUS) parallel zum Einschaltzweig – bei gleichzeitiger Betätigung zieht das Relais an','Vorrangiges Rücksetzen: Öffner (AUS) in Reihe vor dem Einschaltzweig – bei gleichzeitiger Betätigung fällt das Relais ab; für EIN/AUS-Funktionen vorgeschrieben','Darstellung von Verknüpfungen: Funktionstabelle, Funktionsgleichung, Funktionsplan mit Logiksymbolen (& für UND, ≥1 für ODER)','Stern-Dreieck-Anlauf: Drehstrommotoren ziehen beim Direktanlauf ein Mehrfaches des Nennstroms; in Sternschaltung sinken Anlaufstrom und Moment auf etwa ein Drittel; Umschalten nach Hochlauf meist per Zeitrelais; Stern- und Dreieckschütz gegenseitig verriegelt (sonst Kurzschluss); heute oft ersetzt durch Sanftanlauf oder Frequenzumrichter']},
    {bsp:{t:'Beispiel: Anlaufstrom eines 22-kW-Motors',b:['Gegeben: Nennstrom 41 A; Direktanlauf ca. 6- bis 8-facher Nennstrom','Direktanlauf: 6 · 41 A = 246 A bis 8 · 41 A = 328 A','Stern-Dreieck: etwa ein Drittel → ca. 82 A bis 109 A','Folgerung: Ohne Anlaufhilfe würden Sicherungen auslösen oder das Netz einbrechen; bei Lastanlauf (Pumpe gegen Druck) reicht das reduzierte Moment in Stern evtl. nicht – dann Frequenzumrichter.']}},
    {merke:'Für EIN/AUS gilt: AUS hat Vorrang. Not-Halt wirkt immer, auch wenn gleichzeitig EIN gedrückt wird.'}
  ]},
  {t:'Speicherprogrammierbare Steuerungen und Bussysteme',h:'Speicherprogrammierbare Steuerungen · Industrielle Bussysteme',pg:108,abb:[['Abb. 6.50 SPS-Steuerung (Hardware)',109]],b:[
    {p:'Bei verbindungsprogrammierten Steuerungen (VPS) legt die Verdrahtung die Funktion fest; bei speicherprogrammierbaren Steuerungen (SPS) ein Programm. Jede Funktionsänderung einer VPS bedeutet neu verdrahten.'},
    {tab:[['Merkmal','VPS','SPS'],['Funktion festgelegt durch','Verdrahtung (Schütze, Relais)','Programm im Speicher'],['Änderung','aufwendig: neu verdrahten','schnell: Programm ändern'],['Platz','groß','klein'],['Vernetzung','kaum','mit anderen SPS, Leitsystem, Bus'],['Fehlersuche','Messen an Klemmen','Online-Status von Ein- und Ausgängen'],['Stärke','robust, keine IT nötig','flexibel, Diagnose, Datenerfassung']]},
    {svg:{w:520,h:255,cap:'Aufbau einer SPS: Signale laufen von den Sensoren über Ein- und Ausgabebaugruppen zu den Aktoren',body:'<rect x="8" y="95" width="82" height="50" class="sk-body"/><text x="49" y="125" text-anchor="middle" class="sk-t">Sensoren</text><line x1="90" y1="120" x2="108" y2="120" class="sk-f" marker-end="url(#ar)"/><rect x="110" y="95" width="82" height="50" class="sk-body"/><text x="151" y="125" text-anchor="middle" class="sk-t">Eingänge</text><line x1="192" y1="120" x2="210" y2="120" class="sk-f" marker-end="url(#ar)"/><rect x="212" y="70" width="110" height="100" class="sk-body"/><text x="267" y="90" text-anchor="middle" class="sk-t acc">CPU</text><text x="267" y="110" text-anchor="middle" class="sk-t">Programm</text><text x="267" y="128" text-anchor="middle" class="sk-t">Merker</text><text x="267" y="146" text-anchor="middle" class="sk-t">Zeiten, Zähler</text><line x1="322" y1="120" x2="340" y2="120" class="sk-f" marker-end="url(#ar)"/><rect x="342" y="95" width="82" height="50" class="sk-body"/><text x="383" y="125" text-anchor="middle" class="sk-t">Ausgänge</text><line x1="424" y1="120" x2="442" y2="120" class="sk-f" marker-end="url(#ar)"/><rect x="444" y="95" width="70" height="50" class="sk-body"/><text x="479" y="125" text-anchor="middle" class="sk-t">Aktoren</text><rect x="212" y="10" width="110" height="34" class="sk-body"/><text x="267" y="32" text-anchor="middle" class="sk-t">Netzteil</text><line x1="267" y1="44" x2="267" y2="68" class="sk-l" marker-end="url(#ar)"/><rect x="192" y="205" width="150" height="36" class="sk-body"/><text x="267" y="228" text-anchor="middle" class="sk-t">Programmiergerät</text><line x1="267" y1="172" x2="267" y2="203" class="sk-c"/><text x="50" y="165" text-anchor="middle" class="sk-t">Taster, Geber</text><text x="479" y="165" text-anchor="middle" class="sk-t">Ventile,</text><text x="479" y="183" text-anchor="middle" class="sk-t">Schütze</text>'}},
    {ul:['Automatisierungsgerät: Netzteil, CPU mit Programmspeicher, Prozessabbild, Merkern, Zeiten und Zählern, digitale und analoge Ein- und Ausgabebaugruppen','Programmiergerät: eigenständiges Gerät oder Notebook mit Software; zeigt Status von Ein-/Ausgängen und Bausteinen in Echtzeit','Programmiersprachen nach IEC 61131-3: Kontaktplan KOP (wie Stromlaufplan), Funktionsbausteinsprache FBS/FUP (Logiksymbole, sehr verbreitet), Strukturierter Text ST, Ablaufsprache AS; Anweisungsliste AWL gilt als veraltet','Herstellerspezifische Adressen (z. B. E 0.1, A 1.0) – deshalb Belegungsliste zwischen Schaltplan und Programm']},
    {svg:{w:520,h:265,body:'<rect x="170" y="15" width="180" height="44" class="sk-body"/><text x="260" y="33" text-anchor="middle" class="sk-t">Prozessabbild der</text><text x="260" y="51" text-anchor="middle" class="sk-t">Eingänge lesen</text><rect x="330" y="110" width="180" height="44" class="sk-body"/><text x="420" y="128" text-anchor="middle" class="sk-t">Anwenderprogramm</text><text x="420" y="146" text-anchor="middle" class="sk-t">abarbeiten</text><rect x="170" y="205" width="180" height="44" class="sk-body"/><text x="260" y="223" text-anchor="middle" class="sk-t">Prozessabbild der</text><text x="260" y="241" text-anchor="middle" class="sk-t">Ausgänge schreiben</text><rect x="10" y="110" width="180" height="44" class="sk-body"/><text x="100" y="128" text-anchor="middle" class="sk-t">Betriebssystem,</text><text x="100" y="146" text-anchor="middle" class="sk-t">Kommunikation</text><path d="M350,37 Q420,37 420,108" class="sk-f" marker-end="url(#ar)"/><path d="M420,154 Q420,227 352,227" class="sk-f" marker-end="url(#ar)"/><path d="M170,227 Q100,227 100,156" class="sk-f" marker-end="url(#ar)"/><path d="M100,110 Q100,37 168,37" class="sk-f" marker-end="url(#ar)"/><text x="260" y="128" text-anchor="middle" class="sk-t acc">Zyklus</text><text x="260" y="146" text-anchor="middle" class="sk-t">(Zykluszeit)</text>',cap:'Zyklische Programmbearbeitung einer SPS'}},
    {ol:['Selbsttest nach dem Einschalten','Eingänge einlesen (Prozessabbild der Eingänge)','Programm Anweisung für Anweisung abarbeiten','Ergebnisse ins Prozessabbild der Ausgänge schreiben und ausgeben','Zyklus beginnt von vorn; die Dauer heißt Zykluszeit (je nach Programmgröße und CPU wenige ms)']},
    {svg:{w:520,h:290,cap:'Links jeder Sensor mit eigener Leitung, rechts alle Teilnehmer adressiert an einer Busleitung',body:'<rect x="20" y="30" width="90" height="40" class="sk-body"/><text x="65" y="55" text-anchor="middle" class="sk-t">SPS</text><text x="130" y="275" text-anchor="middle" class="sk-t acc">Parallelverdrahtung</text><rect x="290" y="30" width="90" height="40" class="sk-body"/><text x="335" y="55" text-anchor="middle" class="sk-t">SPS</text><text x="410" y="275" text-anchor="middle" class="sk-t acc">Bussystem</text><rect x="190" y="90" width="50" height="24" class="sk-body"/><text x="215" y="107" text-anchor="middle" class="sk-t">S1</text><path d="M40,70 V102 H190" class="sk-l"/><rect x="190" y="130" width="50" height="24" class="sk-body"/><text x="215" y="147" text-anchor="middle" class="sk-t">S2</text><path d="M54,70 V142 H190" class="sk-l"/><rect x="190" y="170" width="50" height="24" class="sk-body"/><text x="215" y="187" text-anchor="middle" class="sk-t">S3</text><path d="M68,70 V182 H190" class="sk-l"/><rect x="190" y="210" width="50" height="24" class="sk-body"/><text x="215" y="227" text-anchor="middle" class="sk-t">S4</text><path d="M82,70 V222 H190" class="sk-l"/><line x1="335" y1="70" x2="335" y2="220" class="sk-l thick"/><rect x="440" y="83" width="50" height="24" class="sk-body"/><text x="465" y="100" text-anchor="middle" class="sk-t">S1</text><line x1="335" y1="95" x2="440" y2="95" class="sk-l"/><rect x="440" y="123" width="50" height="24" class="sk-body"/><text x="465" y="140" text-anchor="middle" class="sk-t">S2</text><line x1="335" y1="135" x2="440" y2="135" class="sk-l"/><rect x="440" y="163" width="50" height="24" class="sk-body"/><text x="465" y="180" text-anchor="middle" class="sk-t">S3</text><line x1="335" y1="175" x2="440" y2="175" class="sk-l"/><rect x="440" y="203" width="50" height="24" class="sk-body"/><text x="465" y="220" text-anchor="middle" class="sk-t">S4</text><line x1="335" y1="215" x2="440" y2="215" class="sk-l"/><text x="420" y="246" text-anchor="middle" class="sk-t">eine Leitung, Daten seriell</text>'}},
    {ul:['Bussystem: Sensoren und Aktoren (Feldgeräte) kommunizieren über eine gemeinsame Leitung mit der Steuerung','Protokoll legt fest, wer (Adresse) was (Messwert, Befehl) wann (Zugriffsverfahren) sendet; Daten werden seriell übertragen','Vorteile: weniger Verdrahtung, Klemmstellen und Fehlerquellen, Diagnose bis zum Sensor, einfache Erweiterung','Beispiele: PROFINET, EtherCAT, EtherNet/IP (Ethernet-basiert), PROFIBUS, CANopen, AS-Interface, IO-Link (Punkt-zu-Punkt zum Sensor)']},
    {bsp:{t:'Beispiel: Fehlersuche mit dem SPS-Status',b:['Störung: Förderband läuft nicht an, obwohl Start gedrückt.','Online-Status: Ausgang A 1.0 (Bandmotor) ist 0, Verknüpfung erfordert E 0.1 (Start), E 0.3 (Schutztür zu) und E 0.4 (Motorschutz ok).','E 0.3 zeigt 0 – Sensor an der Schutztür meldet „offen“, obwohl die Tür zu ist.','Ursache: Sensor verstellt bzw. verschmutzt. Nachjustieren, Funktion prüfen, Störung im Instandhaltungssystem dokumentieren. Kein Überbrücken der Schutztürüberwachung!']}},
    {falle:'Not-Halt und Schutztürüberwachung gehören nicht allein in die Standard-SPS: Sicherheitsfunktionen brauchen eine Sicherheitssteuerung oder ein Sicherheitsrelais mit nachgewiesenem Performance Level (EN ISO 13849).'}
  ]},
  {t:'Diagnosesysteme, Condition Monitoring und Predictive Maintenance',h:'Diagnosesysteme an Maschinen und Anlagen',pg:111,b:[
    {p:'Diagnosesysteme vergleichen Istwerte wie Temperatur, Druck, Stromaufnahme oder Schwingung mit Grenz- und Sollwerten und melden kritische Zustände. Trendaufzeichnungen zeigen Verschleiß und Überlast frühzeitig.'},
    {svg:{w:520,h:280,cap:'Zustandsverlauf bis zum Ausfall: Je früher ein Messverfahren den Schaden erkennt, desto mehr Zeit bleibt zur Planung',body:'<line x1="50" y1="220" x2="505" y2="220" class="sk-l" marker-end="url(#ar)"/><line x1="50" y1="220" x2="50" y2="20" class="sk-l" marker-end="url(#ar)"/><text x="500" y="240" text-anchor="end" class="sk-t">Zeit</text><text x="58" y="25" class="sk-t">Zustand</text><polyline points="60,54 69.5,54 79,54 88.5,54 98,54 107.5,54 117,54 126.5,54 136,54 145.5,54 155,54 164.5,54 174,54 183.5,54 193,54.5 202.5,55.5 212,57 221.5,58.5 231,60.5 240.5,63 250,66 259.5,69 269,72.5 278.5,76.5 288,81 297.5,86 307,91 316.5,96.5 326,102.5 335.5,108.5 345,115 354.5,122 364,129.5 373.5,137.5 383,145.5 392.5,154 402,163 411.5,172.5 421,182 430.5,192 440,202.5" class="sk-l thick"/><circle cx="231" cy="60.58035714285717" r="5" class="fillacc"/><circle cx="326" cy="102.32142857142858" r="5" class="fillacc"/><circle cx="383" cy="145.58035714285717" r="5" class="fillacc"/><circle cx="440" cy="202.5" r="5" class="fillacc"/><text x="241" y="52.58035714285717" class="sk-t">P: Schwingung messbar</text><text x="336" y="96.32142857142858" class="sk-t">Geräusch hörbar</text><text x="393" y="141.58035714285717" class="sk-t">Wärme</text><text x="447" y="207.5" class="sk-t acc">F: Ausfall</text><line x1="231" y1="250" x2="440" y2="250" class="sk-f" marker-end="url(#ar)"/><text x="335.5" y="270" text-anchor="middle" class="sk-t">P-F-Intervall: Zeit für geplanten Eingriff</text>'}},
    {ul:['Condition Monitoring (Zustandsüberwachung): Ziele Sicherheit (schnelle Abschaltung) und Effizienz; Voraussetzung für zustandsorientierte Instandhaltung','Nutzt die Lebensdauer kritischer Teile fast vollständig und plant Eingriffe passend zum Produktionsplan','Erkennt Verschleiß und Ermüdung (aus gemessenen Belastungen lässt sich die Restlebensdauer abschätzen), aber keinen plötzlichen Gewaltbruch','Beispiele: Körperschall an Wälzlagern, Schwingungsmessung an Lüftern und Pumpen, Ölanalyse, Thermografie, Motorstromanalyse','Internet der Dinge (IoT): Geräte stellen ihren Zustand im Netzwerk bereit; nötig sind Standardisierung, sichere und einfache Netzanbindung, geringe Kosten je Teilnehmer und automatisierte digitale Dienste','Predictive Maintenance: 1. Daten erfassen, digitalisieren, übertragen – 2. speichern, analysieren, bewerten – 3. Eintrittswahrscheinlichkeiten berechnen (oft mit KI, Big Data)','Cloud-Computing: Rechenleistung, Speicher und Anwendungen als Dienst über das Netz statt lokal']},
    {bsp:{t:'Beispiel: Schwingungsüberwachung eines Abluftventilators',b:['Grenzwerte nach Maschinenklasse (Orientierung ISO 20816): Warnung bei 2,8 mm/s, Alarm bei 4,5 mm/s Schwinggeschwindigkeit.','Trend: 6 Monate stabil bei 1,5 mm/s, dann innerhalb von 3 Wochen Anstieg auf 3,2 mm/s → Warnung.','Analyse: Frequenzspektrum zeigt Lagerschaden am Außenring.','Maßnahme: Lagerwechsel im nächsten Wochenendstillstand geplant, Lager vorab bestellt – kein ungeplanter Ausfall, keine Produktionsunterbrechung.']}},
    {merke:'Condition Monitoring verlängert die Nutzung und macht Ausfälle planbar – je früher ein Verfahren den Schaden erkennt, desto mehr Vorlaufzeit bleibt.'}
  ]},
  {t:'Materialwirtschaft, Logistik und Lagerarten',h:'Veranlassen von Maßnahmen zur Lagerung von Werk- und Hilfsstoffen sowie Produkten · Materialflusssteuerung · Funktionen',pg:115,abb:[['Abb. 7.1 Einordnung der Materialwirtschaft',115],['Abb. 7.2 Logistiksystem',116]],b:[
    {p:'Lagern gehört zur Materialwirtschaft. Sie stellt Stoffe, Handelswaren und Halbfabrikate bereit (beschaffen, transportieren, lagern, am Bedarfsort bereitstellen) und kümmert sich um Wiederverwendung und Entsorgung. Je nach Kompetenzbereich gehören auch Einkauf, Disposition und Fertigungssteuerung dazu.'},
    {ul:['Materialfluss = Abfolge von Lager-, Transport- und Bearbeitungsvorgängen; Ziel der Materialflusssteuerung: Tätigkeiten wie Wareneingang, Prüfung, Einlagerung so gestalten, dass die Materialkosten minimal bleiben','Logistik im Unternehmen: Beschaffungslogistik (bis zur Übergabe an die Produktion), Produktionslogistik (Fluss im Werk), Absatz-/Distributionslogistik (termin- und qualitätsgerecht zum Kunden), Entsorgungslogistik (Verwertung, Entsorgung) – immer als Gesamtsystem betrachten']},
    {tab:[['Gliederung','Varianten','Hinweis'],['Standort','zentral – dezentral','zentral: weniger Bestand, effizienter Personaleinsatz; dezentral: nah am Bedarf, spezielle Lagerbedingungen'],['Automatisierung','manuell – teilautomatisch – vollautomatisch','vollautomatisch über ERP/Lagerverwaltung gesteuert, aus Sicherheitsgründen menschenleer'],['Eigentum','Eigenlager – Fremdlager','Konsignationslager (Ware gehört dem Lieferanten bis zur Entnahme), Kommissionslager (Dritter betreibt das Lager)'],['Produktionsstufe','Eingangs-, Produktions-, Erzeugnislager',''],['weitere','Haupt-/Nebenlager, offen/geschlossen, Boden-, Block-, Hochregallager','nach Lagergut: Werkzeuge, Büromaterial, Abfälle'],['Sonderfall','Instandhaltungslager','Verfügbarkeit der Anlagen steht vor den Lagerkosten']]},
    {ul:['Lagerfunktionen: Puffer- und Sicherheitsfunktion (jederzeit lieferfähig), Veredelungsfunktion (Reifen, Trocknen, Aushärten), Spekulationsfunktion (Einkauf vor erwarteter Preissteigerung)','Fördermittel im Lager: Stetigförderer (Band, Rollenbahn, Kettenförderer) und Unstetigförderer (Stapler, Kran, Aufzug, Regalbediengerät)','Lagerprinzipien: FIFO (first in – first out, gegen Überalterung), LIFO (last in – first out, z. B. Schüttgut), FEFO (first expired – first out, Haltbarkeitsdatum)']},
    {bsp:{t:'Beispiel: Lagerkonzept für Klebstoffe und Normteile',b:['Zweikomponenten-Klebstoff mit Haltbarkeitsdatum: FEFO, dezentral im klimatisierten Schrank an der Montage, Mindestbestand für 2 Wochen.','Schrauben und Muttern (C-Teile): Kanban-Behälter direkt am Arbeitsplatz, vom Lieferanten befüllt (Konsignation).','Fertige Baugruppen: zentrales Erzeugnislager mit chaotischer Lagerplatzvergabe und Scanner-Buchung.']}},
    {merke:'Jeder Lagerbestand bindet Kapital und Fläche. Lagern ist nur so viel wie nötig, so wenig wie möglich.'}
  ]},
  {t:'Materialbedarf ermitteln',h:'Aufgaben',pg:117,abb:[['Abb. 7.3 Stücklistenauflösung (Gozintograph)',118]],b:[
    {p:'Die Materialdisposition ermittelt den Bedarf einer Periode, sichert die Versorgung und kontrolliert den Ablauf. Sie stimmt Bedarfs-, Bestands- und Bestelldisposition mit Einkauf, Produktion und Vertrieb ab.'},
    {tab:[['Verfahren','Grundlage','Genauigkeit'],['deterministisch (programmgesteuert)','Produktionsprogramm und Stücklisten (Stücklistenauflösung)','hoch'],['stochastisch (verbrauchsgesteuert)','Verbrauchswerte der Vorperioden, Prognose','mittel, für C-Teile ausreichend'],['heuristisch (Schätzung)','Erfahrung, Analogie zu ähnlichen Produkten','gering – Gefahr von Über- oder Unterdeckung']]},
    {svg:{w:520,h:305,cap:'Gozintograph einer Spannvorrichtung: Zahlen an den Pfeilen = Menge je übergeordneter Einheit',body:'<rect x="220" y="15" width="80" height="34" class="sk-body"/><text x="260" y="37" text-anchor="middle" class="sk-t acc">P</text><rect x="80" y="110" width="80" height="34" class="sk-body"/><text x="120" y="132" text-anchor="middle" class="sk-t">G</text><rect x="360" y="110" width="80" height="34" class="sk-body"/><text x="400" y="132" text-anchor="middle" class="sk-t">S</text><rect x="200" y="215" width="80" height="34" class="sk-body"/><text x="240" y="237" text-anchor="middle" class="sk-t">M8</text><rect x="330" y="215" width="70" height="34" class="sk-body"/><text x="365" y="237" text-anchor="middle" class="sk-t">Z</text><rect x="430" y="215" width="70" height="34" class="sk-body"/><text x="465" y="237" text-anchor="middle" class="sk-t">B</text><line x1="120" y1="110" x2="248" y2="51" class="sk-l" marker-end="url(#ar)"/><line x1="400" y1="110" x2="272" y2="51" class="sk-l" marker-end="url(#ar)"/><line x1="232" y1="215" x2="128" y2="146" class="sk-l" marker-end="url(#ar)"/><line x1="248" y1="215" x2="385" y2="146" class="sk-l" marker-end="url(#ar)"/><line x1="365" y1="215" x2="392" y2="146" class="sk-l" marker-end="url(#ar)"/><line x1="465" y1="215" x2="418" y2="146" class="sk-l" marker-end="url(#ar)"/><text x="172" y="72" text-anchor="middle" class="sk-t acc">1</text><text x="348" y="72" text-anchor="middle" class="sk-t acc">2</text><text x="165" y="190" text-anchor="middle" class="sk-t acc">6</text><text x="300" y="170" text-anchor="middle" class="sk-t acc">4</text><text x="366" y="186" text-anchor="middle" class="sk-t acc">1</text><text x="452" y="186" text-anchor="middle" class="sk-t acc">1</text><text x="10" y="280" class="sk-t">P Vorrichtung, G Grundplatte, S Spanneinheit, Z Zylinder, B Backe</text><text x="10" y="298" class="sk-t acc">Bedarf 150 P: M8 = 150 · 6 + 300 · 4 = 2 100 Stück</text>'}},
    {bsp:{t:'Beispiel: Stücklistenauflösung für 150 Spannvorrichtungen',b:['Aufbau: 1 Vorrichtung P = 1 Grundplatte G + 2 Spanneinheiten S; G enthält 6 Schrauben M8; S enthält 1 Zylinder Z, 1 Backe B, 4 Schrauben M8','Grundplatten: 150 · 1 = 150','Spanneinheiten: 150 · 2 = 300 → Zylinder 300, Backen 300','Schrauben M8: 150 · 6 + 300 · 4 = 900 + 1 200 = 2 100','Nettobedarf = Bruttobedarf − verfügbarer Bestand; z. B. 2 100 − 650 M8 am Lager = 1 450 zu bestellen (Verpackungseinheit beachten).']}},
    {merke:'Bruttobedarf aus Stückliste, Nettobedarf nach Abzug des verfügbaren Bestands – erst der Nettobedarf wird bestellt.'}
  ]},
  {t:'Lagerbestände optimieren',h:'Optimierung der Lagerbestände',pg:118,abb:[['Abb. 7.4 Optimale Bestellmenge',119],['Abb. 7.5 Bestellrhythmusverfahren',120]],b:[
    {p:'Bestände kosten Geld: Zinsen auf gebundenes Kapital, Lagerplatz, Personal, Schwund und Veralterung. Gleichzeitig verursachen zu viele kleine Bestellungen hohe Bestellkosten. Ziel sind minimale Gesamtkosten bei sicherer Versorgung.'},
    {ul:['Feste Lagerordnung: jedes Gut hat seinen Platz – übersichtlich, aber Platz für den Maximalbestand nötig','Freie (chaotische) Lagerordnung: jeder freie Platz wird genutzt – beste Raumausnutzung, nur mit EDV-Platzverwaltung']},
    {tab:[['Klasse','Wertanteil','Mengenanteil','Disposition'],['A','ca. 70–80 %','ca. 10–20 %','genau planen, kleine Bestände, häufige Lieferungen, Preisverhandlung'],['B','ca. 15 %','ca. 30 %','normale Disposition'],['C','ca. 5–10 %','ca. 50–70 %','vereinfacht, größere Lose, Kanban, Konsignation']]},
    {svg:{w:520,h:255,cap:'ABC-Analyse (Lorenzkurve): wenige A-Teile tragen den Großteil des Verbrauchswerts',body:'<line x1="60" y1="225" x2="505" y2="225" class="sk-l" marker-end="url(#ar)"/><line x1="60" y1="225" x2="60" y2="20" class="sk-l" marker-end="url(#ar)"/><text x="500" y="245" text-anchor="end" class="sk-t">Mengenanteil kumuliert</text><text x="68" y="25" class="sk-t">Wertanteil kumuliert</text><path d="M60,225 L81,139.5 L102,92 L144,65.4 L186,54 L270,44.5 L375,38.80000000000001 L480,35" class="sk-f"/><line x1="102" y1="92" x2="102" y2="225" class="sk-c"/><line x1="186" y1="54" x2="186" y2="225" class="sk-c"/><line x1="60" y1="92" x2="102" y2="92" class="sk-c"/><line x1="60" y1="54" x2="186" y2="54" class="sk-c"/><text x="54" y="97" text-anchor="end" class="sk-t">70 %</text><text x="54" y="59" text-anchor="end" class="sk-t">90 %</text><text x="102" y="243" text-anchor="middle" class="sk-t">10 %</text><text x="186" y="243" text-anchor="middle" class="sk-t">30 %</text><text x="89.4" y="177.5" text-anchor="middle" class="sk-t acc">A</text><text x="144" y="139.5" text-anchor="middle" class="sk-t acc">B</text><text x="333" y="111" text-anchor="middle" class="sk-t acc">C</text><line x1="60" y1="225" x2="480" y2="35" class="sk-c"/>'}},
    {ul:['XYZ-Analyse nach Vorhersagbarkeit: X konstanter Verbrauch, Y Trend oder Saison, Z unregelmäßig','Kombination ABC/XYZ: AX-Teile eignen sich für fertigungssynchrone Anlieferung, CZ-Teile eher für Vorrat oder Bestellung bei Bedarf']},
    {fx:['x_opt = √( 2 · x_Bed · k_B / (EP · i_L) )','Andler’sche Formel; x_Bed Periodenbedarf, k_B fixe Kosten je Bestellung, EP Einstandspreis, i_L Lagerhaltungskostensatz als Dezimalzahl']},
    {svg:{w:520,h:260,body:'<line x1="60" y1="230" x2="495" y2="230" class="sk-l" marker-end="url(#ar)"/><line x1="60" y1="230" x2="60" y2="15" class="sk-l" marker-end="url(#ar)"/><text x="68" y="20" class="sk-t">Kosten</text><text x="490" y="252" text-anchor="end" class="sk-t">Bestellmenge</text><line x1="60" y1="230" x2="460" y2="90" class="sk-l"/><polyline points="100,90 120,137 140,160 180,183 220,195 300,207 380,212 460,216" class="sk-l"/><polyline points="100,76 120,116 140,132 180,141 186,141 220,139 300,123 380,101 460,76" class="sk-f"/><line x1="186" y1="141" x2="186" y2="230" class="sk-c"/><circle cx="186" cy="141" r="5" class="fillacc"/><text x="186" y="250" text-anchor="middle" class="sk-t acc">x opt</text><text x="300" y="80" class="sk-t acc">Gesamtkosten</text><text x="400" y="150" text-anchor="middle" class="sk-t">Lagerhaltungskosten</text><text x="200" y="215" text-anchor="middle" class="sk-t">Bestellkosten</text>',cap:'Optimale Bestellmenge im Minimum der Gesamtkosten'}},
    {bsp:{t:'Beispiel: Optimale Bestellmenge für Lagerbuchsen',b:['Gegeben: Jahresbedarf 12 000 Stück, Bestellkosten 60 € je Bestellung, Einstandspreis 4 €, Lagerhaltungskostensatz 20 % = 0,20','x_opt = √(2 · 12 000 · 60 / (4 · 0,20)) = √(1 440 000 / 0,8) = √1 800 000 = 1 341,6 ≈ 1 342 Stück','Bestellungen pro Jahr: 12 000 / 1 342 ≈ 9','Praxis: Lieferant bietet ab 2 000 Stück 3 % Rabatt → Gesamtkosten beider Varianten vergleichen, nicht nur die Formel anwenden.']}},
    {ul:['Gründe, von x_opt abzuweichen: Mengenrabatt oder Bonus, Nachfrageschwankungen, fehlender Lagerplatz, Liquidität, Veralterungs- oder Verderbrisiko, Verfügbarkeit, Zuverlässigkeit des Lieferanten','Bestandsbegriffe: Lagerbestand (physisch vorhanden), verfügbarer Bestand (+ offene Bestellungen − Reservierungen), Sicherheitsbestand (Puffer, im Normalfall nie angreifen), Meldebestand (löst Bestellung aus), Höchstbestand, Wiederbeschaffungszeit (Bestellung bis Eingang), Reichweite (vom Meldebestand bis Null bei Durchschnittsverbrauch)']},
    {fx:['Meldebestand = Tagesbedarf · Wiederbeschaffungszeit + Sicherheitsbestand','Bestellpunktverfahren']},
    {svg:{w:520,h:255,body:'<line x1="40" y1="220" x2="380" y2="220" class="sk-l" marker-end="url(#ar)"/><line x1="40" y1="220" x2="40" y2="15" class="sk-l" marker-end="url(#ar)"/><text x="48" y="20" class="sk-t">Bestand</text><text x="370" y="242" text-anchor="end" class="sk-t">Zeit</text><line x1="40" y1="40" x2="380" y2="40" class="sk-c"/><line x1="40" y1="120" x2="380" y2="120" class="sk-c"/><line x1="40" y1="180" x2="380" y2="180" class="sk-c"/><text x="385" y="45" class="sk-t">Höchstbestand</text><text x="385" y="125" class="sk-t acc">Meldebestand</text><text x="385" y="185" class="sk-t">Sicherheitsbestand</text><polyline points="40,40 150,180 150,40 260,180 260,40 370,180" class="sk-l thick"/><circle cx="103" cy="120" r="5" class="fillacc"/><line x1="103" y1="120" x2="103" y2="205" class="sk-c"/><line x1="103" y1="205" x2="148" y2="205" class="sk-f" marker-end="url(#ar)"/><text x="100" y="242" class="sk-t">Wiederbeschaffungszeit</text>',cap:'Bestellpunktverfahren: Bestellung bei Meldebestand, Lieferung bevor der Sicherheitsbestand angegriffen wird'}},
    {bsp:{t:'Beispiel: Meldebestand festlegen',b:['Gegeben: Jahresbedarf 12 000 Stück bei 240 Arbeitstagen → 50 Stück/Tag; Wiederbeschaffungszeit 6 Tage; Sicherheitsbestand 150 Stück','Meldebestand = 50 · 6 + 150 = 450 Stück','Mit x_opt = 1 342 ergibt sich ein Höchstbestand von ca. 150 + 1 342 = 1 492 Stück (bei Eingang genau zum Erreichen des Sicherheitsbestands).']}},
    {merke:'Die optimale Bestellmenge liegt im Minimum der Summe aus Bestell- und Lagerhaltungskosten; Bestellkosten sinken, Lagerkosten steigen mit der Menge.'},
    {falle:'Lagerhaltungskostensatz als Dezimalzahl einsetzen (20 % = 0,20) – sonst wird x_opt um den Faktor 10 falsch.'}
  ]},
  {t:'Lagerbedingungen und Ersatzteillagerung',h:'Produktspezifische Anweisungen · Maßnahmen für geeignete Lagerräume · Lagerung von Ersatzteilen für Maschinen und Anlagen',pg:120,b:[
    {p:'Lagergut muss so gelagert werden, dass es keinen Schaden nimmt und Beschäftigte geschützt sind. Ersatzteile sichern die Anlagenverfügbarkeit – fehlt ein Teil, laufen Fixkosten ohne Ertrag weiter, Lieferverzug droht bis zum Kundenverlust.'},
    {ul:['Produktspezifisch: Sauberkeit (verschmutzte Schmierstoffe schädigen Maschinen), Hygiene (Lebensmittel, Medizinprodukte), Temperatur, Luftfeuchte (Korrosion), Arbeitsschutz','Gefahrstoffe nach GefStoffV und TRGS 510 (Zusammenlagerung, Mengen, Lüftung, Brandschutz); wassergefährdende Stoffe mit Auffangwanne (AwSV)','Lagerraum vorab prüfen: direkte Sonne (UV schädigt Kunststoffe und Gummi), Temperaturwechsel (Kondenswasser), ggf. Klimatisierung; bei manchen Gütern auch Sauerstoffgehalt']},
    {tab:[['Ersatzteilart','Merkmal','Bevorratung'],['anlagenspezifische Einzelteile','nur für diese Maschine gefertigt, lange Lieferzeit','bei kritischen Anlagen vorhalten'],['Baugruppen','vormontiert, schneller Tausch','für Engpassanlagen'],['Normteile','in allen Einzelheiten genormt, herstellerübergreifend','meist kurzfristig beschaffbar, wenig Bestand'],['Verschleißteile','vorhersehbarer Verbrauch','vorrangig bevorraten']]},
    {svg:{w:520,h:300,cap:'Bevorratungsentscheidung für Ersatzteile nach Ausfallfolgen und Wiederbeschaffungszeit',body:'<line x1="90" y1="255" x2="505" y2="255" class="sk-l" marker-end="url(#ar)"/><line x1="90" y1="255" x2="90" y2="15" class="sk-l" marker-end="url(#ar)"/><text x="300" y="290" text-anchor="middle" class="sk-t">Wiederbeschaffungszeit</text><text x="98" y="22" class="sk-t">Ausfallfolgen</text><text x="195" y="275" text-anchor="middle" class="sk-t">kurz</text><text x="405" y="275" text-anchor="middle" class="sk-t">lang</text><text x="82" y="85" text-anchor="end" class="sk-t">hoch</text><text x="82" y="200" text-anchor="end" class="sk-t">gering</text><rect x="100" y="30" width="190" height="105" class="sk-body"/><text x="195" y="69.5" text-anchor="middle" class="sk-t">Mindestbestand</text><text x="195" y="87.5" text-anchor="middle" class="sk-t">oder Konsignations-</text><text x="195" y="105.5" text-anchor="middle" class="sk-t">lager</text><rect x="300" y="30" width="195" height="105" class="sk-body"/><text x="397.5" y="78.5" text-anchor="middle" class="sk-t acc">im eigenen Lager</text><text x="397.5" y="96.5" text-anchor="middle" class="sk-t">bevorraten</text><rect x="100" y="145" width="190" height="105" class="sk-body"/><text x="195" y="193.5" text-anchor="middle" class="sk-t">nicht lagern,</text><text x="195" y="211.5" text-anchor="middle" class="sk-t">bei Bedarf kaufen</text><rect x="300" y="145" width="195" height="105" class="sk-body"/><text x="397.5" y="193.5" text-anchor="middle" class="sk-t">Rahmenvertrag,</text><text x="397.5" y="211.5" text-anchor="middle" class="sk-t">Lieferzeit sichern</text>'}},
    {ul:['Standortfrage (beim Hersteller oder beim Betreiber) hängt ab von Verfügbarkeit, Teilewert, Lagerkosten und davon, ob eigenes Personal oder der Herstellerservice instand setzt','Ersatzteile schnell auffindbar und geschützt lagern; in Abständen auf Funktion und Alterung prüfen; bei Verkauf oder Verschrottung einer Maschine zugehörige Teile mit abgeben','Konsignationslager: Lieferant richtet beim Kunden ein Lager ein, Ware bleibt sein Eigentum, Berechnung erst bei Entnahme; Kunde stellt Platz und Versicherung; Vorteile Versorgungssicherheit und geringe Kapitalbindung','Just-in-time (fertigungssynchron): Rahmenvertrag über eine Periode, Lieferung bei Bedarf; sehr niedrige Lagerkosten, aber hoher Abstimmungsaufwand und Risiko bei Lieferausfall (Streik, Unfall)','Additive Fertigung (3D-Druck) direkt aus CAD-Daten: Ersatzteile bei Bedarf statt auf Vorrat, Prototypen, komplexe Geometrien (Rapid Manufacturing, Rapid Tooling); Nachteile Nacharbeit für Toleranzen und Oberfläche, lange Bauzeiten']},
    {bsp:{t:'Beispiel: Ersatzspindel bevorraten – ja oder nein?',b:['Gegeben: Motorspindel 18 000 €, Lieferzeit 8 Wochen; Ausfallkosten der Engpassmaschine ca. 5 000 € pro Tag; kalkulatorischer Zins- und Lagerkostensatz 10 %','Kosten der Bevorratung: 18 000 € · 0,10 = 1 800 € pro Jahr','Ein einziger Ausfall ohne Ersatz: 8 Wochen à 5 Arbeitstage · 5 000 € = 200 000 € (ohne Ausweichfertigung)','Entscheidung: bevorraten. Alternative prüfen: Konsignation beim Hersteller oder gemeinsame Bevorratung mit einem Schwesterwerk.']}},
    {merke:'Bei Ersatzteilen zählt die Verfügbarkeit mehr als die Lagerkosten – kritische Teile mit langer Lieferzeit gehören ins Lager, Normteile nicht.'},
    {falle:'Proportionalventile und herstellerspezifische Elektronik nur baugleich bevorraten; ein „gleichwertiges“ Fremdteil passt mechanisch, funktioniert aber nicht mit der Ansteuerung.'}
  ]}
 ]};
